// ==========================================
// ★ K 의 방 — A등급 직업 갈림길 · 연결
// 협상가 · 결속술사 · 견습 기사 · 신호수 · 표사
// 연결: 부르는 것 앞에서 손을 놓지 않는다 — 끌려가는 사람을 붙드는 쪽
// ==========================================

// ------------------------------------------
// 협상가 · 자원 없음
// ------------------------------------------
kJob('negotiator', 'A', [

{ at:'A', t:'복도 — 하나만 달라는 목소리',
  x:`복도 끝 어둠에서 목소리가 난다. 낮고 친절하다.<br><br>
    <span style="color:#8fb3bf;">"하나만 두고 가면 나머지는 보내 줄게."</span><br>
    값을 먼저 부르는 쪽은 대개 급한 쪽이다. 그런데 이 목소리는 급하지 않다. 몇 번이고 같은 말을 같은 박자로 한다.<br><br>
    협상가는 안다. 서두르지 않는 상대는 이미 값을 받아 본 적이 있다. 여러 번.<br>
    팀원 하나가 이쪽 소매를 쥔다. 손이 젖어 있다.`,
  o:[
    { l:'① 하나 대신 무엇을 받겠느냐고 되묻는다.', k:'bond', dc:23,
      doom:{ title:'되물은 값', what:'목소리에게 복도 끝으로 끌려갑니다', dc:18, sec:50,
        text:`무엇이면 되겠느냐고 물었다. 사람 말고.<br><br>목소리가 처음으로 쉬었다. 그리고 웃었다. 흥정에 응한 사람은 처음이라고.<br>이쪽 발목에 무엇이 감긴다. 차고 가늘다. <span style="color:#8fb3bf;">"흥정할 줄 아는 하나면 돼."</span><br><br>발이 바닥을 미끄러진다. 복도 끝 쪽으로. 값을 물은 사람이 값이 됐다.`,
        dieText:`팀원들이 손전등을 비췄을 때 복도 끝에는 벽뿐이었다.<br><br>벽 아래 신발 한 짝이 가지런히 놓여 있었다. 끈이 묶인 채로.<br>그 뒤로 복도를 지날 때마다 목소리가 말한다. 하나 더 두고 가면 그 하나를 돌려주겠다고. 이번에는 조금 급하게.` },
      ok:`무엇이면 되겠느냐고 물었다. 사람 말고.<br><br>목소리가 오래 쉬었다. 대답 대신 바닥에서 무엇이 기어 와 이쪽 발끝을 만졌다. 차다. 값을 재는 손길이다.<br>등불을 내밀었다. 손길이 등불 쪽으로 옮겨 간다. 불을 감싸고 어둠으로 물러났다.<br><br>남은 등불 하나로 복도를 지났다. 값은 치렀다. 무엇을 치렀는지는 불이 꺼진 뒤에야 알았다. 어둠이 한 칸 더 짙어졌다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 대답하지 말라고 하고 팀을 한 줄로 붙인다.', k:'steady', dc:22,
      ok:`입을 열지 말라고 손으로 일렀다. 앞사람 허리끈을 뒷사람이 쥐게 했다.<br><br>목소리가 같은 값을 다섯 번 불렀다. 여섯 번째엔 값이 내려갔다. 반만 두고 가라고.<br>대꾸하지 않았다. 흥정은 받아 주는 쪽이 있어야 흥정이다. 아무도 받지 않으면 그냥 소리다.<br><br>복도 끝을 지날 때 목소리는 혼잣말을 하고 있었다. 숫자를 세고 있었다.`,
      ng:`줄을 붙이는 사이 맨 뒤 팀원이 대답했다. 작게. 무엇을 주면 되느냐고.<br><br>목소리가 반가워한다. 그 팀원의 무릎이 꺾였다. 다 같이 붙들어 일으켰다.<br>그 뒤로 그 팀원은 걸을 때마다 뒤를 돌아본다. 아직 값을 덜 치른 사람처럼.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-22 } },
    { l:'③ 값은 나갈 때 정하자고 하고 흥정을 미룬다.', k:'bond', dc:22, wake:1,
      ok:`지금은 못 정한다고 했다. 나갈 때, 몇이 남았는지 보고 정하자고.<br><br>목소리가 멈칫한다. 미뤄진 흥정은 상대를 붙잡아 둔다. 기다리는 쪽은 손을 못 쓴다. 다 끝나지 않은 셈 앞에서 손을 대면 그 셈이 깨지니까.<br>복도를 다 지날 때까지 목소리는 따라오기만 했다. 손은 안 뻗었다.<br><br>정하지 않은 값으로 상대를 묶었다. 값을 정하는 것보다 정하지 않고 붙들어 두는 쪽이 더 오래 간다. 혀끝에 새 버릇이 생겼다. 끝맺지 않는 말.`,
      ng:`미루자고 하자 목소리가 웃는다. 미루면 이자가 붙는다고.<br><br>그 말이 끝나자 팀원 하나가 코피를 쏟았다. 멈추지 않는다.<br>한참 눌러서 겨우 멎었다. 이자는 벌써 받아 갔다.`,
      win:{ exp:22, dream:3, mind:6 }, lose:{ hp:-24, spirit:-18 } }
  ] },

{ at:'A', t:'쉬는 자리 — 여섯째 몫',
  x:`쉬는 자리에서 먹을 것을 나눴다. 다섯이다. 다섯 몫으로 갈랐다.<br><br>
    고개를 들어 보니 무더기가 여섯이다.<br>
    아무도 여섯으로 자르지 않았다. 여섯째 무더기는 조금 작다. 막내 몫만 하다.<br><br>
    몫을 보면 누가 낄 자리를 노리는지 보인다. 여섯째는 먹으려고 놓인 게 아니다. 자리를 받으려고 놓였다.`,
  o:[
    { l:'① 여섯째 몫을 문 밖에 내놓고 자리는 안 내준다.', k:'bond', dc:22, wake:1,
      ok:`여섯째 무더기를 들어 문 밖 어둠에 놓았다. 그리고 문 안쪽에 앉았다.<br><br>몫은 준다. 자리는 안 준다. 둘을 갈라서 흥정했다.<br>밤새 문 밖에서 무엇이 씹는 소리가 났다. 아주 천천히. 문 안으로는 한 번도 안 들어왔다.<br><br>아침에 문 밖은 비어 있었다. 무더기 자리에 작은 손자국 하나. 받은 것을 받았다는 표시다.<br>값과 자리를 떼어 내는 법. 나누는 셈이 한 갈래 더 늘었다.`,
      ng:`들어서 내놓는데 무더기가 손에서 무겁다. 들수록 무거워진다.<br><br>문 밖에 놓기 전에 손을 놓쳤다. 무더기가 문턱에 쏟아졌다.<br>문턱은 안도 밖도 아니다. 그날 밤 문턱에 누가 앉아 있었다. 다섯이 다 그쪽을 보고 밤을 샜다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 여섯을 섞어 다시 다섯으로 나눈다.', k:'fix', dc:23,
      ok:`여섯 무더기를 한데 모았다. 다시 다섯으로 갈랐다. 하나하나 손으로 들어 무게를 맞췄다.<br><br>다 갈랐는데 또 여섯이다. 다시 모았다. 다시 갈랐다.<br>네 번째에 다섯이 됐다. 그 대신 팀원들 몫이 다 조금씩 줄었다. 여섯째가 먹은 만큼.<br><br>먹었다. 다 먹고 나서도 배가 덜 찼다. 그래도 자리는 다섯이다.`,
      ng:`모아서 다시 가르는데 손이 하나 더 있다. 이쪽 손 사이에 끼어 같이 가른다.<br><br>작고 차다. 손을 털었다. 무더기가 흩어졌다.<br>아무도 먹지 않았다. 배고픈 채로 잤다. 꿈에서 누가 자꾸 숫자를 세었다.`,
      win:{ exp:16, dream:2, item:'말린 고기' }, lose:{ hp:-22, mind:-16 } }
  ] },

{ at:'A', t:'계단참 — 두고 가려는 팀',
  x:`다른 팀이 계단참에서 쉰다. 넷이 한쪽에 모였고 하나가 떨어져 앉았다.<br><br>
    떨어진 하나는 벽에 귀를 대고 있다. 누가 부른다고 한다. 대답하고 싶다고 한다.<br>
    그쪽 반장이 이쪽에 다가와 낮게 말한다. 저 사람을 두고 가겠다고. 데려가면 다 같이 불린다고.<br><br>
    두고 가겠다는 말에도 값이 붙어 있다. 반장 눈이 이쪽 짐을 본다.`,
  o:[
    { l:'① 저 사람은 이쪽이 데려가겠다고 한다.', k:'bond', dc:23, wake:1,
      ok:`데려가겠다고 했다. 값은 안 받는다고.<br><br>반장이 놀란다. 그리고 안도한다. 두고 가는 짐을 남이 들어 주면 두고 간 게 아니게 된다.<br>떨어진 사람 손목을 이쪽 팀원 손목에 묶었다. 귀를 벽에서 떼게 하고 계속 말을 걸었다. 먹은 것, 온 길, 이름 말고 다른 것.<br><br>그 사람은 다음 층에서 처음으로 이쪽 말에 대답했다. 벽 대신.<br>부르는 것보다 먼저, 더 자주 말을 걸면 된다. 귀는 하나다. 먼저 차지하는 쪽이 이긴다. 그 셈이 몸에 붙었다.`,
      ng:`데려가겠다고 하자 반장이 고개를 젓는다. 남에게 넘기면 그쪽 팀이 불린다고. 이미 해 봤다고.<br><br>다투는 사이 떨어진 사람이 일어섰다. 벽을 따라 걸어간다. 계단 아래로.<br>반장도 이쪽도 따라가지 않았다. 따라갔어야 했다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-20, spirit:-26 } },
    { l:'② 반장이 정말 원하는 게 뭔지 본다.', k:'gaze', dc:22,
      ok:`반장 얼굴을 봤다. 두고 가겠다는 사람 얼굴이 아니다. 누가 말려 주기를 기다리는 얼굴이다.<br><br>말렸다. 두고 가면 그쪽 팀은 내려가는 내내 뒤를 돌아볼 거라고. 넷이 다 불리는 건 그때라고.<br>반장이 숨을 내쉰다. 그 사람에게 가서 손을 잡았다.<br><br>반장은 처음부터 데려가고 싶었다. 혼자서는 그 말을 못 했을 뿐이다.`,
      ng:`보는 걸 반장이 알아챘다. 얼굴이 굳는다.<br><br>남의 팀 셈에 끼는 사람은 그 셈의 일부가 된다. 반장이 이쪽을 밀쳤다. 난간에 허리를 찧었다.<br>그쪽 팀은 그 사람을 두고 내려갔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-14 } }
  ] },

{ at:'A', t:'잠긴 문 — 안쪽의 조건',
  x:`문이 잠겼다. 손잡이를 돌리자 안에서 똑같이 돌린다. 반대 방향으로.<br><br>
    문틈으로 말이 새어 나온다. 열어 줄 수 있다고. 이름 하나만 말해 주면.<br>
    누구 이름이든 상관없다고 한다. 여기 없는 사람 이름이어도.<br><br>
    상관없다는 조건이 제일 위험하다. 아무 이름이나 받는 쪽은 받은 이름으로 무엇을 할지 이미 정해 둔 쪽이다.`,
  o:[
    { l:'① 이름 대신 다른 것을 걸자고 문틈에 말한다.', k:'bond', dc:23,
      doom:{ title:'문틈의 조건', what:'문틈 안으로 끌려 들어갑니다', dc:18, sec:50,
        text:`이름은 안 된다고 했다. 대신 물이나 불을 주겠다고.<br><br>문틈 안쪽이 조용해진다. 그리고 손가락 하나가 틈으로 나와 이쪽 입술을 짚었다.<br><span style="color:#8fb3bf;">"이름은 여기 있잖아."</span><br><br>문이 아주 조금 열린다. 사람 하나 겨우 들어갈 만큼. 입술을 짚은 손이 턱을 쥐고 당긴다.`,
        dieText:`문은 다시 닫혔다. 잠기지는 않았다.<br><br>팀원들이 열었다. 안은 텅 빈 벽장이다. 옷걸이 하나에 이쪽 겉옷이 걸려 있다.<br>주머니에 종이가 들었다. 이쪽 이름이 적혀 있다. 이쪽 글씨로. 영수증처럼 아래에 줄이 그어져 있다.` },
      ok:`이름은 안 된다고 했다. 대신 물이나 불을 주겠다고.<br><br>문틈 안쪽이 오래 조용했다. 그러다 물 쪽을 골랐다. 물주머니를 틈에 대고 짰다. 틈이 물을 마신다. 끝까지.<br>자물쇠가 저절로 풀렸다. 열고 들어가니 텅 빈 벽장이다. 반대쪽 벽에 다른 문이 있다. 아래층으로 가는 문.<br><br>물주머니는 바싹 말라 있었다. 안쪽까지. 오래 목이 말랐던 것이다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 조건을 거절하고 돌아갈 길을 찾는다.', k:'sense', dc:22,
      ok:`대꾸하지 않고 문에서 물러났다. 손잡이도 놓았다.<br><br>복도를 되짚어 벽을 더듬었다. 환기구 덮개 하나가 헐겁다. 기어서 지나갈 만하다.<br>기어가는 동안 등 뒤 문에서 손잡이 돌아가는 소리가 오래 났다. 이쪽 방향으로. 이제 와서 열어 주겠다고.`,
      ng:`물러나서 다른 길을 찾았다. 돌아오는 길은 다 그 문 앞으로 이어진다.<br><br>세 번째로 문 앞에 섰을 때 문틈의 말이 바뀌어 있었다. 이름 둘.<br>값이 올랐다. 거절한 만큼.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-22 } }
  ] },

{ at:'A', t:'복도 구석 — 팀원이 맺은 거래',
  x:`팀원 하나가 구석에서 혼잣말을 한다. 작게. 고개를 끄덕이며.<br><br>
    다가가니 입을 다문다. 아무것도 아니라고 한다. 손에 무엇을 쥐었다. 열쇠다. 이 층 계단문 열쇠.<br>
    어디서 났느냐고 물으니 받았다고 한다. 나중에 갚기로 했다고.<br><br>
    남이 맺은 거래는 냄새로 안다. 이 거래는 갚을 날짜가 정해지지 않았다. 그런 거래가 제일 비싸다.`,
  o:[
    { l:'① 그 거래를 이쪽이 넘겨받겠다고 어둠에 말한다.', k:'bond', dc:23, wake:1,
      ok:`구석 어둠에 대고 말했다. 이 사람 빚은 이쪽이 지겠다고. 이 팀의 셈은 이쪽이 한다고.<br><br>어둠이 한동안 이쪽을 잰다. 팀원 어깨에서 무엇이 내려가는 게 보였다. 축축한 자국이 남는다.<br>그 무게가 이쪽 어깨로 왔다. 무겁다. 그래도 이쪽은 이 무게를 셀 줄 안다. 팀원은 몰랐다.<br><br>빚을 대신 지는 일은 처음이다. 남의 거래를 받아 들 때 손이 어떻게 움직여야 하는지 알았다. 받는 쪽이 조건을 다시 읽는다. 날짜 칸에 이쪽이 날짜를 적었다. 나가는 날.`,
      ng:`넘겨받겠다고 했다. 어둠이 거절한다. 팀원 어깨의 것이 더 꽉 쥔다.<br><br>팀원이 비명을 지르며 주저앉았다. 어깨에 손가락 자국이 다섯 개.<br>열쇠는 그대로 쥐고 있다. 놓지 않는다. 빚이 남았으니까.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-22, spirit:-28 } },
    { l:'② 열쇠를 버리게 하고 거래를 끊는다.', k:'steady', dc:22,
      ok:`열쇠를 빼앗아 구석에 던졌다. 거래는 없던 거라고 크게 말했다.<br><br>어둠 속에서 열쇠가 떨어지는 소리가 안 났다. 누가 받았다.<br>계단문은 다른 길로 돌아서 갔다. 오래 걸렸다. 팀원은 그 내내 미안해했다. 미안해할 수 있다는 게 다행이다.`,
      ng:`빼앗으려는데 팀원 손이 안 펴진다. 손가락이 열쇠에 붙은 것처럼.<br><br>억지로 폈다. 손톱 둘이 빠졌다. 열쇠는 결국 그 손에 남았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-28, mind:-14 } },
    { l:'③ 거래의 값이 무엇이었는지 끝까지 듣는다.', k:'gaze', dc:23,
      ok:`팀원에게 처음부터 다 말해 보라고 했다. 들은 말 그대로.<br><br>열쇠를 주는 대신 나중에 문 하나를 열어 달라고 했단다. 이쪽에서. 아무 문이나.<br>값이 사람이 아니라 문이었다. 그럼 열지 않으면 된다. 팀원 손목에 끈을 감았다. 문고리를 잡으려 할 때마다 당기라고 다른 팀원에게 쥐여 줬다.`,
      ng:`듣는 사이 팀원 말투가 바뀐다. 다른 사람 말투로.<br><br>거래 상대가 직접 말하고 있었다. 팀원 입으로. 그 말을 끝까지 듣고 말았다. 귀에서 한참 물소리가 났다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-18 } }
  ] },

{ at:'A', t:'검은 유리 — 이쪽 얼굴의 흥정',
  x:`벽에 검은 유리가 끼워져 있다. 창인지 거울인지 모른다.<br><br>
    이쪽 얼굴이 비친다. 입이 움직인다. 이쪽은 입을 다물고 있다.<br>
    유리 속 얼굴은 손바닥을 펴고 무엇을 센다. 하나, 둘. 그리고 고개를 젓는다. 하나를 접는다.<br><br>
    흥정하는 손이다. 저 손놀림은 낯익다. 이쪽 손이니까. 유리 속 이쪽이 누군가와 이쪽 팀을 놓고 값을 매기고 있다.`,
  o:[
    { l:'① 입 모양을 끝까지 읽어 무슨 흥정인지 안다.', k:'gaze', dc:23,
      doom:{ title:'유리 속의 셈', what:'검은 유리 속으로 끌려 들어갑니다', dc:18, sec:50,
        text:`입 모양을 따라 읽었다. 다섯. 아니, 넷. 넷이면 되겠다고.<br><br>누가 빠지는지 보려고 유리에 얼굴을 댔다. 유리 속 얼굴이 이쪽 이마에 이마를 댔다. 차다.<br>그쪽 손이 이쪽 손목을 쥔다. 유리를 뚫고. 흥정은 끝났다. 빠지는 하나는 흥정한 사람이다.<br><br>손목부터 유리 안으로 들어간다. 물속처럼 저항이 없다.`,
        dieText:`팀원들이 남은 다리를 잡아당겼다. 유리가 놓아주지 않았다.<br><br>검은 유리에는 이제 다섯이 비친다. 밖에 선 넷과, 안에서 손바닥을 펴고 무엇을 세는 하나.<br>다음 날 같은 복도를 지난 다른 팀이 유리 앞에 멈췄다. 유리 속 사람이 그쪽 반장에게 손가락 넷을 펴 보였다.` },
      ok:`입 모양을 따라 읽었다. 다섯. 아니, 넷. 넷이면 되겠다고.<br><br>얼굴은 대지 않았다. 등 뒤의 팀원들을 손짓으로 불러 다섯이 다 유리 앞에 섰다.<br>유리 속에도 다섯이 서야 하는데 넷만 비친다. 유리 속 이쪽은 없다. 흥정하던 손만 허공에 떠서 갈 곳을 잃었다.<br><br>다섯이 한꺼번에 서면 하나를 빼는 셈을 못 한다. 손은 천천히 오므라들어 사라졌다.`,
      win:{ exp:22, dream:3, spirit:6 } },
    { l:'② 유리에 등을 돌리고 손바닥으로 팀원들 눈을 가린다.', k:'hide', dc:22,
      ok:`유리를 등지고 섰다. 팀원들에게 유리 쪽을 보지 말라고 했다. 손바닥으로 한 사람씩 눈을 가려 지나가게 했다.<br><br>흥정은 양쪽이 서로 볼 때 성립한다. 보지 않는 상대에게는 값을 못 부른다.<br>등 뒤에서 유리를 두드리는 소리가 났다. 손톱으로. 끝까지 돌아보지 않았다.`,
      ng:`가리는데 맨 끝 팀원이 손가락 틈으로 봤다.<br><br>유리 속 이쪽이 그 팀원에게 고개를 끄덕여 줬다. 팀원이 마주 끄덕였다. 뭔가에 동의했다.<br>그 팀원은 그 뒤로 이쪽 말을 잘 안 믿는다. 유리 속 쪽이 더 믿을 만하다고 한다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-20, spirit:-26 } }
  ] },

{ at:'A', t:'빈 방 — 울면 안 되는 곳',
  x:`문 위에 종이가 붙었다. 이 방에서는 소리를 내지 마시오. 글씨가 떨린다.<br><br>
    방 한가운데쯤 왔을 때 팀원 하나가 울기 시작했다. 소리 없이 어깨만. 곧 소리가 날 것이다.<br>
    천장 구석에서 무엇이 몸을 기울인다. 기다리고 있다.<br><br>
    큰 약속이 안 먹히는 때가 있다. 끝까지 참으라는 말은 지금 아무 값도 없다.`,
  o:[
    { l:'① 귀에 대고 숨 열 번만 참자고 한다.', k:'bond', dc:22, wake:1,
      ok:`귀에 입을 대고 말했다. 끝까지 말고. 숨 열 번만.<br><br>팀원이 고개를 끄덕인다. 하나, 둘. 손가락으로 같이 셌다. 열에 닿았을 때 다시 말했다. 열 번만 더.<br>다섯 번을 그렇게 했다. 쉰 번의 숨이 지나자 문이 보였다. 문밖에서 팀원은 크게 울었다. 이제는 괜찮다.<br><br>천장 구석의 것은 끝내 아무것도 못 들었다.<br>사람은 큰 값을 한 번에 못 치른다. 잘게 나누면 다 치른다. 흥정이 상대만이 아니라 이쪽 사람 안에서도 된다는 걸 알았다. 그 셈은 숨 단위로 한다.`,
      ng:`숨 열 번이라고 하자 팀원이 셋에서 무너졌다.<br><br>흐느낌이 새었다. 천장 구석이 내려온다. 팀원을 안고 바닥에 엎드렸다. 등 위로 무엇이 오래 지나갔다.<br>지나간 자리에 등이 얼었다. 며칠 동안 그 자리만 땀이 안 났다.`,
      win:{ exp:24, dream:3, mind:6 }, lose:{ hp:-22, mind:-18, spirit:-16 } },
    { l:'② 팀원 입을 손으로 막고 끌다시피 지나간다.', k:'steady', dc:23,
      ok:`팀원 입을 손바닥으로 막았다. 다른 팔로 허리를 감아 걸었다.<br><br>손바닥 안에서 울음이 진동한다. 소리는 안 샌다. 손바닥이 젖었다.<br>방을 나와 손을 뗐다. 팀원이 이쪽 손을 물었던 자국이 남았다. 미안하다고 한다. 괜찮다.`,
      ng:`막는데 팀원이 버둥거린다. 숨이 막힌 것이다.<br><br>손을 늦추자 울음이 터졌다. 천장 구석이 떨어져 내렸다. 둘이 같이 바닥을 굴렀다. 무엇이 이쪽 다리를 길게 긁고 다시 올라갔다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-30, mind:-14 } }
  ] },

{ at:'A', t:'통로 — 서로 세는 두 팀',
  x:`통로에서 다른 팀과 마주쳤다. 그쪽 반장이 손가락으로 그쪽 사람들을 센다. 여섯.<br><br>
    그쪽 사람은 다섯이다. 이쪽이 셌다. 다섯.<br>
    반장은 다시 센다. 여섯. 그쪽 사람들이 서로 얼굴을 본다. 아무도 남는 사람을 못 찾는다.<br><br>
    제 팀은 제가 못 센다. 협상가는 그걸 안다. 남의 셈이 정확할 때가 있다. 서로 아무것도 안 걸었을 때.`,
  o:[
    { l:'① 서로 상대 팀을 세어 주자고 한다.', k:'bond', dc:23, wake:1,
      ok:`이쪽이 그쪽을 세고 그쪽이 이쪽을 세자고 했다. 소리 내지 말고 손가락으로만.<br><br>이쪽이 그쪽을 셌다. 다섯. 그쪽 반장이 이쪽을 셌다. 손가락이 여섯에서 멈춘다. 이쪽 팀 맨 뒤를 가리킨다.<br>돌아보지 않았다. 다섯이 그쪽 팀 사이로 걸어 들어가 섞였다. 열한 명의 셈은 아무도 못 맞힌다.<br><br>섞인 채로 통로를 지났다. 다 지나서 떨어져 섰다. 그쪽 반장이 이쪽을 세고 끄덕였다. 다섯.<br>서로 아무것도 걸지 않은 흥정이 있다. 셈을 나눠 맡는 것. 그 모양이 손에 남았다.`,
      ng:`서로 세자고 했는데 그쪽 반장이 못 믿는다. 이쪽이 하나를 몰래 넘기려는 거라고.<br><br>다투는 사이 그쪽 셈이 일곱이 됐다. 그쪽 사람 하나가 비명을 질렀다. 누가 손을 잡았다고.<br>그 팀은 흩어져 뛰었다. 이쪽도 뛰었다. 넘어진 사람을 밟고 지나갔다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-24, mind:-20 } },
    { l:'② 그쪽이 먼저 지나가게 물러나 기다린다.', k:'hide', dc:22,
      ok:`벽에 붙어 길을 비켰다. 그쪽이 먼저 가라고 했다.<br><br>그쪽 다섯이 지나갔다. 그 뒤로 한 박자 늦게 무엇이 지나갔다. 발소리는 없고 바람만.<br>이쪽 셈은 다섯이다. 지나간 쪽의 셈은 모른다. 알고 싶지 않다.`,
      ng:`비켜섰는데 지나가는 그쪽 사람 하나가 이쪽 손을 잡고 간다. 놓지 않는다.<br><br>잡아당겨 겨우 뗐다. 그 사람은 돌아보지도 않았다. 손을 잡은 건 그 사람이 아니었다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-22 } }
  ] },

{ at:'A', t:'긴 계단 — 내려 주겠다는 손',
  x:`팀원 하나가 다리를 다쳤다. 계단은 아직 길다.<br><br>
    계단 난간 아래 어둠에서 손 하나가 올라온다. 하얗고 손바닥이 위를 본다. 받쳐 주겠다는 손이다.<br>
    그 손 옆에 글씨가 긁혀 있다. 무거운 짐은 맡기세요. 아래에서 돌려드립니다.<br><br>
    돌려준다는 말에 값이 빠져 있으면 다시 읽어야 한다. 무엇을 돌려주는지가 안 적혀 있다.`,
  o:[
    { l:'① 손에게 짐만 맡기고 사람은 안 된다고 못 박는다.', k:'bond', dc:23,
      doom:{ title:'맡긴 짐', what:'다친 팀원 대신 난간 아래로 끌려갑니다', dc:18, sec:55,
        text:`사람은 안 된다고 했다. 짐만. 배낭을 손바닥에 얹었다.<br><br>손이 배낭을 받는다. 그리고 배낭 끈을 타고 올라와 이쪽 손목을 쥔다. 맡긴 짐에는 맡긴 사람도 딸려 간다는 듯이.<br>몸이 난간 쪽으로 기운다. 다친 팀원이 이쪽 허리를 붙든다. 다리를 다친 사람이.<br><br>아래 어둠이 깊다. 손은 서두르지 않는다.`,
        dieText:`허리를 붙든 손이 미끄러졌다.<br><br>계단 맨 아래에서 팀원들이 배낭을 찾았다. 끈이 단정하게 묶여 있었다. 안에는 이쪽 신발이 들었다. 두 짝 다.<br>배낭 위에 글씨가 긁혀 있었다. 돌려드립니다.` },
      ok:`사람은 안 된다고 했다. 짐만. 배낭을 손바닥에 얹고 끈을 바로 놓았다.<br><br>손이 배낭을 받는다. 끈 끝을 더듬는다. 이쪽 손은 이미 거기 없다.<br>짐이 없으니 다친 팀원을 업을 수 있었다. 계단 맨 아래에 배낭이 놓여 있었다. 안이 축축했다. 그래도 다 있었다.<br><br>손에게도 지키는 조건이 있다. 정확하게 말하면 정확하게 지킨다.`,
      win:{ exp:22, dream:3, item:'맑은 물' } },
    { l:'② 손은 무시하고 다친 팀원을 직접 업는다.', k:'steady', dc:22,
      ok:`손을 보지 않고 팀원을 업었다. 난간에서 먼 쪽 벽에 붙어 내려갔다.<br><br>손이 계단 하나 아래마다 다시 올라와 있다. 같은 손이다. 같은 높이에서 기다린다.<br>스무 번을 지나쳤다. 맨 아래에서는 손이 없었다. 다리가 후들거려 한참 앉아 있었다.`,
      ng:`업고 내려가는데 무릎이 꺾였다. 손 쪽으로 기울었다.<br><br>손이 다친 팀원의 발목을 쓰다듬는다. 받으려는 게 아니라 재 보는 손길이다.<br>억지로 일어나 벽 쪽으로 붙었다. 그 뒤로 팀원 발목이 계속 차다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-32, spirit:-18 } }
  ] },

{ at:'A', t:'꺼진 불 — 성냥 파는 사람',
  x:`쉬는 자리에서 불이 꺼졌다. 성냥이 다 젖었다.<br><br>
    어둠 속에 누가 앉아 있다. 언제 왔는지 모른다. 성냥갑을 흔든다. 마른 소리가 난다.<br>
    <span style="color:#8fb3bf;">"한 개비에 한 마디."</span> 무엇이든 말해 주면 된다고 한다. 지나간 일 한 마디.<br><br>
    협상가는 말이 값인 거래를 제일 싫어한다. 말은 한 번 주면 못 돌려받는다.`,
  o:[
    { l:'① 말 대신 물건으로 값을 바꾸자고 한다.', k:'bond', dc:22,
      ok:`말은 못 준다고 했다. 대신 먹을 것을 주겠다고.<br><br>그 사람이 웃는다. 먹을 것은 필요 없다고. 그래도 성냥 한 개비를 내밀었다. 거래 말고 맛보기로.<br>불을 켰다. 그 사람이 앉았던 자리에 아무도 없다. 성냥갑만 있다. 개비가 꼭 다섯 개 남았다.<br><br>다섯 번 불을 켤 수 있다. 여섯 번째는 말로 사야 한다.`,
      ng:`물건으로 하자고 하는데 팀원이 먼저 말해 버렸다. 지나간 일 한 마디. 어릴 때 집 대문 색깔.<br><br>성냥 한 개비가 손에 들어왔다. 불은 잘 켜졌다.<br>그 팀원은 그 뒤로 집 대문 색을 기억하지 못한다. 몇 번을 물어도.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-22, spirit:-20 } },
    { l:'② 거절하고 어둠 속에서 서로 손을 잡고 앉아 있는다.', k:'steady', dc:23,
      ok:`거절했다. 다섯이 둥글게 앉아 손을 잡았다.<br><br>어둠 속에서 성냥갑 흔드는 소리가 밤새 났다. 점점 가까이.<br>손 다섯이 끝까지 안 풀렸다. 아침에 눈을 뜨니 다섯 손 가운데에 성냥갑이 놓여 있었다. 비어 있었다.`,
      ng:`손을 잡고 앉았는데 잡은 손이 여섯이다. 이쪽 왼손과 오른손이 둘 다 잡혀 있고, 무릎 위에 손이 하나 더 얹혔다.<br><br>털어 냈다. 무릎이 얼었다. 아침까지 아무도 못 잤다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-22, mind:-20 } },
    { l:'③ 그 사람의 손과 발을 본다.', k:'gaze', dc:23, wake:1,
      ok:`성냥갑을 쥔 손을 봤다. 손톱 밑이 까맣다. 숯이다. 그 사람도 불을 원한다.<br><br>파는 쪽도 사고 싶은 게 있다. 그걸 알면 판이 뒤집힌다. 이쪽 부싯돌을 꺼내 보였다. 이걸로 바꾸자고.<br>그 사람이 오래 부싯돌을 본다. 성냥갑을 통째로 내밀었다. 부싯돌을 쥐고 어둠으로 사라졌다. 어둠 저편에서 한 번 불꽃이 튀었다.<br><br>상대가 내미는 물건보다 상대 손톱 밑을 먼저 본다. 그 순서가 눈에 박혔다.`,
      ng:`손을 보려고 몸을 기울였다. 그 사람 발이 없다. 무릎 아래가 어둠에 녹아 있다.<br><br>보는 걸 들켰다. 그 사람이 성냥갑을 거두고 이쪽 얼굴 앞으로 다가온다. 입김이 차다.<br>정신을 차려 보니 아침이다. 그 사이 기억이 없다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'A1', t:'접수처 — 보호자 칸',
  x:`접수처 책상에 방청 신청서가 놓였다. 다섯 장. 이쪽 일행 수다.<br><br>
    이름 칸은 이미 채워져 있다. 이쪽 이름들이다. 어린애 글씨로.<br>
    보호자 칸도 채워져 있다. 다섯 장 다 같은 이름. 뭉치.<br><br>
    책상 뒤에 아무도 없다. 그런데 도장 찍는 소리가 난다. 탁, 탁. 한 장씩 차례로.<br>
    협상가는 남이 대신 쓴 서류를 그냥 두지 않는다. 고칠 수 있을 때 고친다.`,
  o:[
    { l:'① 보호자 칸을 줄 긋고 이쪽 이름을 적는다.', k:'bond', dc:23, wake:1,
      ok:`볼펜으로 뭉치에 줄을 그었다. 두 줄. 그 옆에 이쪽 이름을 적었다. 다섯 장 다.<br><br>도장 소리가 멈춘다. 책상 밑에서 무엇이 부스럭댄다. 털이 책상 다리를 스치는 소리.<br>정정 칸에 이쪽 지장을 찍었다. 고친 서류는 고친 사람 것이 된다. 책상 밑이 조용해졌다.<br><br>다섯 장을 접어 이쪽 품에 넣었다. 이 건물 안에서 다섯은 이제 이쪽이 데리고 온 아이들이다. 누가 데려가려면 이쪽에게 물어야 한다.<br>남이 정한 칸을 고쳐 쓰는 손. 서명 하나로 사람을 맡는 법이 손가락 끝에 붙었다.`,
      ng:`줄을 긋는데 볼펜이 안 나온다. 몇 번을 그어도 종이만 패인다.<br><br>책상 밑에서 털 뭉치가 올라온다. 갈색이다. 이쪽 손등을 쓰다듬는다. 따뜻하다. 그게 더 무섭다.<br>손을 빼고 물러났다. 신청서 다섯 장에 도장이 다 찍혀 있었다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-20, spirit:-26 } },
    { l:'② 신청서를 건드리지 않고 접수처를 돌아 지나간다.', k:'evade', dc:22,
      ok:`책상에서 먼 벽을 따라 돌아갔다. 신청서 쪽은 보지 않았다.<br><br>접수를 안 한 방청객은 방청객이 아니다. 그 셈을 믿었다.<br>계단 앞에서 돌아보니 책상 위 신청서가 한 장씩 바람에 날려 떨어지고 있었다. 받을 사람 없이.`,
      ng:`돌아가는데 접수처 종이 울렸다. 띵.<br><br>어디선가 박수 소리. 이쪽 일행 수만큼. 접수된 것이다. 안 했는데.<br>계단까지 가는 동안 등 뒤에서 털 스치는 소리가 따라왔다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-22, spirit:-20 } }
  ] },

{ at:'A1', t:'방청석 — 바람잡이의 상품',
  x:`방청석 맨 앞에 바람잡이가 섰다. 줄무늬 조끼. 웃는 입이 얼굴에 그려져 있다.<br><br>
    상품 상자를 흔든다. 앞으로 나와 볼 친구에게 준다고.<br>
    상자 안에서 소리가 난다. 사탕이 아니다. 무엇이 안에서 상자 벽을 두드린다.<br><br>
    팀원 하나의 손이 무릎 위에서 들썩인다. 들고 싶어 한다. 상품을 받는 길과 앞으로 나가는 길이 꼭 같은 길은 아니다.`,
  o:[
    { l:'① 상품만 받고 나가는 건 다음 순서로 미루자고 한다.', k:'bond', dc:23,
      doom:{ title:'다음 순서', what:'방청석 위로 손에서 손으로 실려 갑니다', dc:18, sec:50,
        text:`손을 들고 말했다. 상품은 받고 싶다고. 나가는 건 다음 순서에.<br><br>바람잡이가 크게 고개를 끄덕인다. 좋아요. 그럼 상품을 드리러 갈게요. 친구들이.<br>방청석 뒷줄에서 손들이 올라온다. 하얀 장갑들. 이쪽 겨드랑이 밑으로 들어와 들어 올린다.<br><br>몸이 의자에서 떠오른다. 손에서 손으로 넘겨진다. 무대 쪽으로. 다음 순서는 지금이다.`,
        dieText:`무대 위에서 박수가 났다. 크게.<br><br>팀원들이 방청석에서 고개를 들었을 때 무대에는 상품 상자 하나만 놓여 있었다. 리본이 새로 묶였다.<br>상자 벽을 안에서 두드리는 소리가 하나 늘었다. 박자가 이쪽 말버릇과 같다. 한 번 부르고, 기다리고, 깎아서 다시.` },
      ok:`손을 들고 말했다. 상품은 받고 싶다고. 나가는 건 다음 순서에. 그리고 덧붙였다. 상품은 앉은 자리에서 받는 게 방청 규칙 아니냐고.<br><br>바람잡이 웃는 입이 그대로 굳었다. 규칙을 들이밀면 저쪽도 규칙으로 답해야 한다.<br>상자가 방청석을 따라 손에서 손으로 넘어왔다. 하얀 장갑들이 옮겼다. 이쪽 무릎에 놓였다. 열지 않았다.<br><br>나갈 때까지 무릎에 얹고 갔다. 안에서 두드리는 소리가 계단마다 약해졌다. 맨 위층에서 멎었다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 손을 들려는 팀원 손목을 꽉 쥐어 무릎에 누른다.', k:'steady', dc:22,
      ok:`팀원 손목을 쥐고 무릎에 눌렀다. 다른 손으로 이쪽 손도 깔고 앉았다.<br><br>바람잡이가 방청석을 훑는다. 한 줄씩. 손 든 사람이 없다. 상자가 점점 조용해진다.<br>바람잡이가 다른 줄로 갔다. 저 뒤에서 누가 손을 들었다. 이쪽 팀이 아니다. 박수가 났다.`,
      ng:`누르는데 팀원 팔에 힘이 너무 세다. 이쪽 손째 올라간다.<br><br>두 손이 같이 들렸다. 바람잡이가 이쪽을 가리킨다. 두 친구!<br>억지로 팔을 끌어내렸다. 어깨가 빠지는 소리가 났다. 이쪽 어깨다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-28, mind:-16 } },
    { l:'③ 상품 상자가 놓였던 자리를 본다.', k:'luck', dc:22,
      ok:`바람잡이 발치를 봤다. 상자가 놓였던 자리에 다른 상자들이 있다. 지난 회차 것들. 리본이 다 풀렸다.<br><br>쉬는 시간에 그쪽으로 기어가 하나를 열었다. 빈 상자 바닥에 꿀 한 줌이 굳어 있었다. 촬영용 간식이다. 아직 달다.<br>상품은 앞에 나가지 않아도 받을 수 있다. 끝난 상품이라면.`,
      ng:`기어가는데 방청석 의자가 접혔다. 탁. 이쪽 손가락이 끼었다.<br><br>손가락을 빼는 데 한참 걸렸다. 그 소리에 바람잡이가 돌아봤다. 웃는 입이 더 길어졌다.`,
      win:{ exp:15, dream:2, item:'꿀 한 줌' }, lose:{ hp:-24, spirit:-18 } }
  ] },

{ at:'A1', t:'무대 옆 — 큐 카드 뭉치',
  x:`무대 감독이 무대 옆에 서 있다. 헤드셋을 끼고 큐 카드 뭉치를 들었다. 얼굴이 없다. 헤드셋만 있다.<br><br>
    카드 맨 앞장에 큰 글씨. 다음 순서 — 오늘의 친구. 그 밑에 이름 칸.<br>
    이름 칸에 이쪽 팀원 이름이 적히고 있다. 펜도 없는데 한 획씩.<br><br>
    순서표는 사람보다 힘이 세다. 사람을 바꾸기보다 순서를 바꾸는 게 쉽다.`,
  o:[
    { l:'① 카드 순서를 바꾸자고 감독에게 흥정한다.', k:'bond', dc:23, wake:1,
      ok:`감독 앞에 섰다. 지금 오늘의 친구가 나가면 방송이 너무 빨리 끝난다고 했다. 시간이 남는다고.<br><br>헤드셋이 이쪽을 향한다. 감독에게 제일 무서운 건 남는 시간이다. 카드 뭉치를 넘긴다. 노래 순서를 앞으로. 체조를 그다음.<br>이름 칸이 맨 뒤 카드로 넘어갔다. 그 카드까지 가려면 아직 멀다. 그 사이에 위층에 닿으면 된다.<br><br>상대가 제일 겁내는 걸 대신 걱정해 주면 상대는 이쪽 말을 듣는다. 값을 깎은 게 아니라 날짜를 미뤘다. 그 방식이 혀에 익었다.`,
      ng:`시간이 남는다고 하자 감독이 카드 한 장을 꺼내 보여 준다. 남는 시간 — 방청객 참여.<br><br>다른 팀원 이름이 거기 적히기 시작한다. 하나가 둘이 됐다.<br>감독을 밀치고 카드를 빼앗으려다 손목이 감독 손에 잡혔다. 겨우 뺐다. 손목에 시곗바늘 자국이 남았다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-22, spirit:-24 } },
    { l:'② 카드 뭉치 옆면으로 다음 장 글씨를 읽는다.', k:'gaze', dc:22,
      ok:`감독 어깨 너머로 뭉치 옆면을 봤다. 카드마다 끝에 시간이 적혀 있다.<br><br>오늘의 친구는 다섯 시 정각. 지금은 아직 아니다. 이름은 다섯 시에 불린다. 그 전에는 불러도 대답할 사람이 없다.<br>팀원 귀에 다섯 시 전에 위층에 닿자고만 일렀다. 이름이 적힌 팀원은 그 뒤로 시계를 자주 본다.`,
      ng:`옆면을 보는데 감독 헤드셋에서 소리가 샌다. 이쪽 숨소리다. 녹음된 것처럼.<br><br>감독이 카드 한 장을 이쪽 가슴에 붙였다. 대기. 떼어 내도 다시 붙어 있다. 세 번 떼고 나서야 안 붙었다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-18, spirit:-22 } }
  ] },

{ at:'A1', t:'분장실 — 웃는 얼굴 그리기',
  x:`분장실 전구 거울 앞에 의자가 다섯. 의자마다 분장 붓이 놓였다.<br><br>
    거울 속에서 손 하나가 붓을 든다. 다섯 개 다 웃는 입을 그릴 거라고 한다. 방송에 나가려면 웃어야 한다고. 웃지 않는 얼굴은 잘린다고.<br>
    잘린다는 게 화면에서인지 다른 데서인지 말하지 않는다.<br><br>
    다섯을 한 번에 하자는 조건은 하나로 줄이는 데서 깎기 시작한다.`,
  o:[
    { l:'① 한 사람만, 이쪽 얼굴에만 그리라고 한다.', k:'bond', dc:22,
      ok:`이쪽만 하자고 했다. 대표로. 대표가 웃으면 팀이 웃는 거라고.<br><br>붓이 이쪽 얼굴에 닿는다. 차고 미끄럽다. 입꼬리에서 귀 쪽으로 길게.<br>거울 속 이쪽이 웃는다. 이쪽은 안 웃는다. 그래도 거울은 됐다고 한다. 의자 넷이 저절로 밀려났다.<br><br>세수를 해도 지워지지 않았다. 다음 층까지. 거울을 볼 때마다 입이 먼저 웃고 있다.`,
      ng:`이쪽만 하자고 했는데 붓이 다섯 개 다 움직인다. 대표 말은 안 받는다.<br><br>팀원들 얼굴에 웃는 입이 하나씩 그려진다. 이쪽 손으로 문질러 지웠다. 손바닥이 빨갛다. 물감이 아니다.<br>지운 자리마다 피부가 쓰렸다.`,
      win:{ exp:18, dream:2, spirit:5 }, lose:{ hp:-24, mind:-20 } },
    { l:'② 전구 거울을 수건으로 덮는다.', k:'hide', dc:23,
      ok:`분장 수건을 거울에 걸었다. 다섯 칸 다.<br><br>거울 속 손이 수건 뒤에서 붓을 내려놓는 소리가 났다. 볼 수 없으면 그릴 수 없다.<br>붓 다섯 자루가 탁자에 가지런히 누웠다. 솔 끝이 젖어 있다. 아직.`,
      ng:`네 번째 수건을 거는데 전구가 하나 터졌다. 유리가 튀었다.<br><br>얼굴을 감쌌다. 손등에 유리 조각이 박혔다. 거울 속 손이 그 틈에 팀원 하나 입가에 한 획을 그었다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-26, spirit:-18 } }
  ] },

{ at:'A1', t:'7층 복도 — 출연료 봉투',
  x:`스튜디오 앞 복도에 탁자가 있다. 흰 봉투 다섯 장. 봉투마다 이쪽 이름과 출연료라는 글씨.<br><br>
    봉투가 두툼하다. 손에 쥐면 따뜻할 것 같다.<br>
    받으면 출연한 게 된다. 안 받으면 탁자 뒤 문이 안 열린다. 문 손잡이에 쪽지가 붙었다. 출연자 외 출입 금지.<br><br>
    협상가는 받는 법만큼 거절하는 법도 값이 있다는 걸 안다. 거절에도 형식이 있다.`,
  o:[
    { l:'① 봉투를 받아 들었다가 사양서를 써서 되돌린다.', k:'bond', dc:23, wake:1,
      ok:`봉투 다섯 장을 받았다. 손에 쥐니 정말 따뜻하다.<br><br>봉투 뒷면에 적었다. 출연은 감사하나 이번 회는 사양합니다. 다음에 다시 연락 주시면. 다섯 장 다 이쪽 이름으로 서명했다.<br>탁자에 반듯하게 돌려놓았다. 문 손잡이 쪽지가 바뀌었다. 관계자 출입.<br><br>받았다가 돌려준 사람은 출연자도 남도 아니다. 관계자다. 그 자리로 들어가는 문이 있다.<br>거절을 빈손으로 하지 않는다. 받아 들고 정중히 돌려준다. 그 순서가 이제 몸에 있다.`,
      ng:`받아 드는데 봉투가 손바닥에 들러붙는다. 따뜻한 게 봉투가 아니었다. 안에 든 것이었다.<br><br>떼어 내자 손바닥 껍질이 같이 벗겨졌다. 봉투 안에서 무엇이 꿈틀했다.<br>탁자에 던지듯 내려놓았다. 문은 끝내 안 열렸다. 다른 길로 돌았다.`,
      win:{ exp:24, dream:3, hp:6 }, lose:{ hp:-30, spirit:-20 } },
    { l:'② 봉투에 손대지 않고 탁자 앞에 서서 기다린다.', k:'steady', dc:22,
      ok:`손대지 않았다. 다섯이 탁자 앞에 나란히 섰다.<br><br>오래 기다렸다. 봉투 하나가 스스로 미끄러져 바닥에 떨어졌다. 그다음 하나. 다섯 장이 다 떨어지자 문이 조금 열렸다. 출연자가 없으니 출연자 외 금지도 없다.<br>지나가며 봉투를 밟지 않으려 애썼다.`,
      ng:`기다리는 사이 복도 끝 스피커에서 이름이 하나 불렸다. 출연자 대기.<br><br>불린 팀원이 걸음을 뗐다. 붙잡았다. 셋이 같이 붙들었다. 한참 버텼다. 팀원 손톱이 탁자에 긁힌 자국이 길다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-20, spirit:-22 } }
  ] },

{ at:'A2', t:'사감실 — 외박 신청서',
  x:`사감실 문 옆에 서류함이 박혀 있다. 맨 위 칸 종이가 젖지 않았다. 외박 신청서.<br><br>
    사유 칸, 기간 칸, 보호자 확인 칸. 맨 밑에 사감 확인 칸. 비었다.<br>
    벽시계가 여덟 시 사십 분을 가리킨다. 밤 아홉 시 점호까지 이십 분.<br><br>
    협상가는 규칙이 센 곳에서는 규칙 안의 구멍을 찾는다. 이 학교에 외출은 없다. 그런데 신청서는 있다.`,
  o:[
    { l:'① 사유를 정해 다섯 장을 써서 서류함에 넣는다.', k:'bond', dc:23, wake:1,
      ok:`사유 칸에 적었다. 가정 사정. 기간은 오늘 밤. 보호자 확인 칸에는 이쪽 이름. 다섯 장.<br><br>서류함에 넣었다. 물 밑에서 종이 넘기는 소리가 난다. 아주 오래. 그리고 탁. 도장 소리.<br>아홉 시에 점호가 지나갔다. 사감 발소리가 이쪽 문 앞에서 멈추고, 다음 문으로 넘어갔다. 외박생은 부르지 않는다.<br><br>규칙과 싸우지 않고 규칙에 서류를 냈다. 서류는 저쪽 말로 하는 흥정이다. 상대 말로 쓰면 상대가 읽는다. 그 문법이 손에 잡혔다.`,
      ng:`사유 칸에 쓰는데 글씨가 번진다. 종이가 아래부터 젖어 온다.<br><br>다 쓰기도 전에 서류함이 신청서를 빨아들였다. 반만 쓴 것을. 물 밑에서 빨간 도장 소리가 났다. 반려.<br>점호 때 이쪽 이름이 불렸다. 두 번. 대답하지 않느라 혀를 깨물었다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-22, spirit:-26 } },
    { l:'② 신청서를 두고 점호 동안 침대 밑에 숨는다.', k:'hide', dc:22,
      ok:`가장 가까운 호실 침대 밑에 다섯이 기어들었다. 물이 귀까지 찼다. 코만 내밀었다.<br><br>아홉 시. 사감 발소리. 호실 문이 열린다. 침대 수만큼 이름이 불린다. 이쪽 이름은 없다. 이 방 아이들 이름이다.<br>대답 소리가 났다. 이쪽 머리 위 매트리스에서. 다섯 개.`,
      ng:`기어드는데 맨 끝 팀원 발이 침대 밖으로 나왔다.<br><br>사감 발소리가 그 발 앞에서 멈췄다. 오래. 그리고 발목을 한 번 쓰다듬고 지나갔다.<br>그 팀원 발목에 출석 도장이 찍혀 있다. 지워지지 않는다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, mind:-20 } }
  ] },

{ at:'A2', t:'매점 — 남은 외상',
  x:`물에 잠긴 매점 계산대에 장부가 떠 있다. 외상 장부. 펼쳐진 쪽에 이름 하나.<br><br>
    이 학교 아이 이름이다. 외상이 남았다. 빵 둘, 우유 하나. 날짜는 잠기던 날.<br>
    계산대 밑에서 작은 손이 올라와 장부 그 줄을 짚고 있다. 손톱이 하얗다.<br><br>
    갚지 못한 빚은 사람을 붙잡는다. 이 손은 장부에서 떨어지지 못한다.`,
  o:[
    { l:'① 이쪽 먹을 것으로 그 아이의 외상을 갚는다.', k:'bond', dc:23,
      doom:{ title:'대신 갚은 빚', what:'갚은 사람이 계산대 밑으로 끌려 들어갑니다', dc:18, sec:50,
        text:`말린 고기를 계산대에 올렸다. 빵 둘, 우유 하나 값이라고. 이 아이 몫이라고.<br><br>작은 손이 장부에서 떨어진다. 이쪽 손목으로 옮겨 온다. 고맙다는 듯 꽉.<br>갚아 준 사람은 친구다. 친구는 같이 있어야 한다. 손이 계산대 밑으로 당긴다. 물이 턱까지 오른다.`,
        dieText:`장부의 그 줄에 붉은 줄이 그어졌다. 완납.<br><br>바로 밑 줄에 새 이름이 적혀 있다. 이쪽 이름이다. 외상 없음. 대신 비고 칸에 한 단어. 짝.<br>계산대 밑에서 가끔 웃음소리가 난다. 둘이다.` },
      ok:`말린 고기를 계산대에 올렸다. 빵 둘, 우유 하나 값이라고. 그리고 손을 바로 뺐다. 영수증을 달라고 했다.<br><br>작은 손이 멈칫한다. 장부 옆에서 젖은 영수증 한 장이 떠올랐다. 완납.<br>손이 장부를 놓았다. 물 밑으로 내려간다. 천천히, 처음으로 가볍게.<br><br>빚은 갚을 때보다 갚았다는 증서를 받을 때 끝난다. 영수증을 품에 넣었다. 아직 따뜻하다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 장부를 덮고 매점 진열장을 뒤진다.', k:'luck', dc:22,
      ok:`장부를 덮었다. 작은 손이 덮인 표지 위에 얹힌다. 거기서 기다린다.<br><br>진열장 위 칸이 물 밖이다. 봉지 하나가 젖지 않았다. 소금 덩이다. 반찬용. 오래돼서 굳었다.<br>챙겨 나오는데 등 뒤에서 장부가 다시 펼쳐지는 소리가 났다.`,
      ng:`덮는 순간 작은 손이 이쪽 손등을 할퀴었다. 덮지 말라고.<br><br>손등에 줄 셋. 물이 들어가 쓰리다. 진열장은 텅 비어 있었다.`,
      win:{ exp:15, dream:2, item:'소금 덩이' }, lose:{ hp:-24, spirit:-20 } }
  ] },

{ at:'A2', t:'3학년 교실 — 짝이 없는 자리',
  x:`교실 물이 허리까지 찼다. 책상은 다 둘씩 붙었다. 한 자리만 짝이 비었다.<br><br>
    빈 자리 옆에 아이 하나가 앉아 있다. 물에 젖은 교복. 고개를 숙였다. 빈 자리를 손바닥으로 계속 쓸어 준다.<br>
    짝을 기다리는 것이다. 이쪽 팀원 하나가 그 옆을 지날 때 아이 손이 팀원 옷자락을 잡았다.<br><br>
    사람을 내주지 않고 자리를 채우는 법이 있을 것이다.`,
  o:[
    { l:'① 이쪽 물건 하나를 짝으로 앉혀 준다.', k:'bond', dc:23, wake:1,
      ok:`배낭에서 등불 덮개를 꺼냈다. 빈 의자에 앉혔다. 아이 쪽으로 돌려서.<br><br>아이가 고개를 든다. 덮개를 본다. 오래. 옷자락을 놓았다. 덮개를 손바닥으로 쓸어 준다. 같은 손길로.<br>짝은 사람이 아니어도 된다. 옆자리에 누가 있다는 것만 있으면 된다. 아이가 원한 건 사람이 아니라 옆자리였다.<br><br>원하는 걸 이름이 아니라 모양으로 읽는다. 그 눈이 생겼다. 무엇을 달라는지보다 무엇이 비었는지를 먼저 본다.`,
      ng:`덮개를 앉혔는데 아이가 그걸 물에 밀어 떨어뜨린다. 아니라고.<br><br>옷자락을 더 꽉 쥔다. 팀원이 끌려가 의자에 앉혀질 뻔했다. 셋이 붙어 떼어 냈다. 옷자락이 찢어졌다. 아이 손에 남았다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-20, spirit:-28 } },
    { l:'② 옷자락을 잘라 내고 책상 사이를 피해 지나간다.', k:'evade', dc:22,
      ok:`칼로 옷자락을 잘랐다. 아이 손에 천 조각만 남았다.<br><br>책상 줄 사이를 몸을 비틀어 지나갔다. 의자마다 물 밑에서 무엇이 발목 높이로 손을 내민다. 하나도 안 닿았다.<br>문을 나서며 돌아봤다. 아이가 천 조각을 빈 자리에 앉혀 놓았다.`,
      ng:`자르는데 칼이 물속에서 미끄러졌다. 팀원 손등을 베었다.<br><br>피 냄새에 책상 밑이 일제히 움직인다. 허둥지둥 빠져나왔다. 발목에 손자국이 셋.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-26, mind:-14 } },
    { l:'③ 그 아이가 정말 기다리는 게 누구인지 본다.', k:'gaze', dc:22,
      ok:`책상 위를 봤다. 칼로 새긴 이름 두 개. 하나는 아이 것. 하나는 긁어서 지웠다.<br><br>지운 쪽이 먼저 나간 것이다. 잠기던 날. 혼자.<br>아이에게 말했다. 그 애는 나갔다고. 기다리지 말라고. 아이가 오래 고개를 숙였다. 손을 무릎 위에 올렸다. 다시는 옷자락을 잡지 않았다.`,
      ng:`새긴 이름을 읽으려고 몸을 숙였다. 지운 이름이 이쪽 이름처럼 보인다. 점점.<br><br>아이가 이쪽을 본다. 반가운 얼굴이다. 뒷걸음질 쳤다. 아이가 울기 시작했다. 물이 조금 불었다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-22 } }
  ] },

{ at:'A2', t:'나선 계단 — 불리는 이름',
  x:`아침 일곱 시. 물 밑에서 점호가 올라온다. 이름이 하나씩.<br><br>
    이 학교 아이들 이름 사이에 이쪽 팀원 이름이 끼었다. 한 번. 쉬고. 또 한 번.<br>
    팀원 입이 열린다. 대답하려는 게 아니라 숨을 쉬려는 것이다. 그래도 소리가 나오면 대답이 된다.<br><br>
    대답하지 않는 것 말고 다른 대답이 있을 것이다. 출석과 결석 사이에 말이 하나 더 있다.`,
  o:[
    { l:'① 팀원 대신 조퇴라고 말해 준다.', k:'bond', dc:23,
      doom:{ title:'대신한 대답', what:'대답한 사람이 물속 계단으로 끌려 내려갑니다', dc:18, sec:50,
        text:`팀원 입을 손으로 막고 이쪽이 말했다. 조퇴입니다.<br><br>점호가 멈춘다. 물 밑이 조용하다. 그리고 다른 목소리. 사감이다.<br><span style="color:#9fb4c8;">"조퇴는 본인이 와서 말해야지. 대신 말한 학생, 교무실로."</span><br><br>이쪽 발목을 물이 쥔다. 손 모양으로. 계단 아래로 당긴다. 교무실은 아래층이다.`,
        dieText:`점호는 끝까지 이어졌다. 그 팀원 이름은 다시 불리지 않았다. 조퇴 처리.<br><br>대신 맨 끝에 이름 하나가 새로 불렸다. 이쪽 이름. 사감실 앞으로.<br>팀원들이 대답하지 않았다. 물 밑에서 누가 대신 대답했다. 이쪽 목소리였다. 예.` },
      ok:`팀원 입을 손으로 막고 이쪽이 말했다. 조퇴입니다. 보호자 연락받았습니다. 서류는 사감실에.<br><br>말을 끝까지 다 붙였다. 사유, 확인, 서류 위치. 규칙이 물어볼 걸 먼저 다 답했다.<br>물 밑이 오래 조용했다. 그리고 다음 이름으로 넘어갔다. 그 팀원 이름은 다시 불리지 않았다.<br><br>팀원이 이쪽 손을 떼고 숨을 몰아쉰다. 이쪽 혀가 얼어 있다. 다시는 대신 말하지 않기로 했다.`,
      win:{ exp:22, dream:3 } },
    { l:'② 팀원 입을 막고 숨은 이쪽 손바닥으로 쉬게 한다.', k:'steady', dc:22,
      ok:`손바닥을 팀원 입에 붙였다. 손가락 사이를 조금 벌려 숨만 지나가게.<br><br>이름이 세 번 불렸다. 세 번 다 손바닥이 받아 냈다. 소리는 안 나가고 숨만 나간다.<br>점호가 다음 층으로 내려갔다. 손바닥이 팀원 숨으로 젖어 있었다. 따뜻했다. 살아 있는 숨이다.`,
      ng:`손가락을 벌리는 게 넓었다. 숨에 소리가 실렸다. 아주 작게. 응.<br><br>물 밑에서 출석부 넘기는 소리. 팀원 무릎이 꺾인다. 다 같이 붙들어 계단 위로 끌어올렸다. 팀원 손끝이 파랗다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, mind:-20 } }
  ] },

{ at:'A2', t:'강당 — 남아 줄 당번',
  x:`강당 무대 옆에 사감이 서 있다. 젖은 출석부를 가슴에 안았다. 얼굴은 물그림자다.<br><br>
    하교 종이 무대 위에 매달려 있다. 사감이 말한다. 종은 칠 수 있다고. 대신 교실 정리할 당번 하나는 남아야 한다고.<br>
    규칙이다. 다들 나가면 누군가 문을 잠가야 하니까.<br><br>
    협상가는 사람을 내놓으라는 조건을 일로 바꿔 놓을 수 있는지 본다. 당번은 사람이 아니라 할 일이다.`,
  o:[
    { l:'① 당번 일을 지금 다 해 놓을 테니 남는 사람은 없게 하자고 한다.', k:'bond', dc:24, wake:1,
      ok:`당번이 할 일이 뭐냐고 물었다. 사감이 손가락을 꼽는다. 창문 잠그기, 의자 올리기, 칠판 지우기, 출석부 덮기.<br><br>지금 다 하겠다고 했다. 다섯이 흩어졌다. 물속에서 의자를 올리고 칠판을 지웠다. 마지막으로 이쪽이 사감 앞에 섰다. 출석부를 덮어 드려도 되겠느냐고.<br>사감이 오래 망설이다 출석부를 내밀었다. 덮었다. 표지에서 물이 흘러내린다. 하교 종이 저절로 한 번 흔들렸다.<br><br>사람을 달라는 말 밑에는 대개 일이 있다. 일을 먼저 해 주면 사람을 안 내줘도 된다. 그 순서가 이제 흥정의 첫 수다.`,
      ng:`다 해 놓겠다고 하자 사감이 고개를 젓는다. 문 잠그는 일은 나가는 사람이 못 한다고.<br><br>출석부가 펼쳐진다. 이쪽 이름 옆에 당번 표시가 찍혔다. 팀원들이 이쪽을 끌어 무대 위로 올렸다. 종줄 앞까지. 다리가 무대 바닥에 붙어 한참 안 떨어졌다.`,
      win:{ exp:25, dream:4 }, lose:{ mind:-22, spirit:-30 } },
    { l:'② 흥정하지 않고 종줄부터 붙잡는다.', k:'break', dc:23,
      ok:`대답 대신 무대로 뛰었다. 종줄을 두 손으로 쥐었다.<br><br>사감이 돌아본다. 출석부가 펼쳐진다. 그 전에 당겼다. 종이 운다. 물이 떨린다.<br>사감 손에서 출석부가 떨어졌다. 아무도 남지 않았다. 대신 무대 아래 물이 한참 동안 이쪽 발목 높이에서 출렁였다.`,
      ng:`뛰는데 무대 계단이 물속에서 하나 빠졌다. 정강이를 찧었다.<br><br>사감이 출석부를 펼쳤다. 이쪽 이름 옆에 지각 표시. 종줄까지 기어가는 동안 물이 자꾸 이쪽을 뒤로 민다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, spirit:-18 } }
  ] },

]);

// ------------------------------------------
// 결속술사 · 마력
// ------------------------------------------
kJob('binder', 'A', [

{ at:'A', t:'손목 — 여섯째 가닥',
  x:`손목에 실 다섯 가닥이 모여 있다. 마력으로 꼰 실이다. 팀원 다섯의 손목으로 이어진다.<br><br>
    복도 중간쯤에서 손목이 한 번 당겨졌다. 세어 보니 여섯 가닥이다.<br>
    여섯째는 이쪽이 꼰 게 아니다. 더 가늘고 차다. 어둠 쪽으로 뻗어 있다.<br><br>
    여섯째가 당긴다. 한 번, 쉬고, 한 번. 팀원들이 쓰는 박자다. 결속술사가 가르친 박자.`,
  o:[
    { l:'① 마력을 실어 여섯째 가닥만 끊는다.', k:'bond', dc:22, cost:{ mana:28 },
      ok:`손톱에 마력을 모았다. 다섯 가닥은 그대로 두고 여섯째만 골라 눌렀다.<br><br>실이 끊기는 소리가 났다. 줄이 아니라 숨이 끊기는 소리였다.<br>끊긴 끝이 어둠 속으로 빨려 들어갔다. 다섯 가닥이 일제히 떨렸다. 팀원들이 동시에 어깨를 움츠렸다. 뭔가 지나갔다고.<br><br>손목이 가볍다. 다섯이다. 다섯이어야 한다.`,
      ng:`손톱이 여섯째 대신 셋째를 눌렀다. 비슷하게 차가웠다.<br><br>셋째 팀원이 휘청였다. 이어진 게 끊기자 발밑을 잃은 것처럼. 다시 꼬는 데 마력이 다 갔다.<br>여섯째는 그대로다. 아까보다 조금 더 굵다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-18, spirit:-22 } },
    { l:'② 여섯째 가닥을 감으며 따라간다.', k:'sense', dc:23,
      doom:{ title:'여섯째 가닥', what:'여섯째 실에 감겨 어둠 속으로 끌려갑니다', dc:18, sec:50,
        text:`실을 손가락에 감으며 따라갔다. 복도 끝, 모퉁이, 계단.<br><br>감을수록 실이 굵어진다. 그리고 따뜻해진다. 사람 손목 굵기가 됐을 때 멈췄다.<br>이쪽이 감은 게 아니었다. 저쪽이 감고 있었다. 손가락이 실과 함께 어둠 속으로 들어간다.<br><br>뒤에서 다섯 가닥이 팽팽하게 당긴다. 팀원들이 붙들고 있다.`,
        dieText:`다섯 가닥이 하나씩 느슨해졌다. 끊긴 게 아니다. 저쪽 끝이 놓아 버린 것이다.<br><br>팀원들 손목에 실이 남았다. 끝이 어둠으로 이어진다. 가끔 당겨진다. 한 번, 쉬고, 한 번.<br>그 박자를 가르친 사람은 이제 저쪽 끝에 있다.` },
      ok:`실을 손가락에 감으며 따라갔다. 모퉁이 하나에서 멈췄다. 실이 따뜻해지기 시작한 자리다.<br><br>그 자리에 표시를 하고 돌아섰다. 따라가지 않는 쪽을 골랐다.<br>그 모퉁이는 지도에서 지웠다. 팀원들에게도 일렀다. 거기서 손목이 당겨지면 그건 이쪽이 아니라고.`,
      win:{ exp:20, dream:3 } },
    { l:'③ 여섯째를 가만히 쥐고 당기는 무게를 잰다.', k:'gaze', dc:22, wake:1,
      ok:`쥐기만 했다. 당기지도 끊지도 않고.<br><br>무게가 손바닥에 실린다. 사람 하나 무게가 아니다. 사람 여럿이 나눠서 당기는 무게다. 손가락 마디마다 다른 손이 걸려 있다.<br>무게를 다 잰 뒤에 놓았다. 여섯째는 스스로 풀려 물러났다. 재는 손 앞에서는 당기지 못한다.<br><br>실은 이어 주는 것인 줄만 알았다. 쥐고 있으면 저쪽이 무엇인지 알려 준다. 손바닥이 눈이 됐다. 그 뒤로 실을 쥘 때마다 무게를 먼저 읽는다.`,
      ng:`쥐었는데 무게가 갑자기 늘었다. 손바닥 살이 실에 베였다.<br><br>놓았다. 늦었다. 손바닥 가운데 붉은 줄이 깊다. 거기서 한참 피가 났다. 실이 마신 것 같았다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-24, spirit:-20 } }
  ] },

{ at:'A', t:'어둠 속 — 박자가 다른 가닥',
  x:`등불이 꺼졌다. 다섯이 어둠 속에 섰다. 실이 있으니 흩어지지는 않는다.<br><br>
    둘째 가닥이 당긴다. 둘째 팀원 박자다. 빠르게 두 번. 그 사람 버릇이다.<br>
    그런데 둘째 팀원은 지금 이쪽 왼쪽에 붙어 서서 이쪽 팔을 쥐고 있다. 손이 떨린다. 아무것도 당기지 않았다.<br><br>
    결속술사는 실이 거짓말을 하는 걸 처음 느꼈다.`,
  o:[
    { l:'① 실을 놓지 않고 팔을 쥔 사람 얼굴부터 더듬는다.', k:'gaze', dc:23,
      ok:`팔을 쥔 손을 따라 올라가 얼굴을 더듬었다. 콧날, 눈썹, 흉터. 둘째 팀원 맞다.<br><br>그럼 실 쪽이 틀렸다. 실을 쥔 채로 끝을 당겨 봤다. 저쪽 끝에 무게가 있다. 사람 손목만 한.<br>실 끝을 맨 무엇이 둘째 행세를 했다. 실에 버릇까지 실어서. 둘째 가닥을 끊고 새로 꼬았다. 이번엔 둘째 손목을 직접 쥐고.`,
      ng:`얼굴을 더듬는데 둘째 팀원이 몸을 뺐다. 놀란 것이다.<br><br>그 사이 실이 확 당겨졌다. 이쪽 손목이 꺾였다. 둘째 팀원 손을 놓쳤다.<br>다시 찾는 데 한참 걸렸다. 다섯이 모였을 때 둘째 손목의 실이 없었다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 마력으로 실마다 이쪽만 아는 매듭을 하나씩 더 맨다.', k:'bond', dc:22, cost:{ mana:30 }, wake:1,
      ok:`실 다섯 가닥을 하나씩 손끝으로 훑었다. 가닥마다 매듭을 하나씩 더 맸다. 마력으로. 이쪽만 아는 모양.<br><br>둘째 가닥을 훑을 때 손끝이 걸렸다. 매듭이 안 들어간다. 이 가닥은 이쪽 실이 아니다.<br>끊었다. 진짜 둘째를 찾아 다시 이었다. 이번 매듭은 이쪽 손끝만 안다.<br><br>실에 표시를 남기는 법. 이쪽이 꼰 것과 남이 흉내 낸 것을 손끝으로 가른다. 실이 이쪽 글씨가 됐다.`,
      ng:`매듭을 매는데 마력이 손끝에서 흩어진다. 어둠이 마력을 먹는다.<br><br>셋째 가닥에서 마력이 다 떨어졌다. 둘째는 손도 못 댔다. 둘째 가닥이 다시 당긴다. 빠르게 두 번.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-22, spirit:-20 } }
  ] },

{ at:'A', t:'긴 계단 — 내려가는 무게',
  x:`맨 뒤 팀원이 계단에서 사라졌다. 소리도 없이.<br><br>
    다섯째 가닥이 팽팽하다. 아래로. 계단 아래로 무엇이 끌고 간다. 일정한 속도로.<br>
    실 끝에서 팀원이 버둥거리는 게 느껴진다. 아직 산 무게다.<br><br>
    결속술사의 실은 끊어지지 않도록 꼬았다. 끊어지지 않는 실은 이쪽도 같이 끌고 간다.`,
  o:[
    { l:'① 마력을 다 부어 실을 굳히고 버틴다.', k:'bond', dc:24, cost:{ mana:32 },
      doom:{ title:'굳힌 실', what:'굳힌 실째 계단 아래로 함께 끌려갑니다', dc:18, sec:50,
        text:`마력을 실에 부었다. 실이 빛나며 쇠처럼 굳는다. 손목이 아니라 팔뚝째로 받쳤다.<br><br>아래에서 당기는 힘이 멈칫한다. 그리고 다시 당긴다. 이번엔 둘로. 하나는 팀원을, 하나는 실을.<br>굳은 실은 휘지 않는다. 그래서 이쪽이 휘었다. 발이 계단을 미끄러진다. 한 칸, 또 한 칸.<br><br>남은 팀원들이 이쪽 허리를 붙든다.`,
        dieText:`실은 끝까지 끊어지지 않았다. 그렇게 꼬았으니까.<br><br>팀원들이 계단 아래를 비췄을 때 실 한 가닥이 계단을 따라 길게 내려가 있었다. 빛나는 채로. 끝이 안 보인다.<br>그 실은 그 뒤로도 가끔 당겨진다. 남은 팀원들 손목이 아니라 계단 난간이.` },
      ok:`마력을 실에 부었다. 실이 쇠처럼 굳는다. 팔뚝째로 받쳤다.<br><br>당기는 힘이 멈칫한다. 그 틈에 남은 팀원들이 실을 같이 쥐었다. 넷이 한 가닥을 당긴다.<br>계단 아래에서 맨 뒤 팀원이 끌려 올라왔다. 발목에 손자국이 진하다. 다섯 개가 아니라 여덟 개다.<br><br>굳힌 실이 손목을 파고들었다. 실 자국이 팔찌처럼 남았다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 실을 난간 기둥에 두 번 감아 무게를 기둥에 맡긴다.', k:'fix', dc:22,
      ok:`실을 난간 기둥에 감았다. 두 번. 매듭을 지었다.<br><br>기둥이 삐걱인다. 무게가 기둥으로 갔다. 이쪽 손이 비었다. 빈손으로 계단을 뛰어 내려갔다.<br>팀원이 셋째 층계참에 끌려가다 멈춰 있었다. 실이 기둥에 걸려서. 발목을 쥔 것을 걷어찼다. 차가운 것이 물러났다.`,
      ng:`감는 사이 무게가 확 늘었다. 기둥이 뽑혔다.<br><br>기둥째 실이 계단을 굴러 내려간다. 따라 뛰어 내려가 기둥을 붙잡았다. 팀원은 겨우 건졌다. 갈비뼈 하나가 기둥에 눌렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-34, mind:-14 } }
  ] },

{ at:'A', t:'닫히지 않는 문',
  x:`쉬려고 들어온 방의 문이 닫히지 않는다. 닫으면 다시 열린다. 손바닥 하나만큼.<br><br>
    그 틈으로 바람이 들어온다. 바람에 냄새가 있다. 젖은 털 냄새.<br>
    밤새 문을 지킬 수는 없다. 다섯 다 잠은 자야 한다.<br><br>
    결속술사는 사람만 묶지 않는다. 묶을 수 있는 것은 다 묶는다.`,
  o:[
    { l:'① 문고리와 이쪽 손목을 실로 묶고 잔다.', k:'bond', dc:23, wake:1,
      ok:`문고리에 실을 감았다. 다른 끝을 이쪽 손목에. 그리고 문을 닫았다.<br><br>문이 열리려 할 때마다 손목이 당겨진다. 잠결에 당겨 닫았다. 밤새 열두 번.<br>새벽에는 열리려는 힘이 약해졌다. 아침에 보니 문 바깥 바닥에 젖은 털이 한 움큼 빠져 있다. 문틈에 끼었던 자리다.<br><br>잠든 채로도 실은 깨어 있다. 손목이 문지기를 섰다. 실을 사람 대신 물건에 걸고 이쪽 몸을 그 끝에 두는 법. 그게 쉬는 법이 됐다.`,
      ng:`묶고 잤는데 손목이 당겨지는 게 꿈에 섞였다. 꿈에서 누가 손을 잡고 끌었다.<br><br>따라갔다. 깨 보니 문 앞에 서 있다. 문이 활짝 열려 있다. 이쪽 손으로 연 것이다.<br>팀원들이 이쪽을 끌어당겨 앉혔다. 아무도 다시 못 잤다.`,
      win:{ exp:24, dream:3, hp:6 }, lose:{ mind:-22, spirit:-26 } },
    { l:'② 다섯이 문을 등지고 한 사람씩 깨어 지킨다.', k:'steady', dc:22,
      ok:`돌아가며 지켰다. 한 사람씩 문에 등을 대고.<br><br>등 뒤에서 문이 밀린다. 한참 밀리다 멈춘다. 다음 사람으로 바뀌면 다시 민다. 사람이 바뀌는 걸 안다.<br>아침이 왔다. 다섯 다 조금씩 잤다. 문 바깥에 무엇이 앉아 있던 자국이 있다.`,
      ng:`셋째 순서가 졸았다. 문이 소리 없이 열렸다.<br><br>털 냄새가 방 안 가득. 넷째가 비명에 깼다. 무엇이 다섯째 팀원 머리맡에 앉아 그 얼굴을 들여다보고 있었다. 내쫓는 데 다 같이 할퀴었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, mind:-18 } }
  ] },

{ at:'A', t:'쉬는 자리 — 잠든 발목의 매듭',
  x:`새벽에 눈을 떴다. 손목 실이 이상하다. 넷째 가닥에 다른 실이 엉켜 있다.<br><br>
    넷째 팀원 발목에 실이 묶였다. 이쪽 실이 아니다. 젖었고 굵다. 머리카락을 꼰 것 같다.<br>
    매듭은 서툴다. 아이가 신발 끈 매듯이. 그 끝이 바닥 틈으로 들어간다.<br><br>
    넷째 팀원은 깊이 잔다. 깨우면 놀라 발을 뺄 것이다.`,
  o:[
    { l:'① 매듭을 읽어 깨우지 않고 푼다.', k:'bond', dc:23, wake:1,
      ok:`매듭을 손끝으로 읽었다. 두 번 감고 고리 하나. 당기면 조이는 매듭이다.<br><br>당기지 않고 거꾸로 밀었다. 고리가 헐거워진다. 한 바퀴씩 되감아 풀었다. 바닥 틈 쪽 실이 기다린다는 듯 느슨하다.<br>다 풀고 매듭을 이쪽 손에 쥐었다. 바닥 틈에서 실이 당겨졌다. 빈 고리만 따라 들어갔다.<br><br>남이 맨 매듭을 손끝으로 읽고 거꾸로 푸는 법. 매듭에는 맨 사람의 버릇이 남는다. 그 버릇이 읽히기 시작했다.`,
      ng:`푸는 도중에 넷째 팀원이 몸을 뒤척였다. 발목이 당겨졌다.<br><br>매듭이 조였다. 바닥 틈 쪽으로 다리가 미끄러진다. 팀원이 깨서 비명을 질렀다. 다 같이 붙들고 칼로 잘랐다. 발목에 검은 줄이 감겨 남았다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-22, spirit:-26 } },
    { l:'② 칼로 단번에 끊는다.', k:'break', dc:22,
      ok:`칼을 실 밑에 넣어 단번에 그었다.<br><br>끊긴 쪽이 바닥 틈으로 휙 빨려 들어갔다. 틈 안에서 작게 우는 소리.<br>넷째 팀원은 끝내 안 깼다. 아침에 발목이 시리다고만 했다.`,
      ng:`칼이 실에 걸렸다. 질기다. 머리카락이 칼날을 감는다.<br><br>두 번 세 번 그었다. 그 사이 팀원이 깼다. 발을 빼려다 바닥 틈 쪽으로 끌려갔다. 팔꿈치까지 들어갔다 겨우 나왔다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-28, mind:-16 } },
    { l:'③ 실 끝이 들어간 바닥 틈을 들여다본다.', k:'sense', dc:22,
      ok:`등불을 낮춰 바닥 틈을 비췄다.<br><br>틈 아래 공간이 있다. 거기 실 끝이 수십 가닥 늘어져 있다. 다 같은 매듭으로 끝난다. 신발 끈 매듭.<br>위에서 묶인 발목이 그만큼이었다. 틈을 돌로 막고 그 위에 팀원 신발을 올려놓았다. 무게라도 얹어 두면 덜 당긴다.`,
      ng:`들여다보는데 틈 안에서 눈이 마주쳤다. 작은 눈이다.<br><br>그 눈이 웃는다. 이쪽 손목 실이 다섯 가닥 다 한 번에 당겨졌다. 팀원 다섯이 동시에 잠에서 깨 비명을 질렀다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-22 } }
  ] },

{ at:'A', t:'복도 — 매달린 매듭',
  x:`복도 천장에서 실이 늘어져 있다. 수십 가닥. 가닥마다 끝에 매듭이 하나씩 달렸다.<br><br>
    매듭은 사람 모양으로 묶였다. 머리, 팔, 다리. 손가락만 하다.<br>
    지나가는데 매듭 다섯이 새로 생겨 있다. 아까는 없었다. 아직 덜 묶였다. 다리 쪽이 풀려 있다.<br><br>
    매듭을 보면 누가 묶었는지 안다. 이건 사람 손이 아니다. 너무 촘촘하다.`,
  o:[
    { l:'① 마력을 흘려 새 매듭 다섯을 거꾸로 푼다.', k:'bond', dc:23, cost:{ mana:26 },
      ok:`손가락 끝에 마력을 모아 새 매듭에 댔다. 묶인 순서를 거꾸로 따라갔다. 팔, 머리.<br><br>매듭 하나가 풀릴 때마다 팀원 하나가 숨을 크게 쉰다. 자기도 모르게. 가슴을 누르던 게 풀린 것이다.<br>다섯을 다 풀었다. 실 끝이 천장으로 말려 올라갔다. 복도 끝 어둠에서 손가락 꺾는 소리가 났다. 다시 묶으려는 소리.<br><br>서둘러 지나갔다. 다시 묶이기 전에.`,
      ng:`셋째 매듭을 풀다 마력이 끊겼다. 매듭이 거꾸로 조였다.<br><br>셋째 팀원이 무릎을 꿇었다. 다리가 안 움직인다고. 매듭 다리 쪽이 다 묶여 버렸다.<br>업고 지나갔다. 다음 층에서야 다리가 풀렸다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-22, spirit:-24 } },
    { l:'② 매듭을 건드리지 않고 고개를 숙여 빨리 지나간다.', k:'hide', dc:22,
      ok:`건드리지 않았다. 매듭 밑을 숙여 걸었다. 팀원들도 따라 숙였다.<br><br>덜 묶인 것은 아직 이쪽을 다 모른다. 다리가 묶이기 전에 복도를 벗어나면 된다.<br>끝에서 돌아보니 다섯 매듭이 바람도 없이 흔들린다. 다리 쪽이 여전히 풀린 채로.`,
      ng:`숙이는데 맨 앞 매듭이 이쪽 머리카락에 걸렸다.<br><br>떼어 내는 사이 매듭 다리가 한 바퀴 감겼다. 다섯 팀원이 동시에 발을 헛디뎠다. 다 같이 넘어졌다. 무릎이 다 깨졌다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, mind:-16 } }
  ] },

{ at:'A', t:'빈 방 — 가슴에 감긴 실',
  x:`빈 방에 들어서자 가슴이 당겨졌다. 손목이 아니라 가슴뼈 한가운데.<br><br>
    내려다보니 실 한 가닥이 가슴에 붙어 있다. 이쪽이 맨 적 없다. 끝이 방 구석 어둠으로 간다.<br>
    거기서 누가 부른다. 이쪽 이름은 아니다. 어릴 때 부르던 이름이다. 아무도 모르는 이름.<br><br>
    실이 천천히 감긴다. 한 걸음, 또 한 걸음. 이쪽 발이 따라간다.`,
  o:[
    { l:'① 손목의 다섯 가닥에 가슴 실을 엮어 무게를 나눈다.', k:'bond', dc:23, wake:1,
      ok:`가슴 실을 손으로 쥐었다. 손목에 모인 다섯 가닥을 거기에 엮었다. 한 올씩 꼬아서.<br><br>당기는 힘이 여섯으로 갈린다. 이쪽 혼자 끌려가던 무게가 다섯 팀원에게 나뉘었다. 팀원들이 영문도 모르고 버틴다.<br>여섯이 버티니 구석의 것이 못 감는다. 부르는 소리가 작아지다 멎었다. 가슴 실이 툭 떨어졌다.<br><br>혼자 받는 당김을 여럿에게 나눠 지게 하는 법. 실은 이어 주기만 하는 게 아니다. 무게를 나르는 길이기도 하다. 손이 그걸 기억했다.`,
      ng:`엮는 사이 이름이 다시 불렸다. 손이 멈췄다. 대답하고 싶다.<br><br>팀원들이 이쪽 어깨를 흔들었다. 엮은 실이 반쯤 풀렸다. 다섯 가닥 중 둘이 가슴 실을 타고 구석으로 당겨진다. 그 둘이 넘어졌다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-22, spirit:-28 } },
    { l:'② 아무에게도 말하지 않고 혼자 실을 쥐고 버틴다.', k:'steady', dc:23,
      doom:{ title:'아무도 모르는 이름', what:'가슴의 실에 감겨 방 구석으로 끌려갑니다', dc:18, sec:50,
        text:`혼자 버텼다. 이건 이쪽 이름이니까. 이쪽 일이다.<br><br>실이 감긴다. 발뒤꿈치가 바닥을 긁는다. 이름이 다시 불린다. 이번엔 어릴 때 그 목소리 그대로.<br>팀원들이 뒤에서 무슨 일이냐고 묻는다. 대답을 하려고 입을 열었다. 나온 건 대답이 아니라 그 이름이었다.<br><br>구석 어둠이 반가워한다. 감기는 속도가 빨라진다.`,
        dieText:`팀원들이 등불을 들었을 때 구석은 벽이었다.<br><br>벽에 실 한 가닥이 박혀 있다. 끝이 벽 속으로 들어간다. 손으로 당기자 따뜻했다.<br>그 방을 지나는 사람은 가끔 이름을 듣는다. 자기 것 말고. 결속술사가 어릴 때 듣던 이름을.` },
      ok:`혼자 버텼다. 실을 쥔 손에 피가 맺힐 때까지.<br><br>이름이 불린다. 대답하지 않았다. 입술을 깨물었다. 구석 어둠이 오래 기다리다 실을 놓았다.<br>가슴뼈에 동그란 멍이 남았다. 팀원들은 끝까지 몰랐다. 이쪽이 왜 그 방에서 한참 서 있었는지.`,
      win:{ exp:20, dream:3 } }
  ] },

{ at:'A', t:'통로 — 남이 꼰 실',
  x:`통로 바닥에 실이 깔렸다. 마력으로 꼰 실이다. 빛이 거의 꺼졌다.<br><br>
    다른 결속술사가 꼰 것이다. 꼬임이 왼쪽으로 감겼다. 이쪽과 반대다.<br>
    가닥이 넷. 셋은 끊겼다. 하나가 아직 살아서 떨린다. 아주 약하게. 저 앞 어딘가에서 누가 그 끝을 쥐고 있다.<br><br>
    남의 실을 받아 쥐면 남의 팀을 받아 쥐는 것이다.`,
  o:[
    { l:'① 살아 있는 가닥에 이쪽 실을 이어 받는다.', k:'bond', dc:23, wake:1,
      ok:`왼쪽 꼬임에 오른쪽 꼬임을 맞물렸다. 서로 반대로 감긴 실은 이으면 더 단단해진다.<br><br>실이 다시 빛난다. 저 앞에서 한 번 당겨 온다. 놀란 박자다.<br>따라가니 벽 틈에 사람 하나가 끼어 있다. 다른 팀의 막내다. 그 팀 결속술사는 셋째 가닥 끝에 있었다고 한다. 거기 아무도 없다고.<br><br>막내를 이쪽 줄 맨 뒤에 묶었다. 여섯 가닥이 됐다. 남이 꼰 실을 이쪽 꼬임으로 받아 이었다. 꼬임 방향이 달라도 이어진다는 걸 손이 알았다. 그 뒤로 매듭이 한 가지 더 늘었다.`,
      ng:`맞물리는데 꼬임이 서로 밀어낸다. 실이 튀었다.<br><br>살아 있던 가닥이 끊겼다. 저 앞에서 작은 비명. 그리고 조용하다.<br>뛰어갔다. 벽 틈이 비어 있었다. 실 끝만 남았다. 왼쪽으로 감긴 채.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-20, spirit:-30 } },
    { l:'② 끊긴 셋을 불로 태워 다른 것이 쥐지 못하게 한다.', k:'break', dc:22,
      ok:`끊긴 세 가닥을 모아 등불에 댔다. 마력 실이 파랗게 탄다.<br><br>타는 동안 통로 저편에서 무엇이 물러나는 소리가 났다. 끊긴 실을 붙들고 오려던 것.<br>살아 있는 하나는 남겨 뒀다. 그 끝의 사람이 돌아올 길이다.`,
      ng:`태우는데 불이 실을 타고 번진다. 살아 있는 가닥까지.<br><br>저 앞에서 비명이 났다. 끄려다 손을 데었다. 실은 끝까지 탔다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, spirit:-20 } }
  ] },

{ at:'A', t:'깊은 곳 — 짧아지는 실',
  x:`팀원 다섯과 이어진 실이 짧아진다. 아무도 감지 않았다.<br><br>
    한 걸음 떨어져 걷던 팀원이 반 걸음으로 붙는다. 다시 어깨가 닿는다. 다섯이 한 덩어리로 몰린다.<br>
    실 가운데쯤에서 무엇이 실을 감아 쥔다. 보이지 않는다. 다섯을 한 번에 들어 올리기 좋게.<br><br>
    몰려 있으면 한 번에 들린다.`,
  o:[
    { l:'① 마력을 풀어 실을 늘려 다섯을 흩는다.', k:'bond', dc:23, cost:{ mana:28 },
      ok:`마력을 실에 풀었다. 감긴 만큼 늘어나게. 다섯 팀원에게 흩어지라고 손짓했다.<br><br>실이 늘어난다. 가운데를 쥔 것이 감아도 감아도 끝이 멀어진다. 다섯이 다섯 방향으로 벽에 붙었다.<br>가운데 허공에서 무엇이 한 번 크게 들썩이더니 놓았다. 실이 바닥으로 늘어진다.<br><br>마력이 다 빠졌다. 그래도 다섯은 다섯 군데에 있다.`,
      ng:`늘리는 속도보다 감는 속도가 빨랐다.<br><br>다섯이 한 덩어리로 끌려 붙었다. 발이 동시에 바닥을 떴다. 반 뼘. 그리고 떨어졌다. 다 같이 엉켜 굴렀다. 누구 팔꿈치가 누구 눈에 들어갔다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-30, mind:-14 } },
    { l:'② 실을 다 끊고 맨손으로 서로 손을 잡게 한다.', k:'steady', dc:23, wake:1,
      ok:`실 다섯 가닥을 한꺼번에 끊었다. 가운데를 쥔 것이 빈 실을 감는다.<br><br>대신 손을 잡으라고 했다. 맨손. 다섯이 손을 잡고 한 줄로 걸었다. 실보다 짧고 실보다 따뜻하다.<br>뒤에서 빈 실 감는 소리가 오래 났다. 감을 것이 다 떨어지자 멈췄다.<br><br>실을 놓는 것도 실 다루는 일이다. 언제 꼬고 언제 끊는지. 끊을 때를 아는 손이 됐다. 끊은 손이 다시 잡을 손을 찾았다.`,
      ng:`끊는 순간 팀원 하나가 손을 놓쳤다. 어둠 속에서 두 걸음 떨어졌다.<br><br>찾았다. 찾는 동안 무엇이 그 팀원 등에 손을 얹고 있었다. 떼어 낼 때 그 팀원 등에서 김이 났다.`,
      win:{ exp:22, dream:3 }, lose:{ mind:-20, spirit:-26 } }
  ] },

{ at:'A', t:'쉬는 자리 — 바닥난 숨',
  x:`쉬는 자리에서 팀원 하나가 일어나지 못한다. 다친 데는 없다. 숨이 얕다. 눈이 멀다.<br><br>
    아까 계단에서 무엇이 그 팀원 등을 오래 쓰다듬었다. 그 뒤로 이렇다.<br>
    가져간 것이 기운이라면 돌려줄 수 있다. 실로. 이쪽 것을.<br><br>
    마력이 넉넉하지 않다. 아래층은 아직 길다.`,
  o:[
    { l:'① 마력 실로 이쪽 기운을 건넨다.', k:'bond', dc:22, cost:{ mana:26 }, wake:1,
      ok:`팀원 손목에 실을 감고 마력을 흘렸다. 이쪽 숨을 실에 태워 보냈다.<br><br>팀원 눈에 초점이 돌아온다. 숨이 깊어진다. 대신 이쪽 손끝이 차가워졌다.<br>건너가는 게 마력만이 아니다. 따뜻함이 같이 간다. 실 끝에서 팀원 맥이 이쪽 맥과 박자를 맞춘다.<br><br>잠깐이었지만 두 사람이 한 숨으로 쉬었다. 실이 숨을 나눠 쓰는 길이 될 수 있다는 걸 손목이 기억한다. 다음엔 덜 떨 것이다.`,
      ng:`흘리는데 실 중간에서 마력이 샌다. 무엇이 실 가운데를 입에 문 것처럼.<br><br>건너간 건 반도 안 된다. 팀원은 그대로고 이쪽만 비었다. 둘이 나란히 누웠다.`,
      win:{ exp:22, dream:3, spirit:8 }, lose:{ mind:-20, spirit:-24 } },
    { l:'② 실을 떼어 내고 몸을 덥혀 재운다.', k:'heal', dc:22,
      ok:`손목 실을 떼어 냈다. 실을 타고 다른 게 더 빠져나갈 수도 있다.<br><br>겉옷을 덮고 등을 문질렀다. 쓰다듬긴 자리가 얼음장이다. 손바닥으로 오래 데웠다.<br>새벽에 팀원이 일어났다. 기운은 반만 돌아왔다. 반으로 걸었다.`,
      ng:`실을 떼자 팀원 숨이 더 얕아진다. 실이 붙들고 있던 것이다.<br><br>다시 감으려는데 팀원이 손을 뿌리친다. 차갑다고. 이쪽 손이 차갑다고. 밤새 아무도 못 잤다.`,
      win:{ exp:16, dream:2, hp:6 }, lose:{ hp:-22, mind:-18 } }
  ] },

{ at:'A1', t:'인형극 무대 — 위에서 내려온 줄',
  x:`인형극 무대 막이 반쯤 걷혔다. 손 인형 셋이 무대 턱에 기대 있다. 방글이, 뭉치, 삐뚤이.<br><br>
    손 인형인데 손이 안 들어가 있다. 그런데 움직인다. 머리 위에서 가는 줄이 내려와 있다.<br>
    줄은 천장 어둠으로 올라간다. 마력 실과 닮았다. 꼬임만 다르다.<br><br>
    셋째 팀원 손목에도 그 줄 하나가 와서 감겼다. 이쪽 실 바로 옆에. 팀원은 모른다.`,
  o:[
    { l:'① 마력으로 이쪽 실을 그 줄에 감아 엮은 뒤 함께 끊는다.', k:'bond', dc:23, cost:{ mana:30 }, wake:1,
      ok:`이쪽 실을 위에서 내려온 줄에 한 바퀴 감았다. 마력으로 꼬아 붙였다. 두 줄이 한 줄이 됐다.<br><br>그리고 이쪽 실째 끊었다. 엮인 줄도 같이 끊긴다. 천장에서 무엇이 휘청하는 소리.<br>무대 위 손 인형 셋이 동시에 고개를 떨궜다. 셋째 팀원 손목이 풀렸다. 이쪽 실을 다시 꼬아 이었다.<br><br>남의 줄을 끊지 못할 때는 이쪽 실로 감아서 같이 끊는다. 손해를 보고 끊는 법. 마력보다 실 한 가닥이 싸다. 그 셈이 손에 붙었다.`,
      ng:`감는데 위의 줄이 이쪽 실을 타고 내려온다. 거꾸로.<br><br>이쪽 손목에 줄이 감겼다. 팔이 저절로 올라간다. 손을 흔든다. 인형처럼. 팀원들이 팔을 붙들어 내리고 칼로 줄을 잘랐다. 어깨가 한참 저렸다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-22, spirit:-26 } },
    { l:'② 줄이 어디서 내려오는지 위를 올려다본다.', k:'gaze', dc:23,
      doom:{ title:'인형 줄', what:'줄에 매달려 천장 어둠으로 끌려 올라갑니다', dc:18, sec:50,
        text:`고개를 들었다. 천장 어둠 속에 조명 다리가 있다. 거기 손이 수십 개다. 하얀 장갑들. 장갑마다 줄을 쥐었다.<br><br>그중 하나가 이쪽을 내려다보듯 손가락을 까딱했다.<br>이쪽 손목에 줄이 감긴다. 실 다섯 가닥 사이로. 몸이 위로 들린다. 발끝이 무대 턱에 끌린다.<br><br>팀원들이 이쪽 발목을 쥔다. 위에서 장갑들이 줄을 감는다.`,
        dieText:`무대 위 손 인형이 넷이 됐다.<br><br>넷째는 손이 들어가 있다. 실 다섯 가닥이 손목에서 늘어져 무대 아래로 흘러내린다. 팀원들 손목으로.<br>팀원들이 실을 당기면 넷째 인형이 손을 흔든다. 웃는 입으로.` },
      ok:`고개를 들었다. 조명 다리에 하얀 장갑 수십 개가 줄을 쥐고 있다.<br><br>세어 봤다. 줄 하나에 장갑 하나. 셋째 팀원 줄을 쥔 장갑만 손가락이 하나 모자란다.<br>그 줄만 힘이 약하다. 팀원 손목을 당겨 그 줄을 뺐다. 장갑이 줄을 다시 내리는 데 한참 걸렸다. 그 사이 무대를 지났다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A1', t:'방청석 — 박수를 맞추는 실',
  x:`방청석에 앉자 박수가 시작됐다. 빈 의자들에서. 똑같은 박자로.<br><br>
    다섯 팀원의 손이 무릎 위에서 들썩인다. 따라 치려 한다. 이쪽 손목 실이 박수 박자로 떨린다.<br>
    실이 이쪽 실이 아니게 되고 있다. 방청석 전체가 한 실에 꿰인 것처럼 박자가 하나다.<br><br>
    박자에 꿰이면 다 같이 일어난다. 다 같이 무대로 나간다.`,
  o:[
    { l:'① 손목 실을 엇박으로 당겨 팀원들 박자를 깬다.', k:'bond', dc:23, wake:1,
      ok:`박수 사이사이에 실을 당겼다. 짝, 당김, 짝, 당김.<br><br>팀원들 손이 박수 대신 이쪽 당김을 따른다. 한 박자씩 밀린다. 방청석 박자에서 다섯만 빠졌다.<br>박수가 끝나자 빈 의자들이 일제히 일어섰다. 다섯 의자만 그대로 앉아 있었다. 이쪽 팀이 앉은 의자.<br><br>남의 박자에 꿰인 실을 이쪽 박자로 되찾는 법. 실은 박자로도 묶인다. 이쪽 실에 이쪽 박자를 새겼다. 손이 그 박자를 잊지 않는다.`,
      ng:`엇박으로 당기는데 이쪽 손이 박수를 쳤다. 한 번.<br><br>그 한 번에 다섯 팀원이 다 따라 쳤다. 이쪽이 이끈 꼴이다. 박수 소리에 무대 조명이 이쪽 줄을 비췄다. 앞으로 나와 볼 친구.<br>다 같이 엎드려 의자 밑으로 기었다. 무릎이 다 까졌다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-22, mind:-20 } },
    { l:'② 팀원들 손을 등 뒤로 모아 실로 느슨하게 묶는다.', k:'fix', dc:22,
      ok:`팀원들 손을 등 뒤로 모으게 하고 손목 실로 느슨하게 감았다. 칠 수 없게.<br><br>박수가 계속된다. 다섯 손이 등 뒤에서 들썩이다 지친다. 박자가 다섯을 놓쳤다.<br>끝까지 앉아 있다 일어섰다. 손을 풀자 팀원 하나가 이쪽 손바닥을 한 번 쳤다. 고맙다고. 박자에 안 맞게.`,
      ng:`묶는데 팀원 하나가 손을 빼 박수를 쳤다. 웃고 있다. 눈은 안 웃는다.<br><br>그 팀원이 일어선다. 붙들어 앉히느라 둘이 넘어졌다. 의자 모서리에 이마가 찢어졌다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, spirit:-18 } },
    { l:'③ 귀를 막고 박자를 세지 않는다.', k:'steady', dc:23,
      ok:`귀를 손바닥으로 막았다. 팀원들에게도 그러라고 고갯짓했다.<br><br>소리가 줄자 박자도 흐려진다. 무릎이 들썩이는 게 멎었다. 실이 다시 이쪽 실로 돌아왔다. 조용히.<br>박수가 끝날 때까지 다섯이 귀를 막고 앉아 있었다.`,
      ng:`귀를 막았는데 박자가 손바닥을 타고 들어온다. 맥박이 박수에 맞춰 뛴다.<br><br>가슴이 아프다. 심장이 남의 박자를 따라가고 있다. 손을 떼고 크게 숨을 쉬었다. 박자가 흐트러졌다. 그때까지 숨이 반은 멎어 있었다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'A1', t:'의상실 — 탈 속의 실',
  x:`의상실에서 팀원 하나가 안 보인다. 실은 팽팽하다. 레일에 걸린 인형탈 쪽으로.<br><br>
    뭉치 탈이다. 갈색 털. 지퍼가 등까지 올라가 있다. 탈이 숨을 쉰다.<br>
    실이 탈 등 쪽 지퍼 틈으로 들어간다. 팀원이 안에 있다. 입혀졌다.<br><br>
    결속술사는 실이 사람에게 닿아 있는 한 그 사람을 꺼낼 수 있다고 믿는다.`,
  o:[
    { l:'① 마력을 실어 실째로 팀원을 탈 밖으로 끌어낸다.', k:'bond', dc:24, cost:{ mana:30 },
      doom:{ title:'뭉치 탈', what:'실째 탈 안으로 함께 끌려 들어갑니다', dc:18, sec:50,
        text:`실에 마력을 부어 당겼다. 탈 안에서 팀원이 따라 나온다. 손이 지퍼 틈으로 보인다.<br><br>그런데 탈도 당긴다. 안쪽에서. 털이 이쪽 실을 감아 쥔다. 실이 지퍼 틈으로 빨려 들어간다. 이쪽 손목째.<br>탈 안이 따뜻하다. 아주 따뜻하다. 팔꿈치까지 들어갔다. 누가 안에서 이쪽 손을 잡는다. 팀원 손인지 모르겠다.`,
        dieText:`레일 위 뭉치 탈이 무거워졌다. 등 지퍼가 끝까지 올라갔다.<br><br>탈 손목 언저리에서 실 다섯 가닥이 늘어져 있다. 팀원들이 당기면 탈이 손을 흔든다. 한 손이 아니라 두 손으로. 안에 둘이 있다.<br>다음 회 출연자 명단에 뭉치가 둘로 적혔다.` },
      ok:`실에 마력을 부어 당겼다. 탈이 안에서 버틴다. 다른 팀원들에게 지퍼를 내리라고 했다.<br><br>안과 밖에서 같이 당겼다. 지퍼가 내려간다. 털 속에서 팀원 얼굴이 나왔다. 땀범벅이다. 눈이 풀려 있다.<br>끌어냈다. 탈이 빈 채로 레일에서 흔들린다. 안쪽 털이 젖어 있다. 땀이 아니다.<br><br>팀원은 한동안 따뜻했다고만 했다. 너무 따뜻해서 나오기 싫었다고.`,
      win:{ exp:24, dream:3 } },
    { l:'② 탈 지퍼 고리를 찾아 바깥에서 연다.', k:'fix', dc:23,
      ok:`실을 쥔 채 탈 등을 더듬었다. 지퍼 고리가 털 속에 숨어 있다. 안쪽으로 꺾여서.<br><br>칼끝으로 고리를 끌어냈다. 천천히 내렸다. 탈이 몸을 비튼다. 그래도 지퍼는 내려간다.<br>팀원이 쏟아지듯 나왔다. 탈 안쪽에 손바닥 자국이 가득하다. 팀원 것보다 작은 손.`,
      ng:`고리를 찾는데 털이 손가락을 감는다. 따뜻하고 끈적하다.<br><br>손을 빼는 데 피부가 한 꺼풀 벗겨졌다. 지퍼는 끝내 못 열었다. 칼로 탈을 찢었다. 찢긴 자리에서 숨소리가 새어 나왔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-18 } }
  ] },

{ at:'A1', t:'부조정실 — 실처럼 감긴 선',
  x:`부조정실 바닥이 선투성이다. 굵은 선, 가는 선. 다 엉켜서 한쪽 벽 구멍으로 들어간다.<br><br>
    선 하나가 꿈틀한다. 그다음 하나. 맥박처럼 순서대로.<br>
    실을 다루는 손은 엉킨 것을 보면 끝을 찾는다. 이 선들은 끝이 두 개다. 한쪽은 이 방. 한쪽은 위층 스튜디오.<br><br>
    모니터 하나에 스튜디오가 비친다. 빈 의자 하나에 조명이 들어와 있다.`,
  o:[
    { l:'① 이쪽 실 한 가닥을 선 다발에 섞어 흐름을 읽는다.', k:'sense', dc:23, wake:1,
      ok:`실 한 가닥을 풀어 선 다발 사이에 끼웠다. 손끝을 실에 대고 기다렸다.<br><br>선이 꿈틀할 때마다 실이 떨린다. 떨림이 어디서 와서 어디로 가는지 읽었다. 위층 스튜디오에서 내려와 이 방을 지나 벽 구멍 속으로. 무엇이 선을 타고 오르내린다.<br>떨림이 없는 선 하나를 찾았다. 그 선을 따라가면 비상계단이다. 무엇도 그 길로는 안 다닌다.<br><br>실을 남의 줄 사이에 끼워 그 줄이 하는 말을 듣는 법. 실 끝이 귀가 됐다. 손끝이 오래 그 떨림을 기억했다.`,
      ng:`끼운 실이 떨리다 갑자기 팽팽해진다. 선을 타고 오던 것이 이쪽 실을 찾았다.<br><br>실이 손끝을 끌어당긴다. 벽 구멍 쪽으로. 실을 끊었다. 손끝에 화상 자국이 남았다. 전기에 덴 것처럼.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-22, spirit:-24 } },
    { l:'② 꿈틀거리는 선을 한꺼번에 잘라 낸다.', k:'break', dc:22,
      ok:`칼로 다발 한가운데를 갈랐다. 불꽃이 튀었다.<br><br>모니터가 한꺼번에 꺼졌다. 스튜디오 빈 의자의 조명도. 벽 구멍 속에서 무엇이 멈춘 소리가 난다.<br>얼마 안 가 선들이 다시 꿈틀했다. 잘린 끝이 서로를 찾아 기어간다.`,
      ng:`가르는 순간 선 하나가 칼을 감고 이쪽 팔까지 올라왔다.<br><br>찌릿한 게 어깨까지 갔다. 손이 칼을 놓지 못한다. 팀원이 이쪽을 걷어차 떼어 냈다. 손바닥이 탔다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-30, mind:-14 } }
  ] },

{ at:'A1', t:'생방송 직전 — 오늘의 친구 의자',
  x:`스튜디오 한가운데에 의자 하나. 등받이에 별이 붙었다. 오늘의 친구.<br><br>
    팀원 하나가 거기 앉아 있다. 언제 앉았는지 본인도 모른다. 손목에 리본이 감겨 의자 팔걸이에 묶였다. 분홍 리본. 나비 모양 매듭.<br>
    카메라 빨간 불이 하나씩 켜진다. 셋 중 하나가 켜졌다.<br><br>
    매듭을 보면 누가 맸는지 안다. 이건 선물 포장하는 손이다. 다정하고, 풀 생각이 없다.`,
  o:[
    { l:'① 리본 매듭을 이쪽 매듭으로 바꿔 맨다.', k:'bond', dc:24, wake:1,
      ok:`리본을 풀지 않았다. 풀면 다시 묶인다. 대신 나비 매듭 한쪽 고리에 이쪽 실을 꿰었다.<br><br>매듭을 이쪽 방식으로 다시 감았다. 당기면 풀리고 비틀면 조이는 매듭. 의자 쪽으로는 비틀고, 이쪽으로는 당겼다.<br>리본이 팔걸이에서 미끄러져 나온다. 팀원 손목에는 이쪽 실만 남았다. 카메라 두 번째 불이 켜지기 전에 일으켜 세웠다.<br><br>남이 맨 매듭을 풀지 않고 그 위에 이쪽 매듭을 덧매서 주인을 바꾸는 법. 손이 처음 해 본 일인데 처음이 아닌 것처럼 움직였다.`,
      ng:`고리에 실을 꿰는데 리본이 이쪽 실을 같이 감는다. 나비가 둘이 됐다.<br><br>이쪽 손목도 팔걸이에 붙었다. 두 사람이 한 의자에. 카메라 두 번째 불이 켜졌다. 팀원들이 칼로 리본을 끊어 둘을 끌어냈다. 손목에 리본 자국이 분홍색으로 남았다.`,
      win:{ exp:25, dream:4 }, lose:{ mind:-22, spirit:-28 } },
    { l:'② 의자째 들어 카메라 밖으로 옮긴다.', k:'steady', dc:23,
      ok:`팀원 셋이 의자를 같이 들었다. 앉은 사람째로.<br><br>무겁다. 의자가 바닥에 붙으려 한다. 그래도 들렸다. 카메라 앵글 밖으로 세 걸음. 카메라 불이 꺼진다. 화면 밖의 친구는 친구가 아니다.<br>밖에서 리본을 천천히 풀었다. 이번엔 잘 풀렸다.`,
      ng:`드는데 의자 다리가 바닥에서 안 떨어진다. 바닥에 뿌리가 내린 것처럼.<br><br>힘을 주다 허리가 꺾였다. 카메라 두 번째 불이 켜졌다. 앉은 팀원이 웃기 시작했다. 리본을 끊고 끌어냈다. 팀원은 그 뒤로도 가끔 웃는다. 혼자서.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, spirit:-20 } },
    { l:'③ 카메라 렌즈를 겉옷으로 덮는다.', k:'hide', dc:22,
      ok:`켜진 카메라 렌즈에 겉옷을 씌웠다. 빨간 불이 깜빡이다 꺼졌다.<br><br>보는 눈이 없어지자 리본이 느슨해졌다. 사람을 묶어 두는 건 매듭이 아니라 시선이었다.<br>팀원을 빼내고 겉옷은 두고 왔다. 렌즈 앞에서 겉옷이 작게 들썩였다.`,
      ng:`씌우는 사이 둘째 카메라가 돌아 이쪽을 잡았다. 화면에 이쪽 얼굴이 크게.<br><br>스피커에서 박수가 터졌다. 새 친구! 다리가 저절로 의자 쪽으로 걷는다. 팀원들이 붙들었다. 무릎이 바닥에 끌려 피가 났다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, mind:-18 } }
  ] },

{ at:'A2', t:'종탑 — 여섯째 밧줄',
  x:`종탑 창틀 고리에 끊긴 밧줄 다섯. 끝이 다 해졌다. 물 쪽에서 오래 당겨진 자리다.<br><br>
    배를 묶어야 한다. 돌아갈 때 타야 하니까. 그런데 밧줄은 다섯 번 다 못 버텼다.<br>
    물 밑에서 배를 당기는 것은 지치지 않는다. 밤새, 며칠이고.<br><br>
    밧줄은 당기면 해진다. 마력 실은 당겨도 안 해진다. 대신 묶은 사람이 해진다.`,
  o:[
    { l:'① 마력 실로 배를 이쪽 손목에 묶어 둔다.', k:'bond', dc:23, cost:{ mana:28 }, wake:1,
      ok:`배 뱃머리에 실을 감았다. 다른 끝을 손목에. 마력을 실에 남겨 두었다. 이쪽이 멀리 가도 실이 늘어나게.<br><br>층을 내려갈 때마다 손목이 당겨진다. 물 밑의 것이 배를 당기는 박자다. 잠들어도 손목이 대신 버틴다.<br>배가 끌려갈 때마다 이쪽이 조금씩 지친다. 그 대신 배는 그 자리에 있다.<br><br>실 끝에 사람이 아니라 돌아갈 길을 묶었다. 돌아갈 길이 이쪽 손목에 있다. 멀리 가도 끊기지 않는 매듭을 처음 꼬았다. 마력을 오래 남겨 두는 꼬임이 손가락에 익었다.`,
      ng:`묶는데 물 밑에서 배를 확 당겼다. 실이 손목을 파고든다.<br><br>창틀을 붙들고 버텼다. 실을 끊을 수밖에 없었다. 배가 한 뼘 가라앉았다가 떠올랐다. 밧줄로 다시 묶었다. 여섯째 밧줄로.<br>손목에 실 자국이 얼음처럼 차다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-24, spirit:-26 } },
    { l:'② 밧줄을 두 겹으로 꼬아 고리에 맨다.', k:'fix', dc:22,
      ok:`밧줄 두 가닥을 꼬아 하나로 만들었다. 고리에 두 번 감고 엇매듭.<br><br>당겨지는 힘이 두 가닥에 나뉜다. 버틴다. 오래는 모르지만 지금은.<br>창을 넘으며 매듭 위에 손바닥을 한 번 얹었다. 버텨 달라고.`,
      ng:`꼬는 사이 배가 당겨졌다. 손에 쥔 밧줄이 쓸려 나간다. 손바닥이 쓸렸다.<br><br>겨우 맸다. 매듭이 비뚤다. 내려가는 내내 그 매듭이 마음에 걸렸다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, mind:-16 } }
  ] },

{ at:'A2', t:'물속 복도 — 손을 잡은 줄',
  x:`물 밑 복도를 지나다 등불에 비쳤다. 아이들이 줄을 섰다. 물속에서. 앞사람 손을 뒷사람이 잡고.<br><br>
    줄 맨 끝 아이가 손을 뒤로 내밀고 있다. 비었다.<br>
    그 손이 이쪽 팀원 손을 잡았다. 팀원이 숨을 참은 채 굳었다. 이쪽 손목 실이 줄 쪽으로 당겨진다.<br><br>
    손을 잡은 줄은 실과 같다. 끝을 잡으면 이어진다. 이어지면 같이 간다.`,
  o:[
    { l:'① 실에 마력을 실어 팀원을 줄에서 끌어낸다.', k:'bond', dc:24, cost:{ mana:30 },
      doom:{ title:'잡은 손', what:'손을 잡은 줄 속으로 끌려갑니다', dc:18, sec:45,
        text:`실을 당겼다. 팀원이 이쪽으로 끌려온다. 아이 손이 따라온다. 놓지 않는다.<br><br>줄 전체가 한 번 움직였다. 앞에서부터. 아이들이 한 걸음씩 걷기 시작한다. 복도 저편 어둠으로.<br>실이 팽팽하다. 팀원이 끌려간다. 실 끝의 이쪽도. 줄이 하나 길어졌다. 이쪽이 맨 끝이다.<br><br>맨 끝은 손을 뒤로 내밀게 된다. 이쪽 손이 저절로 뒤로 간다.`,
        dieText:`팀원들이 물 위로 올라와 숨을 몰아쉬었을 때 둘이 없었다.<br><br>다음 층 물 밑에서 줄을 다시 봤다. 아이들 줄. 맨 끝 둘이 어른 키다.<br>맨 끝 사람이 손을 뒤로 내밀고 있다. 손목에 빛이 다 꺼진 실이 감겨 있다.` },
      ok:`실을 당기는 대신 실을 아이 손목에도 감았다. 팀원과 아이를 한 실로 묶었다. 그리고 그 실을 줄 앞 아이 손목에 이었다.<br><br>맨 끝 아이 손이 앞 아이와 이어졌다. 이제 뒤로 내밀 이유가 없다. 아이가 팀원 손을 놓고 앞사람 손을 잡았다.<br>줄이 다시 고요해졌다. 팀원을 끌어 물 위로 올라왔다. 실 한 가닥은 두고 왔다. 줄 끝 아이 손목에.`,
      win:{ exp:24, dream:3 } },
    { l:'② 줄 맨 끝 아이 손가락을 하나씩 편다.', k:'gaze', dc:23,
      ok:`아이 손을 봤다. 손가락 넷이 팀원 손을 쥐었고 엄지는 비었다. 엄지만 다르게 굽어 있다. 오래 무엇을 쥐었던 모양이다.<br><br>팀원 손에서 반지를 빼 아이 엄지에 걸어 줬다. 아이 손이 반지를 쥔다. 팀원 손을 놓았다.<br>물 위로 올라와 팀원이 울었다. 어머니 반지였다고. 다시 내려가지 않았다.`,
      ng:`손가락을 펴는데 하나 펼 때마다 다른 하나가 다시 쥔다.<br><br>숨이 다 됐다. 팀원 얼굴이 하얗다. 억지로 떼어 냈다. 팀원 손등에 아이 손톱 자국 넷이 파였다. 물이 들어가 퍼렇다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-16 } },
    { l:'③ 숨이 다하기 전에 일단 팀원을 끌고 물 위로 오른다.', k:'evade', dc:23,
      ok:`팀원 허리를 감고 발을 찼다. 물 위로.<br><br>아이 손이 끝까지 따라 올라온다. 수면에서 놓았다. 물 밖으로는 못 나온다.<br>숨을 몰아쉬며 내려다보니 줄이 다시 손을 뒤로 내밀고 있다. 다음 사람을 기다리며.`,
      ng:`차고 오르는데 다리가 물풀에 감겼다. 아니다. 다른 아이 손이었다.<br><br>둘을 달고 올라왔다. 수면에서 겨우 떨어졌다. 물을 한참 토했다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-32, spirit:-18 } }
  ] },

{ at:'A2', t:'기숙사 — 침대에 묶인 손목',
  x:`이층 침대 위 칸에 끈이 묶여 있다. 운동화 끈이다. 한쪽은 침대 기둥에. 한쪽은 끝이 고리가 되어 비었다.<br><br>
    고리 크기가 아이 손목만 하다. 안쪽이 닳았다. 아주 오래 끼고 있었다.<br>
    기둥에 연필로 적혔다. 점호 때 대답 안 하려고. 안 끌려가려고.<br><br>
    누가 스스로를 묶었다. 그리고 지금 그 고리는 비었다.`,
  o:[
    { l:'① 그 매듭을 읽어 이 아이가 어떻게 풀려났는지 안다.', k:'bond', dc:23, wake:1,
      ok:`매듭을 손끝으로 읽었다. 아이 손이 맨 매듭이다. 서툴다. 그런데 한 군데가 다르다. 마지막 고리가 어른 손으로 다시 감겼다.<br><br>누가 와서 고쳐 매 줬다. 더 단단히. 풀리지 않게. 그리고 아이는 고리에서 빠져나갔다. 손목을 줄여서. 물이 된 손목으로.<br>고리를 풀어 주었다. 이제 기다릴 손목이 없다. 끈을 침대에 반듯이 내려놓았다.<br><br>매듭 하나에 손이 둘 남는다. 맨 손과 고친 손. 그 둘을 가려 읽는 눈이 생겼다. 매듭이 누구 편이었는지까지.`,
      ng:`매듭을 읽는데 손끝이 고리 안으로 들어갔다. 고리가 조였다.<br><br>이쪽 손가락이 묶였다. 침대 기둥 쪽으로 당겨진다. 침대 밑 물이 출렁인다. 팀원이 끈을 잘라 줬다. 손가락에 끈 자국이 하얗게 남았다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-20, spirit:-26 } },
    { l:'② 매듭을 건드리지 않고 침대 위 칸에 숨어 점호를 넘긴다.', k:'hide', dc:22,
      ok:`위 칸에 다섯이 겹쳐 누웠다. 끈 옆에. 물이 아래 칸까지 찼다.<br><br>점호가 지나갔다. 이름들. 이 침대 아이 이름도 불렸다. 대답이 없다. 사감 발소리가 멈췄다가, 지나갔다.<br>끈이 아이 대신 대답을 안 해 준 것이다. 그날 밤 그 침대 위 칸만 아무도 안 불렸다.`,
      ng:`겹쳐 눕는데 침대가 기울었다. 무게가 넘쳤다.<br><br>맨 아래 팀원이 아래 칸 물로 반쯤 미끄러졌다. 점호 소리가 물속에서 그 귀에 바로 들렸다. 대답하려는 입을 다 같이 막았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, mind:-20 } }
  ] },

{ at:'A2', t:'수영장 — 레인 줄',
  x:`수영장 물이 검다. 레인 줄이 수면에 떠 있다. 동그란 부표가 줄줄이.<br><br>
    건너편에 탈의실 문이 있다. 레인 다섯 개를 건너야 한다.<br>
    레인마다 물살이 다르다. 한쪽 방향으로만 흐른다. 누가 물속에서 계속 헤엄치는 것처럼.<br><br>
    손목의 실이 물살을 따라 늘어진다. 레인마다 다른 쪽으로.`,
  o:[
    { l:'① 레인 줄에 이쪽 실을 감아 다섯을 줄줄이 건너게 한다.', k:'bond', dc:23, cost:{ mana:27 },
      ok:`레인 줄 부표마다 실을 감았다. 마력으로 고정했다. 실이 물 위 난간이 됐다.<br><br>팀원들이 난간을 잡고 한 레인씩 건넜다. 물살이 발을 끈다. 난간이 버틴다.<br>셋째 레인에서 물속의 것이 난간을 한 번 당겼다. 실이 울었다. 끊어지지 않았다. 다섯이 다 건넜다.<br><br>마력이 바닥났다. 실은 두고 왔다. 레인 줄에 감긴 채 빛이 천천히 꺼져 갔다.`,
      ng:`감는 사이 물살이 실을 끌고 간다. 셋째 부표에서 실이 미끄러졌다.<br><br>난간이 끊겼다. 셋째 레인 한가운데서 팀원 하나가 물살에 휩쓸렸다. 실을 다시 던져 건졌다. 둘 다 물을 한참 먹었다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-32, mind:-16 } },
    { l:'② 레인을 건너지 않고 수영장 벽을 따라 돌아간다.', k:'evade', dc:22,
      ok:`수영장 가장자리 턱을 따라 걸었다. 물에 발을 안 담그고.<br><br>멀다. 레인 끝을 하나씩 지날 때마다 물살이 이쪽 발밑을 향해 꺾인다. 기다린다.<br>턱이 미끄럽다. 다섯이 벽에 손을 짚고 끝까지 갔다. 아무도 안 빠졌다.`,
      ng:`턱 한 군데가 깨져 있었다. 맨 앞이 미끄러졌다.<br><br>물에 반쯤 빠졌다. 물살이 다리를 문다. 실을 당겨 끌어올렸다. 다리에 물살 자국처럼 멍이 길게 들었다.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-26, spirit:-18 } }
  ] },

{ at:'A2', t:'강당 — 명찰을 꿴 실',
  x:`강당 관람석 의자마다 명찰이 놓였다. 수놓은 명찰. 이름, 학년, 반.<br><br>
    명찰마다 실이 꿰어 있다. 젖은 실이 의자 밑으로 늘어져 물속으로 간다. 이백 개가 넘는 실.<br>
    맨 끝 다섯 의자의 명찰은 새것이다. 이쪽 팀 이름이다. 학년 반 칸은 비었다. 바늘이 아직 꽂혀 있다.<br><br>
    바늘을 뽑으면 끝난다. 실 끝을 매면 그때부터 학생이다.`,
  o:[
    { l:'① 다섯 명찰의 실을 이쪽 실로 바꿔 꿰어 맨다.', k:'bond', dc:24, wake:1,
      ok:`명찰마다 젖은 실을 뽑아냈다. 바늘은 그대로 두고. 그 자리에 이쪽 마력 실을 꿰었다. 실 끝은 물속이 아니라 팀원 손목으로.<br><br>명찰이 팀원과 이어졌다. 학교가 아니라. 물속에서 실을 기다리던 것이 빈 바늘귀만 더듬는다.<br>명찰 다섯을 떼어 품에 넣었다. 이제 이 명찰은 이쪽 팀 것이다. 이 학교 것이 아니라.<br><br>무엇에 묶였는지 보다 어디로 이어졌는지가 사람을 정한다. 실 끝을 옮겨 매는 것만으로 사람의 자리를 옮겼다. 그 손놀림이 몸에 새겨졌다.`,
      ng:`뽑는데 젖은 실이 손가락에 감긴다. 바늘이 이쪽 손끝을 찔렀다.<br><br>피 한 방울이 명찰에 떨어졌다. 학년 칸에 숫자가 수놓아지기 시작한다. 저절로. 팀원들이 이쪽 손에서 명찰을 쳐냈다. 숫자는 반만 수놓였다.`,
      win:{ exp:25, dream:4 }, lose:{ mind:-22, spirit:-30 } },
    { l:'② 명찰 다섯을 뜯어 물에 던진다.', k:'break', dc:23,
      ok:`명찰 다섯을 한꺼번에 뜯었다. 실째 뽑아 물에 던졌다.<br><br>물속 실이 명찰을 받아 끌고 간다. 이쪽 이름 다섯이 가라앉는다. 그걸 보고 있기가 이상했다.<br>바늘 다섯이 의자에 남았다. 아무것도 꿰지 않은 채로.`,
      ng:`뜯는데 실이 질기다. 명찰이 안 떨어진다. 힘을 주다 손바닥이 실에 갈렸다.<br><br>겨우 뜯었다. 던지려는데 맨 끝 팀원이 자기 명찰을 품에 넣었다. 버리기 싫다고. 그 팀원은 그 뒤로 이름을 부르면 대답이 한 박자 늦다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-22 } }
  ] },

]);

// ------------------------------------------
// 견습 기사 · 무력
// ------------------------------------------
kJob('knight', 'A', [

{ at:'A', t:'긴 복도 — 등 뒤의 이름',
  x:`긴 복도를 걷는다. 등 뒤에서 누가 맨 뒷사람 이름을 부른다. 다정한 목소리다.<br><br>
    맨 뒷사람 어깨가 굳는다. 돌아보고 싶어 한다. 돌아보면 안 된다는 걸 다 안다. 안다고 안 돌아보는 건 아니다.<br>
    견습 기사는 맨 앞에 서는 게 일이라고 배웠다. 위험은 앞에서 온다고.<br><br>
    여기서는 뒤에서 온다.`,
  o:[
    { l:'① 무력을 끌어올려 맨 뒤로 가서 등으로 막는다.', k:'steady', dc:23, cost:{ might:28 }, wake:1,
      ok:`줄 맨 뒤로 갔다. 맨 뒷사람을 앞으로 보냈다. 이쪽 등이 복도 어둠을 향한다.<br><br>이름이 다시 불린다. 이번엔 이쪽 이름이다. 등에 힘을 넣었다. 견갑골 사이가 단단해진다. 부르는 소리가 등에 부딪혀 흩어진다.<br>돌아보지 않고 끝까지 걸었다. 등이 얼음장처럼 차졌다. 그래도 아무도 안 돌아봤다.<br><br>앞에 서는 법만 배웠다. 뒤에 서는 건 다른 일이다. 앞은 눈으로 막고 뒤는 등으로 막는다. 등이 처음으로 방패가 됐다. 그 자세를 몸이 외웠다.`,
      ng:`맨 뒤로 가는 사이 이름이 한 번 더 불렸다. 맨 뒷사람이 반쯤 돌아봤다.<br><br>그 사람 눈이 하얘진다. 무릎이 꺾인다. 붙들어 일으켰다. 어깨 너머로 이쪽도 봤다. 복도 끝에 서 있던 것을. 키가 천장에 닿는다.<br>뛰었다. 그 뒤로 등 뒤가 계속 시리다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-22, spirit:-28 } },
    { l:'② 돌아서서 부르는 쪽을 막아선다.', k:'bond', dc:24,
      doom:{ title:'등 뒤의 이름', what:'부르던 것에게 복도 끝으로 끌려갑니다', dc:18, sec:50,
        text:`돌아섰다. 팀원들 대신 이쪽이 보면 된다고 생각했다.<br><br>복도 끝에 무엇이 서 있다. 키가 천장에 닿는다. 팔이 바닥까지 늘어졌다. 손바닥이 위를 향한다.<br>이름이 불린다. 이번엔 이쪽 이름이다. 본 사람의 이름을 부른다. 발이 앞으로 나간다. 다리가 이쪽 말을 안 듣는다.<br><br>팀원들이 이쪽 허리띠를 붙든다. 발은 계속 앞으로 간다.`,
        dieText:`허리띠가 끊어졌다.<br><br>팀원들은 끝까지 돌아보지 않았다. 이쪽이 마지막으로 소리친 대로. 보지 말라고.<br>복도를 다 지난 뒤 맨 뒷사람 이름이 다시 불렸다. 이쪽 목소리로.` },
      ok:`돌아서되 눈은 바닥에 두었다. 바닥에 그림자가 길게 뻗어 온다. 그 끝을 칼끝으로 짚었다.<br><br>그림자가 멈춘다. 부르는 소리가 끊겼다. 칼끝으로 짚은 채 뒷걸음질로 걸었다. 그림자가 따라오지 못한다.<br>복도 끝에 닿아서야 칼을 들었다. 칼끝이 얼어서 하얗다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A', t:'문 — 저편에서 미는 힘',
  x:`문을 지나 다음 방으로 가야 한다. 다섯이 다 지나가야 한다.<br><br>
    문을 열자 저편에서 민다. 닫으려고. 아니면 들어오려고. 힘이 크다. 문틈으로 차가운 손가락 끝이 보인다.<br>
    누군가 문을 붙들고 있어야 나머지가 지나간다.<br><br>
    문을 붙드는 사람은 마지막에 지나간다. 마지막에 지나가지 못할 수도 있다는 것도.`,
  o:[
    { l:'① 무력을 실어 어깨로 문을 받친다.', k:'steady', dc:23, cost:{ might:30 },
      ok:`어깨를 문에 댔다. 무력을 다리로 내렸다. 발뒤꿈치가 바닥에 박힌다.<br><br>문이 밀린다. 손가락 끝이 문틈에서 더듬는다. 이쪽 어깨를 찾는다. 찾아도 밀리지 않았다.<br>넷이 지나갔다. 마지막으로 이쪽이 몸을 빼며 문을 놓았다. 문이 쾅 닫혔다. 반대편에서 무엇이 한 번 크게 쳤다.<br><br>어깨에 손가락 자국 다섯 개가 검게 남았다.`,
      ng:`어깨를 댔는데 문이 한 번에 밀렸다. 저편 힘이 이쪽 무력보다 세다.<br><br>문틈이 넓어진다. 손가락이 이쪽 귀를 스친다. 다 같이 붙어 밀어 닫았다. 아무도 못 지나갔다. 다른 길을 찾는 데 한참 걸렸다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-32, mind:-14 } },
    { l:'② 팀원들 먼저 보내고 문을 쥔 채 맨 마지막에 빠진다.', k:'bond', dc:23, wake:1,
      ok:`팀원들에게 먼저 가라고 했다. 하나씩. 등을 밀어 보냈다. 손은 문을 쥐고.<br><br>넷째가 지나갈 때 문틈의 손가락이 넷째 옷깃을 잡았다. 이쪽 손으로 그 손가락을 떼어 냈다. 차갑다. 놓지 않으려 한다. 손가락 하나씩.<br>마지막으로 이쪽이 빠졌다. 문이 닫혔다. 손등에 손톱자국이 남았다.<br><br>먼저 보내는 일과 붙드는 일을 한 몸으로 동시에 했다. 한 손은 문, 한 손은 사람. 맨 끝에 서는 게 자리가 아니라 일이라는 걸 손이 먼저 알았다.`,
      ng:`먼저 보내는데 셋째가 문 앞에서 멈췄다. 이쪽을 두고 갈 수 없다고.<br><br>그 사이 문이 밀렸다. 셋째와 이쪽이 같이 넘어졌다. 손가락 끝이 셋째 발목을 쥐었다. 둘이 같이 떼어 내고 굴러 넘어왔다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, spirit:-24 } },
    { l:'③ 문틈의 손가락을 칼로 내리친다.', k:'break', dc:22,
      ok:`칼을 문틈에 내리쳤다. 손가락 끝이 잘려 떨어졌다. 피가 안 난다. 바닥에서 꿈틀댄다.<br><br>저편 힘이 한순간 빠졌다. 그 틈에 다섯이 다 지나갔다.<br>뒤에서 잘린 손가락이 문 밑으로 기어 돌아가는 소리가 났다.`,
      ng:`내리쳤는데 칼이 문틈에 박혔다. 저편에서 칼날을 쥔다.<br><br>당겨도 안 빠진다. 칼을 놓고 다른 길로 돌았다. 맨손으로 다음 층까지 갔다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, mind:-18 } }
  ] },

{ at:'A', t:'계단 — 무거워지는 등',
  x:`다리를 다친 팀원을 업었다. 계단이 길다.<br><br>
    내려갈수록 등이 무거워진다. 계단 하나에 한 줌씩. 업힌 팀원 숨소리는 그대로다.<br>
    업힌 팀원이 귀에 대고 속삭인다. 뒤에 누가 있다고. 자기 등 뒤에. 이쪽 등에 업힌 자기 등에.<br><br>
    돌아보면 누구인지 알 수 있다. 내려놓으면 가벼워진다.`,
  o:[
    { l:'① 돌아보지 않고 업은 채 끝까지 내려간다.', k:'steady', dc:24, wake:1,
      ok:`돌아보지 않았다. 업힌 팀원에게도 돌아보지 말라고 했다. 이쪽 목만 꽉 안으라고.<br><br>무게가 계속 는다. 무릎이 떨린다. 계단 하나에 숨 한 번. 업힌 팀원이 이쪽 목을 꽉 안는다. 그 위의 무엇은 아무것도 안 안는다. 그냥 얹혀 있다.<br>마지막 계단을 내려서자 등이 확 가벼워졌다. 얹힌 것은 계단 끝을 못 넘는다.<br><br>무게가 늘어도 걸음 박자를 바꾸지 않는 법. 업은 사람을 지키는 건 힘이 아니라 박자다. 다리가 그 박자를 기억했다.`,
      ng:`내려가다 무릎이 꺾였다. 업힌 팀원과 같이 계단에 엎어졌다.<br><br>등 위에서 무엇이 내려섰다. 맨발 소리. 계단을 거꾸로 올라간다. 업힌 팀원이 고개를 들어 봤다. 비명을 질렀다. 무엇을 봤는지는 끝내 말하지 않는다.`,
      win:{ exp:24, dream:3, hp:6 }, lose:{ hp:-30, spirit:-22 } },
    { l:'② 팀원을 내려놓고 등 뒤를 확인한다.', k:'gaze', dc:23,
      doom:{ title:'업힌 것', what:'업힌 것에게 목을 감겨 계단 아래로 끌려갑니다', dc:18, sec:50,
        text:`팀원을 계단에 내려놓았다. 등이 가벼워지지 않는다.<br><br>무게는 그대로다. 팀원이 아니었다. 처음부터 둘을 업고 있었다. 하나를 내려놓았을 뿐이다.<br>목에 팔이 감긴다. 차고 길다. 귀에 대고 속삭인다. 이제 둘만 남았다고.<br><br>발이 계단 아래로 걷기 시작한다. 이쪽이 걷는 게 아니다.`,
        dieText:`계단에 남은 팀원이 기어서 내려갔다. 계단 끝에 아무도 없었다.<br><br>계단참 벽에 업은 사람 그림자가 붙어 있다. 등에 하나를 업은 채. 누가 업혔는지는 그림자로는 모른다.<br>그 계단을 내려가는 사람은 가끔 등이 무겁다. 한 사람 몫만큼.` },
      ok:`팀원을 계단에 내려놓았다. 칼을 뽑고 돌아섰다.<br><br>아무것도 없다. 등이 가볍다. 다시 업으려고 팀원 쪽을 봤다. 팀원 등에 무엇이 업혀 있다. 팀원보다 작다.<br>칼등으로 쳐냈다. 작은 것이 계단 위로 굴러 올라갔다. 다시 업고 내려갔다. 이번엔 가벼웠다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A', t:'쉬는 자리 — 맹세를 따라 외는 입',
  x:`쉬는 자리에서 맹세를 왼다. 매일 밤. 다섯 줄. 넷째 줄은 아직 뜻을 다 모른다.<br><br>
    약한 이를 앞에 두지 않는다. 등 뒤의 이를 버리지 않는다. 그 대목에서 어둠 속에서 누가 따라 왼다. 한 박자 늦게.<br>
    따라 외는 목소리가 넷째 줄을 다르게 왼다. 등 뒤의 이를 데려간다.<br><br>
    팀원들이 잠에서 깨 이쪽을 본다. 어느 쪽 목소리가 이쪽인지 모르는 얼굴이다.`,
  o:[
    { l:'① 맹세를 처음부터 소리 내어 끝까지 다시 왼다.', k:'bond', dc:23, wake:1,
      ok:`처음부터 다시 외웠다. 크게. 팀원들 얼굴을 하나씩 보며. 넷째 줄에서 더 크게.<br><br>등 뒤의 이를 버리지 않는다. 따라 외던 목소리가 그 줄에서 엉킨다. 한 박자가 두 박자로 늦어진다. 다섯째 줄에서 끊겼다.<br>팀원들이 이쪽 목소리를 골랐다. 눈이 이쪽에 와 멈춘다.<br><br>맹세는 혼자 외는 건 줄 알았다. 남 앞에서 소리 내 외면 그 사람들이 증인이 된다. 증인이 있는 맹세는 흉내 낼 수 없다. 넷째 줄 뜻이 조금 열렸다.`,
      ng:`다시 외는데 따라 외는 목소리가 이번엔 먼저 나온다. 반 박자 앞에서.<br><br>이쪽이 따라 외는 꼴이 됐다. 입이 저쪽 넷째 줄을 따라 한다. 데려간다. 말이 나오기 전에 팀원이 이쪽 입을 막았다. 혀를 깨물었다.`,
      win:{ exp:24, dream:3, spirit:6 }, lose:{ mind:-22, spirit:-28 } },
    { l:'② 입을 다물고 어둠 쪽을 향해 칼을 무릎에 놓는다.', k:'steady', dc:22,
      ok:`외기를 멈췄다. 칼을 무릎에 가로놓고 어둠을 향해 앉았다.<br><br>따라 외던 목소리가 혼자 남았다. 혼자서는 맹세를 끝까지 못 왼다. 넷째 줄에서 맴돌다 잦아들었다.<br>밤새 그렇게 앉아 있었다. 아침에 칼날에 서리가 앉았다.`,
      ng:`입을 다물었는데 목소리는 계속 왼다. 다섯 줄 다. 이쪽 목소리로.<br><br>팀원 하나가 그 목소리 쪽으로 몸을 돌렸다. 이쪽인 줄 안 것이다. 붙잡아 끌어당겼다. 팀원이 이쪽을 보고 소스라쳤다. 둘 중 누가 진짜냐고.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'A', t:'통로 구석 — 혼자 남은 막내',
  x:`통로 구석에 어린 사람이 웅크리고 있다. 다른 팀 옷이다. 팀이 먼저 갔다고 한다.<br><br>
    운다. 소리가 작다. 등불을 비추자 얼굴을 가린다.<br>
    견습 기사는 늦는 막내를 아무도 안 기다리던 날을 기억한다. 그래서 늘 손을 먼저 내민다.<br><br>
    그런데 등불에 비친 그림자가 웅크리고 있지 않다. 서 있다. 이쪽보다 크게.`,
  o:[
    { l:'① 손은 내밀되 칼 쥔 손은 끝까지 놓지 않는다.', k:'bond', dc:23, wake:1,
      ok:`왼손을 내밀었다. 오른손은 칼자루에 그대로.<br><br>막내가 손을 본다. 칼 쥔 손을 본다. 오래. 그리고 왼손을 잡았다. 따뜻하다. 진짜 손이다.<br>그림자가 천천히 쪼그라든다. 칼 앞에서는 크게 못 선다. 막내를 이쪽 줄 맨 뒤의 앞에 세웠다. 다음 층에서 그 팀을 찾아 돌려줬다.<br><br>내미는 손과 지키는 손은 다른 손이어야 한다. 두 손이 하는 일을 갈라 쓰는 법. 왼손이 다정해지고 오른손이 단단해졌다.`,
      ng:`왼손을 내밀었다. 막내가 잡았다. 차다. 손이 아니라 손 모양의 물이다.<br><br>그림자가 일어선다. 칼을 휘둘렀다. 그림자가 흩어지고 막내도 없다. 왼손에 물기만 남았다. 손등이 며칠 동안 시렸다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-22, spirit:-28 } },
    { l:'② 다가가지 않고 막내 발밑부터 본다.', k:'gaze', dc:22,
      ok:`발을 봤다. 신발이 있다. 끈이 묶였다. 발자국도 있다. 그림자는 사람 그림자다. 등불을 낮추자 그림자가 줄었다.<br><br>등불이 높아서 크게 비쳤을 뿐이다. 겁먹은 쪽은 이쪽이었다.<br>막내를 일으켜 데려갔다. 다음 층에서 그 팀을 만났다. 반장이 막내를 끌어안았다. 이쪽에게는 고개만 숙였다.`,
      ng:`발을 보는데 막내가 고개를 들었다. 웃고 있다.<br><br>울음소리는 그대로인데 얼굴이 웃는다. 뒷걸음질 쳤다. 막내가 따라 일어선다. 등불을 휘둘러 쫓았다. 손등을 할퀴고 어둠으로 갔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-18 } }
  ] },

{ at:'A', t:'좁은 통로 — 앞에서 다가오는 숨',
  x:`통로가 좁다. 어깨 하나 너비. 한 줄로만 갈 수 있다. 맨 앞은 이쪽이다.<br><br>
    앞 어둠에서 숨소리가 다가온다. 아주 느리게. 무엇이 통로를 꽉 채운 채 이쪽으로 기어 온다.<br>
    물러설 데가 없다. 뒤로 돌기엔 통로가 너무 좁다.<br><br>
    등 뒤의 팀원들 숨이 빨라진다. 맨 앞이 버티면 뒤는 물러날 시간이 생긴다.`,
  o:[
    { l:'① 무력을 끌어올려 통로를 막고 버틴다.', k:'steady', dc:24, cost:{ might:32 },
      ok:`발을 넓게 벌려 통로 벽 양쪽에 댔다. 무력을 다리와 팔에 고루 돌렸다. 이쪽이 통로의 문짝이 됐다.<br><br>숨소리가 코앞에서 멈췄다. 축축한 것이 이쪽 가슴을 민다. 밀리지 않았다. 다시 민다. 버텼다.<br>등 뒤에서 팀원들이 한 걸음씩 물러난다. 갈림길까지. 마지막 팀원이 외쳤다. 됐다고.<br><br>그제야 뒷걸음쳤다. 숨소리는 따라오지 않았다. 막힌 자리를 기억하는 것 같았다.`,
      ng:`버텼는데 미는 힘이 아니라 끄는 힘이었다. 가슴에 붙은 것이 이쪽을 앞으로 당긴다.<br><br>발이 미끄러진다. 뒤의 팀원이 이쪽 허리를 끌어안았다. 둘이 같이 뒤로 넘어졌다. 가슴에 붙었던 것이 떨어졌다. 가슴팍 옷이 녹아 있었다.`,
      win:{ exp:22, dream:3 }, lose:{ hp:-34, mind:-16 } },
    { l:'② 팀원들을 벽 틈에 밀어 넣고 그 앞을 등으로 막는다.', k:'bond', dc:23, wake:1,
      ok:`통로 벽에 움푹한 틈이 있다. 사람 하나 겨우. 팀원들을 하나씩 밀어 넣었다. 다섯이 겹쳐 들어갔다. 이쪽은 들어갈 데가 없다.<br><br>틈 앞에 등을 대고 섰다. 얼굴은 통로를 향했다. 숨소리가 지나간다. 이쪽 앞을. 아주 느리게. 무엇이 이쪽 얼굴을 한참 들여다본다. 눈은 감지 않았다.<br>지나갔다. 다리가 풀렸다. 등 뒤 틈에서 팀원들이 이쪽 옷을 꽉 쥐고 있었다. 내내.<br><br>막는다는 게 맞서는 일만은 아니다. 숨길 데를 찾고 그 앞에 서는 것도 막는 일이다. 그 자리를 찾는 눈이 생겼다.`,
      ng:`밀어 넣는데 넷째가 안 들어간다. 틈이 모자라다.<br><br>넷째와 이쪽이 같이 통로에 남았다. 지나가던 것이 넷째 다리를 스쳤다. 넷째가 한참 걷지 못했다. 업고 갔다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-28, spirit:-22 } }
  ] },

{ at:'A', t:'빈 방 — 이쪽 목소리로 하는 명령',
  x:`방이 넓다. 어둡다. 팀원들이 흩어져 벽을 더듬는다. 문을 찾는 중이다.<br><br>
    어둠 속에서 이쪽 목소리가 난다. 이리 와. 여기 문이 있다.<br>
    이쪽은 아무 말도 안 했다. 팀원들은 이쪽 목소리를 따르게 되어 있다. 맨 앞에 서던 목소리니까.<br><br>
    셋째 팀원이 그쪽으로 걷는다. 이쪽 목소리를 믿고.`,
  o:[
    { l:'① 팀원들에게 미리 정한 말을 외치게 하고 답을 기다린다.', k:'bond', dc:23, wake:1,
      ok:`정한 말을 외쳤다. 출발 전에 정한 것. 맨 앞이 누구냐. 답은 셋째 줄 맹세.<br><br>팀원들이 멈춘다. 어둠 속의 이쪽 목소리가 답을 못 한다. 같은 말만 한다. 이리 와.<br>진짜 이쪽이 맹세 셋째 줄을 외쳤다. 팀원들이 이쪽 쪽으로 돌아섰다. 셋째도.<br><br>목소리는 흉내 낼 수 있다. 약속은 흉내 낼 수 없다. 앞에 서는 사람은 목소리보다 약속으로 이끌어야 한다는 걸 알았다. 그 뒤로 매번 출발 전에 새 말을 정한다.`,
      ng:`외쳤는데 어둠 속 목소리가 똑같이 외친다. 같은 말을. 같은 순간에.<br><br>팀원들이 어느 쪽도 못 따른다. 제자리에 굳었다. 셋째만 계속 걷는다. 뛰어가 붙잡았다. 셋째 앞에 벽이 아니라 빈 구덩이가 있었다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-22, spirit:-24 } },
    { l:'② 소리 나는 쪽으로 혼자 먼저 간다.', k:'break', dc:24,
      doom:{ title:'이쪽 목소리', what:'이쪽 목소리를 낸 것에게 어둠 속으로 끌려갑니다', dc:18, sec:50,
        text:`셋째를 제치고 소리 쪽으로 달렸다. 칼을 뽑았다.<br><br>어둠 속에서 이쪽이 서 있다. 이쪽 얼굴, 이쪽 옷. 칼만 없다. 빈손을 내밀고 있다.<br>칼을 휘둘렀다. 그쪽이 칼날을 맨손으로 잡았다. 그리고 당긴다. 칼째. 그쪽 손이 이쪽 손목을 쥔다.<br><br>둘이 같은 얼굴로 서로 당긴다. 그쪽이 조금 더 세다.`,
        dieText:`팀원들이 등불을 켰을 때 방 한가운데에 이쪽이 서 있었다.<br><br>칼이 없다. 빈손을 내밀고 있다. 이리 와, 라고 한다. 이쪽 목소리로.<br>팀원들은 그 손을 잡지 않고 방을 나왔다. 등 뒤에서 목소리가 오래 불렀다. 맹세 셋째 줄을 틀리게 외면서.` },
      ok:`셋째를 제치고 소리 쪽으로 달렸다. 칼을 뽑았다. 휘두르지는 않았다.<br><br>어둠 속에 이쪽이 서 있다. 빈손을 내밀고. 칼끝을 그 가슴에 댔다. 그쪽이 칼을 내려다본다. 칼은 흉내 내지 못했다.<br>칼끝을 밀자 그쪽이 연기처럼 흩어졌다. 뒤에 진짜 문이 있었다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A', t:'쉬는 자리 — 칼날에 비친 것',
  x:`쉬는 자리에서 칼을 닦는다. 칼날이 등불을 받아 거울처럼 빛난다.<br><br>
    칼날에 이쪽 어깨 너머가 비친다. 잠든 팀원들. 그 사이에 누가 앉아 있다. 무릎을 끌어안고. 다섯째 팀원과 넷째 팀원 사이에.<br>
    돌아보면 아무도 없을 것이다. 칼날 속에서만 보인다.<br><br>
    칼날 속의 그것이 다섯째 팀원 머리를 쓰다듬는다.`,
  o:[
    { l:'① 칼날을 비스듬히 들어 그것이 무얼 하는지 끝까지 본다.', k:'gaze', dc:23,
      ok:`칼날을 기울여 각도를 맞췄다. 그것이 한가운데 오게.<br><br>쓰다듬는 손이 다섯째 팀원 귀에 닿는다. 무엇을 속삭인다. 다섯째 입이 잠결에 움직인다. 대답하려 한다.<br>칼날을 등불 쪽으로 돌려 그것 얼굴에 빛을 쏘았다. 칼날 속에서 그것이 얼굴을 가린다. 다섯째 입이 다물렸다. 날이 샐 때까지 빛을 쏘았다.`,
      ng:`각도를 맞추는데 칼날 속 그것이 이쪽을 본다. 칼날을 통해서.<br><br>눈이 마주쳤다. 손이 저절로 칼을 내려놓았다. 정신을 차리니 그것이 쓰다듬던 자리에 이쪽이 앉아 있다. 다섯째 머리에 손을 얹고. 손이 차다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-22, spirit:-26 } },
    { l:'② 무력을 다리에 모아 그 둘 사이에 앉아 밤을 지킨다.', k:'steady', dc:23, cost:{ might:26 }, wake:1,
      ok:`일어나서 넷째와 다섯째 사이로 갔다. 칼날에 비친 그것이 앉은 자리다. 그 자리에 앉았다.<br><br>앉는 순간 엉덩이 밑이 얼음 같다. 무엇 위에 앉은 것이다. 다리에 힘을 모아 버텼다. 밑에서 꿈틀댄다. 일어나지 않았다.<br>새벽녘에 밑이 따뜻해졌다. 그것이 빠져나갔다. 칼날을 들어 비춰 보니 이쪽과 팀원들뿐이다.<br><br>자리를 지키는 법은 그 자리에 앉는 것이다. 막아서는 게 아니라 차지하는 것. 앉은 자세가 그대로 버티는 자세가 됐다.`,
      ng:`그 자리에 앉았는데 밑의 것이 이쪽을 들어 올린다. 반 뼘. 다리 힘이 모자라다.<br><br>그대로 옆으로 밀려났다. 넷째 팀원 위로 넘어졌다. 넷째가 깨서 비명을 질렀다. 다섯째는 끝내 안 깼다. 아침에 다섯째가 꿈 이야기를 했다. 누가 머리를 오래 쓰다듬었다고.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, spirit:-26 } },
    { l:'③ 칼을 내려놓고 팀원들을 깨워 등을 맞대고 앉힌다.', k:'bond', dc:22,
      ok:`팀원들을 흔들어 깨웠다. 다섯이 등을 맞대고 둥글게 앉았다. 가운데 빈자리가 없게.<br><br>칼날을 다시 비춰 보니 그것이 원 밖에 서 있다. 들어올 자리가 없다. 한참 원을 돌다 어둠으로 갔다.<br>아무도 다시 잠들지 못했다. 그래도 다섯이다.`,
      ng:`깨우는데 다섯째가 안 깬다. 흔들어도. 숨은 쉰다.<br><br>넷이 둘러앉아 다섯째를 가운데 눕혔다. 칼날 속의 그것이 다섯째 위에 엎드려 있다. 쫓아내지 못했다. 아침에 다섯째가 깼다. 눈 밑이 검다.`,
      win:{ exp:15, dream:2 }, lose:{ mind:-20, spirit:-22 } }
  ] },

{ at:'A', t:'계단 — 넘어진 팀원의 발목',
  x:`계단을 뛰어 내려가다 팀원 하나가 넘어졌다. 계단참 바닥에 엎어졌다.<br><br>
    계단 틈에서 손이 나와 그 발목을 쥐었다. 하얗고 마른 손. 틈 안쪽으로 당긴다. 틈은 손 하나 너비다. 사람이 들어갈 너비가 아니다.<br>
    그래도 당긴다. 발목이 틈 쪽으로 꺾인다. 팀원이 비명을 지른다.<br><br>
    다른 팀원들은 벌써 아래층 문 앞에 있다.`,
  o:[
    { l:'① 무력을 실어 손목을 칼로 내리친다.', k:'break', dc:23, cost:{ might:28 },
      ok:`칼을 높이 들어 내리쳤다. 무력을 칼끝에 다 실었다. 마른 손목이 끊어졌다.<br><br>끊긴 손은 발목을 쥔 채로 남았다. 손가락을 하나씩 펴서 떼어 냈다. 계단 틈 안에서 무엇이 오래 울었다.<br>팀원 발목에 손 모양 멍. 걸을 수는 있다. 어깨를 빌려줬다.`,
      ng:`내리쳤는데 칼날이 손목 대신 계단 모서리를 쳤다. 칼날이 이 빠졌다.<br><br>손이 발목을 더 꺾는다. 뼈 소리가 났다. 둘째로 내리쳐서 겨우 끊었다. 팀원은 그 뒤로 업혀서만 갔다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-30, mind:-16 } },
    { l:'② 팀원을 끌어안고 같이 버틴다.', k:'bond', dc:24,
      doom:{ title:'계단 틈', what:'끌어안은 팀원과 함께 계단 틈으로 끌려갑니다', dc:18, sec:50,
        text:`팀원을 끌어안았다. 둘 무게면 버틸 줄 알았다.<br><br>틈 속의 손이 하나 더 나온다. 둘. 셋. 이쪽 발목도 쥔다. 둘을 한꺼번에 당긴다.<br>틈이 넓어지고 있다. 계단 판자가 갈라진다. 손 하나 너비가 사람 하나 너비가 된다.<br><br>팀원이 이쪽을 밀어내려 한다. 이쪽은 놓지 않는다.`,
        dieText:`아래층 문 앞의 팀원들이 뛰어 올라왔다. 계단참은 멀쩡했다. 틈은 손 하나 너비였다.<br><br>틈 안에서 두 사람 숨소리가 났다. 아주 가까이. 한참 뒤에 그쳤다.<br>틈 가장자리에 칼 한 자루가 걸려 있다. 칼자루를 끌어안듯 손가락 자국이 남았다.` },
      ok:`팀원을 끌어안았다. 무릎으로 계단참을 버텼다. 소리를 질러 아래 팀원들을 불렀다.<br><br>셋이 뛰어 올라왔다. 다섯이 한 덩어리로 당겼다. 틈 속의 손이 마침내 놓았다. 다섯이 다 같이 뒤로 나뒹굴었다.<br>틈 안에서 손가락이 계단 판자를 긁는 소리가 오래 났다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A', t:'출구 앞 — 마지막 사람',
  x:`아래층으로 가는 문 앞이다. 문이 무겁다. 열면 저절로 닫히려 한다.<br><br>
    문 위에 글씨가 긁혀 있다. 마지막 사람은 남는다.<br>
    벽에 긁힌 자국이 많다. 손톱으로. 문 안쪽에서 바깥쪽으로. 마지막에 남은 사람들이 낸 자국이다.<br><br>
    이쪽은 늘 맨 마지막에 지나간다. 그게 이 자리에 서는 사람의 일이라고 배웠다.`,
  o:[
    { l:'① 이쪽이 마지막이 되되 문을 몸으로 붙든 채 빠진다.', k:'bond', dc:24, wake:1,
      ok:`팀원들을 먼저 보냈다. 넷이 지나갔다. 문이 닫히려 한다. 문짝과 문틀 사이에 이쪽 몸을 끼웠다.<br><br>문이 이쪽을 조인다. 갈비뼈가 운다. 그 상태로 한 발씩 빠져나갔다. 마지막 사람은 문 안쪽에 있는 사람이다. 이쪽은 안쪽도 바깥쪽도 아니다. 문 사이에 있다.<br>다 빠졌을 때 문이 닫혔다. 안쪽에서 긁는 소리가 났다. 이쪽 손톱이 아니었다.<br><br>규칙의 끝자리에 서되 그 자리를 다르게 차지하는 법. 맨 마지막에 서는 일에도 기술이 있다. 몸이 문짝 너비를 외웠다.`,
      ng:`몸을 끼웠는데 문이 너무 세다. 숨이 막힌다. 앞으로 빠지지도 뒤로 물러나지도 못한다.<br><br>팀원들이 문을 반대로 당겨 열었다. 다섯이 다 매달렸다. 겨우 빠져나왔다. 갈비뼈에 금이 갔다.`,
      win:{ exp:25, dream:4 }, lose:{ hp:-34, spirit:-22 } },
    { l:'② 문에 쐐기를 박아 아무도 마지막이 되지 않게 한다.', k:'fix', dc:23,
      ok:`부서진 의자 다리를 주워 왔다. 문틀 밑에 박았다. 칼등으로 두드려.<br><br>문이 닫히려다 쐐기에 걸린다. 떨린다. 버틴다. 다섯이 다 지나갔다. 마지막은 쐐기다.<br>건너편에서 돌아보니 쐐기가 천천히 부서지고 있었다. 무엇이 갉아 먹듯이.`,
      ng:`박는데 쐐기가 미끄러졌다. 문이 확 닫혔다. 손가락 하나가 끼었다.<br><br>빼는 데 한참. 손톱이 들렸다. 다시 박고 지나갔다. 마지막에 지나간 이쪽 등을 문이 쳤다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, mind:-16 } }
  ] },

{ at:'A1', t:'방청석 — 앞으로 나와 볼 친구',
  x:`바람잡이가 방청석을 훑는다. 줄무늬 조끼. 그려 넣은 웃는 입.<br><br>
    손가락이 한 사람씩 짚는다. 앞으로 나와 볼 친구. 손가락이 이쪽 팀 막내에서 멈춘다.<br>
    막내가 몸을 웅크린다. 뒷줄 빈 의자들에서 박수가 시작된다. 재촉하는 박수.<br><br>
    견습 기사는 남이 불려 나갈 때 먼저 일어서는 쪽이다. 일어서는 것과 나가는 것은 다르다.`,
  o:[
    { l:'① 막내 앞에서 먼저 일어서되 무대로는 나가지 않는다.', k:'bond', dc:23, wake:1,
      ok:`일어섰다. 막내 앞을 가렸다. 바람잡이 손가락이 이쪽 가슴에 닿는다.<br><br>그런데 걸어 나가지 않았다. 일어선 채로 섰다. 바람잡이가 손짓한다. 나와요, 나와요. 박수가 커진다. 다리에 힘을 줬다.<br>오래 서 있었다. 바람잡이 웃는 입이 조금씩 처진다. 일어섰는데 안 나오는 사람은 방송 순서에 없다. 손가락이 다른 줄로 넘어갔다.<br><br>앞에 서는 일과 끌려 나가는 일 사이에 선이 있다. 몸으로 그 선 위에 서는 법을 알았다. 일어선 다리가 바닥에 뿌리처럼 붙었다.`,
      ng:`일어섰는데 다리가 저절로 한 걸음 나간다. 박수가 다리를 민다.<br><br>두 걸음째에 팀원들이 이쪽 허리띠를 잡아 앉혔다. 의자에 엉덩이를 찧었다. 바람잡이가 아쉽다는 듯 웃는 입을 더 길게 그렸다. 다음 회에 꼭 나와요.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-22, spirit:-26 } },
    { l:'② 무력을 실어 막내 어깨를 눌러 의자에 붙인다.', k:'steady', dc:22, cost:{ might:27 },
      ok:`막내 어깨를 두 손으로 눌렀다. 무력을 손바닥에 실었다. 의자에서 안 뜨게.<br><br>막내 몸이 들썩인다. 박수가 들어 올리려 한다. 눌렀다. 끝까지.<br>바람잡이 손가락이 한참 머물다 지나갔다. 막내 어깨에 이쪽 손자국이 빨갛게 남았다. 아프다고 한다. 살았으니 아픈 거다.`,
      ng:`눌렀는데 막내가 아니라 이쪽이 들썩였다. 박수가 이쪽 다리를 민다.<br><br>막내 어깨를 짚은 채 같이 일어설 뻔했다. 뒤의 팀원이 두 사람 어깨를 다 눌렀다. 의자 다리가 부러졌다. 셋이 바닥에 나뒹굴었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, mind:-18 } },
    { l:'③ 바람잡이 손가락이 무엇을 세는지 본다.', k:'gaze', dc:23,
      ok:`손가락을 봤다. 짚는 게 사람이 아니다. 무릎이다. 무릎이 떨리는 사람을 짚는다.<br><br>막내 무릎이 떨린다. 이쪽 무릎은 안 떨린다. 막내 무릎에 손을 얹어 눌렀다. 떨림이 멎었다.<br>손가락이 막내를 지나쳤다. 저 뒷줄 어디선가 떨리는 무릎을 찾았다. 거기엔 아무도 없는데 박수가 났다.`,
      ng:`손가락을 보는데 이쪽 무릎이 떨리기 시작했다. 보는 사이에 겁이 들었다.<br><br>손가락이 이쪽으로 왔다. 두 손으로 무릎을 눌렀다. 무릎이 멈추지 않는다. 바람잡이가 이쪽 줄 앞까지 걸어왔다. 숨을 참고 버텼다. 지나갈 때까지 혀를 깨물었다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-22 } }
  ] },

{ at:'A1', t:'분장실 — 넷째 의자',
  x:`분장실 전구 거울 앞에 의자가 다섯. 거울 속엔 의자가 여섯이다.<br><br>
    거울 속 넷째 의자에만 누가 앉아 있다. 뒷모습. 머리를 빗는다. 이쪽 의자 넷째는 비었다.<br>
    팀원 하나가 넷째 의자에 앉으려고 다가간다. 다리가 아프다고. 거울 속 사람이 빗질을 멈춘다.<br><br>
    앉기 전에 앉을 자리를 먼저 봐야 한다.`,
  o:[
    { l:'① 팀원을 비켜 세우고 이쪽이 거울과 의자 사이에 선다.', k:'steady', dc:23, wake:1,
      ok:`팀원 어깨를 잡아 돌려세웠다. 넷째 의자 앞에 이쪽이 섰다. 거울을 등지고.<br><br>등 뒤 거울 속에서 빗질 소리가 다시 난다. 이쪽 뒤통수를 빗는다. 머리카락이 당겨지는 느낌. 그래도 거울을 안 봤다. 의자에도 안 앉았다.<br>팀원들이 분장실을 다 지날 때까지 섰다. 빗질은 끝까지 이쪽 뒤통수를 빗었다. 나와서 만져 보니 머리카락이 반듯하게 빗겨 있었다.<br><br>자리 앞에 서되 자리에 앉지 않는다. 지키는 사람은 지킬 자리에 앉으면 안 된다. 몸이 그 차이를 익혔다.`,
      ng:`팀원을 비켜 세우는데 이쪽 무릎이 넷째 의자에 닿았다. 의자가 이쪽 뒤로 미끄러져 왔다.<br><br>앉고 말았다. 거울 속 사람이 돌아본다. 이쪽 얼굴이다. 분칠을 했다. 팀원들이 의자째 이쪽을 넘어뜨려 끌어냈다. 얼굴에 분가루가 묻어 있었다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-22, spirit:-28 } },
    { l:'② 무력을 실어 넷째 거울 칸을 깨뜨린다.', k:'break', dc:23, cost:{ might:30 },
      ok:`칼자루 끝으로 넷째 거울을 쳤다. 무력을 손목에 모아. 거울이 거미줄처럼 갈라진다.<br><br>갈라진 조각마다 뒷모습이 하나씩. 수십 개. 다 빗질을 멈췄다. 그리고 조각째 바닥에 쏟아졌다.<br>쏟아진 조각 위에 아무것도 안 비친다. 넷째 의자가 그냥 의자가 됐다. 팀원이 앉아 다리를 주물렀다.`,
      ng:`쳤는데 거울이 안 깨진다. 칼자루가 튕겨 나왔다. 손목이 꺾였다.<br><br>거울 속 사람이 빗을 내려놓고 이쪽 쪽으로 손을 뻗는다. 거울 안쪽에서 유리를 짚었다. 손바닥 자국이 남았다. 이쪽 손목과 같은 자리에 금이 갔다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-30, spirit:-18 } }
  ] },

{ at:'A1', t:'무대 옆 — 빈 인형탈 하나',
  x:`무대 옆 통로에 인형탈들이 줄을 섰다. 방글이, 뭉치, 삐뚤이. 입장 순서를 기다린다.<br><br>
    줄 맨 끝에 빈 탈이 하나 서 있다. 등 지퍼가 열렸다. 안이 비었다.<br>
    빈 탈이 하얀 장갑 낀 손으로 손짓한다. 이쪽 팀 막내에게. 이리 와. 너 키에 딱 맞아.<br><br>
    막내가 한 걸음 뒷걸음질 친다. 그 앞으로 이쪽이 나섰다.`,
  o:[
    { l:'① 막내 앞을 막고 빈 탈과 눈을 맞춘다.', k:'bond', dc:24,
      doom:{ title:'입장 대기', what:'빈 인형탈 안으로 끌려 들어가 무대로 실려 나갑니다', dc:19, sec:45,
        text:`막내 앞에 섰다. 빈 탈 얼굴의 그려진 눈을 마주 봤다.<br><br>탈이 고개를 갸웃한다. 그리고 이쪽을 위아래로 훑는다. 하얀 장갑이 이쪽 어깨를 잰다. 너도 맞겠다.<br>지퍼 열린 등이 이쪽을 향해 돌아선다. 장갑이 이쪽 팔을 잡아 소매에 넣는다. 탈 안은 따뜻하다. 땀 냄새가 난다. 여러 사람 땀.<br><br>무대 쪽에서 입장 음악이 시작된다.`,
        dieText:`무대 위에 인형탈이 넷 나왔다. 방글이, 뭉치, 삐뚤이. 그리고 새 친구.<br><br>새 친구는 동작이 서툴다. 손을 흔들 때 한 박자 늦다. 그리고 계속 무대 옆을 본다. 막내가 서 있던 쪽을.<br>새 친구는 무대 위에서 한 번도 막내 쪽으로 손을 흔들지 않았다. 막아선 자세 그대로였다.` },
      ok:`막내 앞에 섰다. 빈 탈의 그려진 눈을 마주 봤다. 끝까지.<br><br>탈이 이쪽을 잰다. 하얀 장갑이 어깨를 짚는다. 그때 이쪽이 먼저 탈 손목을 잡았다. 맞지 않는다고 말했다. 우리 중엔 아무도 안 맞는다고.<br>탈이 오래 이쪽 손을 내려다본다. 그리고 지퍼를 스스로 올렸다. 빈 채로 줄 맨 끝에 다시 섰다. 막내는 이쪽 등에 얼굴을 묻고 있었다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 막내를 등 뒤로 숨기고 한 걸음씩 물러난다.', k:'hide', dc:23,
      ok:`막내를 등 뒤로 돌렸다. 둘이 한 몸처럼 겹쳐 뒷걸음질 쳤다.<br><br>빈 탈이 손짓을 계속한다. 그런데 막내가 안 보인다. 손짓할 데를 잃었다. 탈 손이 허공을 더듬다 내려갔다.<br>통로 모퉁이를 돌아서야 막내가 숨을 내쉬었다. 이쪽 허리를 꽉 쥐고 있었다.`,
      ng:`물러나는데 막내가 이쪽 등 뒤에서 고개를 내밀었다. 보고 싶었던 것이다.<br><br>빈 탈이 반가워한다. 하얀 장갑이 이쪽 어깨 너머로 길게 뻗어 막내 머리칼을 쥐었다. 칼로 머리칼을 잘라 냈다. 막내 머리 한쪽이 짧아졌다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, spirit:-24 } }
  ] },

{ at:'A1', t:'공 바다 — 가라앉는 손',
  x:`놀이 세트에 공 바다가 있다. 알록달록한 공이 허리 깊이로 찼다. 건너편이 계단이다.<br><br>
    팀원 하나가 공 사이로 반쯤 가라앉았다. 발밑이 없다고 한다. 공이 끝없이 깊다고.<br>
    공 사이에서 작은 손들이 팀원 다리를 붙든다. 놀자는 손이다. 밑으로.<br><br>
    팀원 손만 공 위에 남았다. 손가락이 허우적거린다.`,
  o:[
    { l:'① 무력을 실어 공을 헤치고 뛰어들어 끌어낸다.', k:'bond', dc:23, cost:{ might:30 }, wake:1,
      ok:`뛰어들었다. 공이 가슴까지 찬다. 무력을 팔에 실어 공을 양옆으로 쳐냈다. 공이 튀어 오른다.<br><br>팀원 손을 잡았다. 밑에서 작은 손들이 같이 당긴다. 공 밑이 차갑다. 물처럼. 버텼다. 팀원을 이쪽 가슴으로 끌어당겨 안고 뒤로 걸었다.<br>가장자리에 닿았다. 둘이 같이 굴러 나왔다. 팀원 다리에 작은 손자국이 줄줄이.<br><br>뛰어드는 데도 순서가 있다. 손을 먼저 잡고 몸을 나중에 뺀다. 잡은 사람을 가슴에 붙이면 둘이 한 무게가 된다. 그 자세가 몸에 새겨졌다.`,
      ng:`뛰어들었는데 이쪽 발밑도 없다. 공이 목까지 찬다.<br><br>팀원 손을 잡았다. 둘이 같이 가라앉는다. 다른 팀원들이 공 바다 가장자리에서 밧줄을 던졌다. 겨우 잡고 나왔다. 둘 다 공 밑에서 무엇이 웃는 소리를 들었다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-32, spirit:-22 } },
    { l:'② 공 바다 가장자리 칸막이를 뜯어 공을 쏟아 낸다.', k:'fix', dc:23,
      ok:`가장자리 칸막이 판자를 뜯었다. 공이 와르르 바닥으로 쏟아진다.<br><br>공 높이가 내려간다. 무릎, 발목. 바닥이 보인다. 팀원이 바닥에 웅크리고 있다. 공 밑에 다른 건 없다. 손자국 같은 얼룩만 바닥 가득.<br>팀원을 일으켰다. 쏟아진 공들이 바닥을 굴러 다시 공 바다 쪽으로 모인다.`,
      ng:`뜯는데 판자가 안 떨어진다. 그 사이 팀원 손이 공 밑으로 사라졌다.<br><br>판자를 다 뜯었을 때 공이 쏟아졌다. 팀원은 공 바다 맨 밑바닥에 누워 있었다. 숨은 쉰다. 입에 공이 하나 물려 있었다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, mind:-20 } }
  ] },

{ at:'A1', t:'생방송 — 방글이가 내민 손',
  x:`생방송 불이 켜졌다. 무대 한가운데 방글이가 섰다. 해 얼굴. 웃는 입이 얼굴보다 길다.<br><br>
    방글이가 손을 내민다. 이쪽 팀원에게. 오늘의 친구. 같이 노래하자.<br>
    팀원이 손을 들어 올린다. 자기 손이 아닌 것처럼. 카메라 세 대가 그 손을 잡는다.<br><br>
    누군가 그 손을 대신 잡으면 오늘의 친구가 바뀐다. 그걸 안다. 안다고 손이 멈추지는 않는다.`,
  o:[
    { l:'① 팀원 손을 내리고 이쪽 손을 대신 내민다.', k:'bond', dc:24,
      doom:{ title:'오늘의 친구', what:'방글이에게 손을 잡혀 무대 한가운데로 끌려 나갑니다', dc:19, sec:40,
        text:`팀원 손목을 쳐서 내렸다. 이쪽 손을 내밀었다.<br><br>방글이가 이쪽 손을 잡는다. 장갑 속 손이 뜨겁다. 해처럼. 당긴다. 무대 한가운데로.<br>카메라 빨간 불이 이쪽을 잡는다. 스피커에서 박수. 이쪽 입이 웃는 모양이 된다. 근육이 저절로 당겨진다.<br><br>팀원들이 무대 턱에서 이쪽 다리를 붙든다. 방글이는 노래를 시작한다.`,
        dieText:`노래가 끝났다. 박수가 길었다.<br><br>무대 한가운데 오늘의 친구 의자에 이쪽이 앉아 있다. 웃는 입으로. 손을 흔든다.<br>방송이 끝나고 팀원들이 의자 앞에 섰을 때 의자는 비어 있었다. 등받이 별 옆에 이름이 수놓여 있었다. 다음 주에도 출연.` },
      ok:`팀원 손목을 쳐서 내렸다. 이쪽 손을 내밀었다. 그러나 손바닥이 아니라 주먹으로. 칼자루를 쥔 채로.<br><br>방글이 장갑이 주먹을 감싸려다 칼자루에 닿는다. 멈칫. 잡을 데가 없다. 손을 잡아야 친구가 된다.<br>방글이 웃는 입이 처음으로 흔들렸다. 그 틈에 팀원들이 무대 뒤 송출 부스로 뛰었다. 주먹을 내민 채 방글이 앞에 서 있었다. 노래가 끝날 때까지.`,
      win:{ exp:25, dream:4 } },
    { l:'② 팀원 손목을 쥐고 무대 반대쪽으로 끌어당긴다.', k:'steady', dc:23,
      ok:`팀원 손목을 쥐었다. 뒤로 당겼다. 팀원 팔이 방글이 쪽으로 뻗은 채 버틴다.<br><br>두 쪽에서 한 팔을 당긴다. 팀원이 이를 악문다. 이쪽이 더 오래 버텼다. 방글이 손이 허공을 쥐었다.<br>무대 밖으로 끌어냈다. 카메라 앵글 밖. 팀원 팔이 축 늘어졌다. 어깨가 빠져 있었다. 끼워 넣었다. 비명이 길었다.`,
      ng:`당기는데 팀원 팔이 무대 쪽으로 미끄러진다. 방글이 손이 팀원 손끝을 잡았다.<br><br>손끝만. 그래도 잡혔다. 다 같이 당겨 겨우 뺐다. 팀원 손끝 셋이 하얗게 탔다. 해에 덴 것처럼.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-32, spirit:-20 } }
  ] },

{ at:'A2', t:'종탑 창 — 맨 마지막으로 넘는 사람',
  x:`종탑 창을 넘어 안으로 들어간다. 창틀 아래 반은 물속이다. 위 반으로 넘어야 한다.<br><br>
    한 사람씩 넘는다. 넘을 때마다 물 밑에서 무엇이 발목 높이로 손을 내민다. 아직 아무도 안 잡혔다.<br>
    넘는 사람 수를 물 밑이 세고 있다. 넷째가 넘자 물이 한 번 출렁였다. 하나 남았다.<br><br>
    남은 하나가 이쪽이다. 늘 그렇다.`,
  o:[
    { l:'① 물 쪽을 마주 보며 뒷걸음으로 마지막에 넘는다.', k:'bond', dc:23, wake:1,
      ok:`창틀에 손을 짚고 돌아섰다. 물을 마주 봤다. 뒷걸음으로 한 발씩 창틀에 올렸다.<br><br>물 밑의 손이 올라온다. 이쪽 발목 앞에서 멈춘다. 얼굴을 보고 있는 것 앞에서는 잡지 않는다. 등을 보이는 것만 잡는다.<br>창틀 안쪽으로 내려섰다. 그제야 돌아섰다. 물 위에 손바닥 하나가 떠서 이쪽을 향해 펴져 있다. 잘 가라는 것처럼. 아니면 다음에 보자는 것처럼.<br><br>마지막에 남는 사람은 등을 보이지 않는다. 얼굴로 뒤를 막으며 물러나는 걸음. 그 뒷걸음이 다리에 익었다.`,
      ng:`돌아서는데 창틀이 미끄럽다. 손을 짚은 데서 이끼가 밀렸다.<br><br>무릎이 물에 빠졌다. 손이 무릎을 쥔다. 팀원들이 창 안에서 이쪽 겉옷을 잡아끌었다. 넘어오긴 했다. 무릎이 얼음장이다. 며칠 동안 구부릴 때마다 물소리가 났다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, spirit:-24 } },
    { l:'② 넷이 넘은 뒤 창틀을 차고 크게 뛰어넘는다.', k:'evade', dc:23,
      ok:`창틀 위에 올라섰다. 물 쪽을 보지 않고 안쪽으로 뛰었다. 크게.<br><br>발뒤꿈치를 무엇이 스쳤다. 잡을 만큼은 아니었다. 안쪽 바닥에 굴러 떨어졌다.<br>창밖 물이 한참 출렁였다. 다섯이 다 넘었다는 걸 늦게 안 것처럼.`,
      ng:`뛰는데 발목이 잡혔다. 반쯤 뜬 몸이 창틀에 걸쳤다.<br><br>안쪽 팀원들이 팔을 잡아당긴다. 바깥 물이 다리를 당긴다. 허리가 창틀에 걸린 채 버텼다. 겨우 빠졌다. 허리에 창틀 자국이 시퍼렇다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-30, mind:-14 } }
  ] },

{ at:'A2', t:'기숙사 복도 — 점호 줄 맨 앞',
  x:`밤 아홉 시. 복도 물속에서 점호 종이 울렸다. 호실 문이 일제히 열린다.<br><br>
    복도에 줄이 선다. 젖은 교복을 입은 아이들. 고개를 숙였다. 이쪽 팀은 피할 데가 없어 줄 끝에 끼었다.<br>
    사감이 복도 끝에서 걸어온다. 한 사람씩 얼굴을 들여다본다. 모르는 얼굴이면 멈춘다.<br><br>
    줄 맨 앞이 제일 오래 보인다. 사감은 맨 앞 얼굴부터 외운다.`,
  o:[
    { l:'① 무력을 끌어올려 팀 앞에 서서 사감 시선을 혼자 받는다.', k:'steady', dc:24, cost:{ might:28 }, wake:1,
      ok:`팀원들을 이쪽 등 뒤로 줄 세웠다. 이쪽이 팀의 맨 앞이 됐다. 무력을 등줄기로 끌어올렸다. 꼿꼿하게.<br><br>사감이 이쪽 앞에서 멈췄다. 얼굴이 물그림자다. 오래 들여다본다. 숨이 얼어붙는다. 눈을 내리깔지 않았다.<br>사감이 고개를 갸웃했다. 학생이 이렇게 서 있지는 않는다. 학생은 고개를 숙인다. 맨 앞이 학생이 아니면 그 뒤도 아니다. 사감이 이쪽 팀을 통째로 지나쳤다.<br><br>앞에 선 사람의 자세가 뒤에 선 사람들의 이름이 된다. 등을 펴는 것만으로 팀 전체를 가렸다. 그 서는 법이 몸에 남았다.`,
      ng:`서는데 사감 손이 이쪽 턱을 들어 올렸다. 손가락이 차고 젖었다.<br><br>얼굴을 오래 본다. 그리고 출석부를 펼친다. 이쪽 얼굴 옆에 무엇이 적힌다. 줄이 흩어질 때까지 턱에 손가락 자국이 남았다. 그 뒤로 거울을 보면 턱에 물이 맺힌다.`,
      win:{ exp:25, dream:4 }, lose:{ mind:-22, spirit:-28 } },
    { l:'② 사감이 오기 전에 팀을 줄 밖 물속 계단으로 뺀다.', k:'hide', dc:23,
      ok:`줄 끝에서 손짓했다. 다섯이 한 사람씩 물속 계단으로 미끄러져 내려갔다. 머리만 내밀고.<br><br>사감이 줄 끝까지 왔다. 빈자리를 본다. 다섯 자리. 오래 서 있었다.<br>그리고 출석부에 무엇을 적고 돌아갔다. 결석. 결석은 다음 점호 때 다시 부른다.`,
      ng:`미끄러져 내려가는데 계단 밑 물이 깊다. 막내가 발을 헛디뎠다.<br><br>물을 튀겼다. 사감이 돌아본다. 다섯이 물속에 머리를 박았다. 숨이 다 될 때까지. 올라왔을 때 사감이 계단 위에 서서 내려다보고 있었다. 한참 뒤에 갔다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, mind:-18 } }
  ] },

{ at:'A2', t:'3학년 교실 — 칠판 앞으로',
  x:`교실 물이 허리까지 찼다. 교탁 앞에 누가 서 있다. 분필을 쥐었다. 뒷모습만 보인다.<br><br>
    칠판에 문제가 하나. 그 밑에 이름. 이쪽 팀원 이름이다.<br>
    분필 쥔 것이 돌아보지 않고 말한다. 나와서 풀어 보세요.<br><br>
    팀원 의자가 저절로 뒤로 밀린다. 일어나라는 것이다. 남이 불려 나갈 때 이쪽은 먼저 일어선다. 늘 그랬다.`,
  o:[
    { l:'① 팀원 대신 이쪽이 일어나 칠판 앞으로 나간다.', k:'bond', dc:24,
      doom:{ title:'칠판 앞', what:'칠판 앞으로 불려 나가 물 밑으로 끌려갑니다', dc:19, sec:45,
        text:`일어섰다. 이쪽이 풀겠다고 했다. 물을 헤치고 칠판 앞으로 갔다.<br><br>분필을 받았다. 문제를 본다. 글씨가 물속처럼 흔들린다. 읽을 수 없다.<br>분필 쥐었던 것이 이쪽 뒤에 선다. 이쪽 어깨에 손을 얹는다. 틀렸어요. 남아서 다시 하세요.<br><br>교탁 밑 물이 깊어진다. 이쪽 발밑부터. 어깨 위의 손이 내리누른다.`,
        dieText:`교실 물이 잔잔해졌다. 칠판 앞에 아무도 없다.<br><br>칠판의 이름이 바뀌어 있다. 이쪽 이름. 그 옆에 동그라미. 다 풀었다는 표시다.<br>팀원들이 교실을 나올 때 교탁 밑 물에서 분필 긁는 소리가 났다. 같은 문제를 계속 푸는 소리.` },
      ok:`일어섰다. 이쪽이 풀겠다고 했다. 칠판 앞으로 가면서 칼을 등 뒤로 뽑아 쥐었다.<br><br>분필을 받지 않았다. 칠판의 팀원 이름을 칼등으로 문질렀다. 젖은 분필이 뭉개진다. 이름이 지워졌다.<br>불릴 이름이 없으면 나올 사람도 없다. 분필 쥔 것이 오래 칠판을 본다. 새로 쓸 이름을 찾는다. 그 사이 다섯이 교실을 빠져나왔다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 팀원 의자를 두 손으로 붙들어 일어서지 못하게 한다.', k:'steady', dc:23,
      ok:`팀원 의자 등받이를 쥐었다. 의자가 뒤로 밀리지 않게 버텼다.<br><br>팀원이 반쯤 일어서다 다시 앉는다. 나오세요. 다시 부른다. 의자가 떨린다. 버텼다.<br>세 번 불렀다. 대답이 없으니 분필이 이름에 줄을 긋는다. 결석. 결석은 오늘 다시 안 부른다.`,
      ng:`붙들었는데 의자가 앞으로 미끄러진다. 물이 의자를 민다.<br><br>팀원이 의자째 칠판 쪽으로 간다. 이쪽도 등받이를 쥔 채 끌려갔다. 교탁 바로 앞에서 의자를 뒤집었다. 둘이 물에 빠졌다. 칠판 쪽에서 손이 내려왔다. 피했다. 교복 소매가 이쪽 귀를 스쳤다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-28, mind:-18 } },
    { l:'③ 칠판 문제를 끝까지 읽는다.', k:'gaze', dc:23,
      ok:`문제를 읽었다. 물 아래로 비친 글씨를 거꾸로. 산수 문제다. 212에서 몇을 빼면 몇이 남느냐.<br><br>답을 소리 내지 않았다. 손가락으로 물 위에 썼다. 212. 아무도 빼지 않는다.<br>분필 쥔 것이 칠판 앞에서 오래 서 있다. 그리고 이름을 지웠다. 맞은 사람은 안 불려 나간다.`,
      ng:`읽는데 문제 숫자가 바뀐다. 212가 213이 된다. 이쪽을 셌다.<br><br>눈을 떼지 못했다. 숫자가 계속 는다. 214. 팀원이 이쪽 눈을 손으로 가려 줄 때까지. 그 뒤로 숫자를 세면 머리가 아프다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-22, spirit:-22 } }
  ] },

{ at:'A2', t:'수영장 — 다이빙대 밑',
  x:`팀원 하나가 다이빙대에서 미끄러졌다. 검은 물로 떨어졌다. 물보라도 작다.<br><br>
    떠오르지 않는다. 물 밑에서 거품이 한 줄로 올라온다. 점점 깊은 데서.<br>
    수영장 바닥이 안 보인다. 이 수영장은 학교보다 깊다. 그런 말을 벽에서 읽었다.<br><br>
    뛰어들면 같이 내려간다. 안 뛰어들면 혼자 내려간다.`,
  o:[
    { l:'① 무력을 다리에 실어 곧장 뛰어든다.', k:'bond', dc:24, cost:{ might:30 }, wake:1,
      ok:`뛰어들었다. 무력을 다리에 모아 아래로 찼다. 물이 이쪽을 밀어 올리려 한다. 거슬러 내려갔다.<br><br>거품 줄을 따라갔다. 팀원 손이 보인다. 위를 향해 펴져 있다. 그 아래로 다른 손들이 팀원 발목에 줄줄이. 팀원 손을 잡았다. 그리고 밑의 손들을 발로 찼다.<br>손들이 흩어진다. 위로 찼다. 수면이 멀다. 숨이 다 됐을 때 수면을 뚫었다. 둘이 같이 숨을 토했다.<br><br>사람을 건지는 건 내려가는 힘이 아니라 올라오는 힘이다. 내려갈 때 반을 남겨 둬야 한다. 다리가 그 셈을 처음으로 맞췄다.`,
      ng:`뛰어들었는데 물이 생각보다 차다. 몸이 굳는다.<br><br>팀원 손끝을 겨우 잡았다. 올라오는 힘이 모자란다. 위에서 팀원들이 레인 줄을 던졌다. 줄을 감고 끌려 올라왔다. 둘 다 입술이 파랗다. 한참 몸이 안 풀렸다.`,
      win:{ exp:25, dream:4 }, lose:{ hp:-34, spirit:-22 } },
    { l:'② 다이빙대에 밧줄을 묶어 몸에 감고 내려간다.', k:'fix', dc:23,
      ok:`다이빙대 기둥에 밧줄을 맸다. 반대쪽을 허리에 감았다. 팀원들에게 세 번 당기면 올리라고 했다.<br><br>내려갔다. 밧줄이 다 풀릴 즈음 팀원 손을 잡았다. 세 번 당겼다. 위에서 다섯이 같이 당겨 올렸다.<br>물 밖으로 나왔을 때 밧줄 끝에 이쪽 말고 다른 손자국이 묻어 있었다. 밧줄을 같이 잡고 올라오려던 손.`,
      ng:`매듭을 짓는 사이 거품이 멎었다.<br><br>서둘러 내려갔다. 팀원을 찾는 데 한참 걸렸다. 끌어올렸을 때 팀원이 숨을 안 쉬었다. 가슴을 눌렀다. 한참 만에 물을 토했다. 눈을 뜨고 처음 한 말이 이쪽 이름이 아니었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-26, mind:-20 } }
  ] },

{ at:'A2', t:'강당 — 종 앞을 막은 사감',
  x:`강당 무대 위에 하교 종이 매달렸다. 종줄이 물 위로 늘어졌다.<br><br>
    종 앞에 사감이 섰다. 출석부를 펼쳤다. 이쪽 팀을 본다. 하나씩. 아직 점호가 안 끝났다고.<br>
    누가 사감 앞을 막아야 다른 누가 종줄에 닿는다.<br><br>
    견습 기사의 맹세 넷째 줄. 등 뒤의 이를 버리지 않는다. 오늘은 앞의 이를 막아야 한다.`,
  o:[
    { l:'① 무력을 다 끌어올려 사감 앞을 막아서고 팀을 종으로 보낸다.', k:'steady', dc:24, cost:{ might:32 }, wake:1,
      ok:`사감과 종 사이에 섰다. 무력을 온몸에 돌렸다. 팀원들에게 뛰라고 외쳤다.<br><br>사감이 이쪽을 본다. 출석부를 이쪽 가슴에 댄다. 이름을 찾는다. 이쪽 이름이 출석부에 없다. 처음부터 이 학교 학생이 아니다. 사감이 이쪽을 비켜 가려 한다. 비키지 않았다.<br>등 뒤에서 종이 울렸다. 크게. 물이 떨린다. 사감 손에서 출석부가 녹아내리듯 풀렸다.<br><br>맹세 넷째 줄이 뒤만이 아니라 앞을 향해서도 된다는 걸 알았다. 등 뒤의 이를 버리지 않으려면 앞의 것을 막아야 한다. 넷째 줄 뜻이 한 겹 더 열렸다.`,
      ng:`막아섰는데 사감 손이 이쪽 어깨를 통과한다. 물처럼.<br><br>몸 안이 얼음물에 씻긴다. 무릎이 꺾였다. 사감이 이쪽을 지나간다. 종줄 앞의 팀원에게. 다시 일어나 사감 등을 붙들었다. 손이 젖은 천만 쥐었다. 종은 울렸다. 이쪽 몸은 한참 떨렸다.`,
      win:{ exp:25, dream:4 }, lose:{ hp:-30, spirit:-30 } },
    { l:'② 사감 손의 출석부를 쳐서 떨어뜨린다.', k:'break', dc:23,
      ok:`칼등으로 출석부를 쳤다. 출석부가 물에 떨어졌다. 젖은 종이가 풀린다.<br><br>사감이 출석부를 주우려 몸을 숙인다. 이름 없이는 점호를 못 한다. 그 사이 팀원이 종줄을 당겼다.<br>종소리 속에서 사감이 물속 종이를 한 장씩 건지고 있었다.`,
      ng:`쳤는데 출석부가 안 떨어진다. 사감 손과 붙어 있다.<br><br>칼등이 출석부에 닿자 출석부에 이쪽 이름이 적힌다. 쳐서 적었다. 사감이 이쪽을 보며 고개를 끄덕인다. 출석. 다리가 종 반대쪽으로 걷기 시작했다. 팀원들이 붙잡았다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-20 } },
    { l:'③ 맹세를 소리 내어 외며 종줄까지 걸어간다.', k:'bond', dc:23,
      ok:`맹세를 외웠다. 첫 줄부터 크게. 한 줄에 한 걸음씩.<br><br>사감이 이쪽 쪽으로 출석부를 든다. 이쪽은 학생 대답을 하지 않는다. 맹세를 왼다. 학교 말이 아닌 말. 사감 손가락이 출석부 위에서 갈 곳을 잃는다.<br>다섯째 줄에서 종줄을 쥐었다. 당겼다. 종이 울렸다.`,
      ng:`외는데 강당이 따라 왼다. 관람석 아이들이. 교가 박자로.<br><br>맹세가 교가에 묻혔다. 사감이 이쪽 앞을 막아선다. 출석부가 펼쳐진다. 팀원 하나가 사감을 들이받았다. 그 틈에 종줄을 당겼다. 들이받은 팀원 어깨가 하얗게 얼었다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-20, spirit:-24 } }
  ] },

]);

// ------------------------------------------
// 신호수 · 자원 없음
// ------------------------------------------
kJob('signal', 'A', [

{ at:'A', t:'어둠 속 — 목록에 없는 손짓',
  x:`등불을 쓸 수 없는 곳이다. 빛을 보면 깨는 것이 천장에 있다.<br><br>
    어둠 속에서는 손짓도 안 보인다. 그래서 손바닥에 손가락으로 쓴다. 출발 전에 정했다. 한 번 누르면 멈춰. 두 번 쓸면 가. 손등을 두드리면 위험.<br>
    줄 맨 앞에서 신호가 뒤로 넘어온다. 이쪽 손바닥에 닿은 신호는 동그라미다. 손가락으로 천천히 한 바퀴.<br><br>
    그런 신호는 정한 적이 없다. 신호수는 정하지 않은 신호를 가르친 적이 없다.`,
  o:[
    { l:'① 신호마다 확인 신호를 붙여 다시 돌린다.', k:'bond', dc:23, wake:1,
      ok:`이쪽 앞사람 손바닥에 썼다. 멈춰. 그리고 새끼손가락을 한 번 걸었다. 이쪽이 보낸 신호라는 표시. 방금 지어냈다.<br><br>앞으로 넘어간 신호가 돌아온다. 멈춰, 새끼손가락. 넷째까지 왔다 갔다. 다섯째에서 돌아온 신호에는 새끼손가락이 없다. 동그라미만 있다.<br>다섯째 자리를 손으로 더듬었다. 비어 있다. 진짜 다섯째는 한 걸음 옆에 웅크리고 있었다. 손을 잡아 줄로 데려왔다.<br><br>신호에 서명을 붙이는 법. 무엇을 보냈는지보다 누가 보냈는지를 먼저 실어 보낸다. 손가락 하나 거는 버릇이 그 뒤로 모든 신호에 붙었다.`,
      ng:`확인 신호를 붙였는데 앞사람이 못 알아듣는다. 새끼손가락을 위험으로 읽었다.<br><br>앞사람이 뒤로 물러서다 이쪽 발을 밟았다. 소리가 났다. 천장이 움직인다. 다섯이 납작 엎드렸다. 등 위로 바람이 오래 지나갔다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-24, spirit:-24 } },
    { l:'② 신호를 멈추고 다섯이 서로 손목을 쥐게 한다.', k:'steady', dc:22,
      ok:`더는 손바닥에 쓰지 않았다. 앞사람 손목을 쥐고 뒷사람 손을 이쪽 손목에 얹었다. 그렇게 줄이 됐다.<br><br>신호가 없으면 흉내 낼 것도 없다. 쥔 손목만 믿고 걸었다.<br>어둠 속에서 누가 이쪽 손바닥에 동그라미를 그린다. 계속. 쥔 손목을 놓지 않았다. 그리는 손가락이 점점 지쳐 갔다.`,
      ng:`쥐게 하는데 하나가 손을 늦게 줬다. 줄이 한 박자 끊겼다.<br><br>그 사이 손 하나가 줄에 끼었다. 차고 작은 손. 줄을 다 지나고 나서야 알았다. 셋째와 넷째 사이에 누가 있었다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-22, spirit:-26 } }
  ] },

{ at:'A', t:'벽 너머 — 배운 두드림',
  x:`벽 너머에서 두드림이 온다. 셋, 하나, 셋. 이쪽 팀 박자다. 출발 전에 정한 것.<br><br>
    팀원은 다섯 다 여기 있다. 벽 너머엔 아무도 없어야 한다.<br>
    두드림이 다음 박자로 넘어간다. 하나는 예, 둘은 아니오. 그것도 이쪽 것이다.<br><br>
    누가 언제 이 박자를 들었을까. 연습할 때. 첫 층에서. 그때부터 벽이 듣고 있었다.`,
  o:[
    { l:'① 박자를 일부러 하나 틀려 보내 반응을 본다.', k:'gaze', dc:23, wake:1,
      ok:`셋, 하나, 둘. 일부러 틀렸다.<br><br>벽 너머가 그대로 따라 한다. 셋, 하나, 둘. 틀린 줄 모른다. 박자를 아는 게 아니라 흉내 내는 것이다.<br>팀원들에게 손짓했다. 이제부터 셋, 하나, 셋에 하나를 더한다. 마지막 박은 손바닥으로. 벽에 안 닿게.<br><br>흉내 내는 쪽은 틀린 것도 흉내 낸다. 진짜는 틀린 걸 고친다. 일부러 틀려서 상대를 가르는 법. 신호 안에 덫을 심을 줄 알게 됐다.`,
      ng:`틀리게 보냈는데 벽 너머가 고쳐서 돌려보낸다. 셋, 하나, 셋.<br><br>고칠 줄 안다. 흉내가 아니다. 등에 소름이 돋았다. 벽 너머에서 한 번 더. 셋, 하나, 셋. 그리고 아주 작게 한 번. 이쪽 이름 글자 수만큼.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-22, spirit:-26 } },
    { l:'② 정한 박자로 대답해 누구냐고 묻는다.', k:'bond', dc:23,
      doom:{ title:'배운 두드림', what:'벽 속으로 손목을 잡혀 끌려 들어갑니다', dc:18, sec:50,
        text:`셋, 하나, 셋. 그리고 물음 박자. 누구냐.<br><br>벽 너머가 대답한다. 하나. 예. 묻는 말에 예라고 한다. 그리고 두드림이 이쪽 손바닥 바로 앞에서 난다. 벽 이쪽 면에서.<br>벽이 무르다. 손바닥이 벽에 들어간다. 진흙처럼. 안쪽에서 무엇이 손목을 쥔다. 셋, 하나, 셋. 손목을 쥔 박자로.<br><br>팔꿈치까지 들어갔다. 팀원들이 어깨를 붙든다.`,
        dieText:`벽은 다시 단단해졌다.<br><br>팀원들이 벽에 귀를 댔다. 두드림이 온다. 셋, 하나, 셋. 이쪽이 두드리는 박자다. 이쪽 손 힘으로.<br>그 벽은 그 뒤로 지나가는 팀마다 두드린다. 같은 박자로. 누구냐고 묻는 팀에게 예라고 대답한다.` },
      ok:`셋, 하나, 셋. 그리고 물음 박자. 누구냐.<br><br>벽 너머가 대답하지 않는다. 물음 박자는 연습 때 쓴 적이 없다. 처음 쓰는 신호다. 모르는 건 따라 하지 못한다.<br>벽이 조용해졌다. 그 벽을 떠나며 팀원들에게 일렀다. 물음 박자는 이 벽이 모른다. 앞으로는 먼저 물어보자고.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A', t:'틈 건너 — 같은 불빛',
  x:`깊은 틈 건너에서 불빛이 깜빡인다. 길게, 짧게, 짧게.<br><br>
    이쪽 등불 신호다. 이쪽이 아까 보낸 것. 앞서 간 팀원에게.<br>
    앞서 간 팀원은 저쪽에 없다. 저쪽 바위 위에 등불만 하나. 아무도 안 들었는데 덮개가 열렸다 닫힌다.<br><br>
    신호는 보낸 쪽을 알려 준다. 받은 쪽도 이쪽이 어디 있는지 안다.`,
  o:[
    { l:'① 덮개로 정하지 않은 새 신호를 보낸다.', k:'bond', dc:23,
      ok:`짧게 일곱 번. 정한 적 없는 신호다. 저쪽 등불이 멈춘다. 따라 하지 못한다. 모르는 건 모른다.<br><br>그 사이 아래쪽 어둠에서 다른 불빛이 깜빡였다. 아주 약하게. 짧게, 길게. 서툴다. 앞서 간 팀원이 쓰다 남은 성냥으로 보내는 신호다.<br>그쪽으로 내려갔다. 팀원이 바위턱에 매달려 있었다. 끌어올렸다. 위쪽 등불은 내내 같은 신호만 반복했다.`,
      ng:`새 신호를 보내는데 저쪽 등불이 바로 따라 한다. 일곱 번. 이쪽 손보다 빠르게.<br><br>배우는 속도가 빠르다. 그리고 다가온다. 틈 위로. 허공을 건너서. 덮개를 닫고 바위 뒤로 굴렀다. 불빛이 이쪽 머리 위를 지나갔다. 머리카락이 탔다.`,
      win:{ exp:20, dream:3 }, lose:{ hp:-26, mind:-18 } },
    { l:'② 등불을 끄고 어둠 속에서 기다린다.', k:'hide', dc:22,
      ok:`덮개를 닫았다. 다섯이 바위 뒤에 숨었다.<br><br>저쪽 불빛이 한참 같은 신호를 보낸다. 대답이 없자 신호가 바뀐다. 짧게, 짧게, 짧게. 다급하다. 이쪽 팀이 쓰는 위험 신호다.<br>속지 않았다. 불빛이 지쳐 꺼졌다. 날이 밝은 것도 아닌데 주위가 조금 밝아졌다.`,
      ng:`닫았는데 덮개 틈으로 빛이 샜다. 한 줄기.<br><br>저쪽 불빛이 그 한 줄기를 향한다. 그리고 그 한 줄기를 그대로 되비춘다. 이쪽 눈에. 한동안 앞이 하얬다. 눈을 뜨니 셋째가 틈 가장자리에 서 있었다. 불빛 쪽으로 한 발 내밀고.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-20, spirit:-24 } },
    { l:'③ 저쪽 불빛 박자를 숨죽여 센다.', k:'sense', dc:23, wake:1,
      ok:`세었다. 길게, 짧게, 짧게. 길게가 이쪽보다 조금 길다. 짧게가 조금 짧다. 손이 아니라 숨으로 덮개를 여닫는 박자다.<br><br>사람 손은 숨과 박자가 다르다. 저쪽은 숨으로 깜빡인다. 들숨에 켜고 날숨에 끈다.<br>저쪽이 날숨일 때만 움직이자고 팀원들에게 손짓했다. 불이 꺼진 틈마다 한 걸음. 틈을 돌아 건넜다. 저쪽 불빛은 이쪽을 끝내 못 찾았다.<br><br>박자 안의 박자를 듣는 귀가 생겼다. 신호가 무슨 뜻인지보다 어떤 몸이 보냈는지가 먼저 들린다.`,
      ng:`세는데 박자가 점점 이쪽 숨과 맞아 간다. 이쪽 들숨에 켜지고 날숨에 꺼진다.<br><br>숨을 멈췄다. 불빛도 멈췄다. 켜진 채로. 이쪽을 비추며. 숨을 쉬지 못한 채 한참 서 있었다. 팀원이 이쪽 가슴을 쳐서야 숨이 터졌다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-22, spirit:-28 } }
  ] },

{ at:'A', t:'구덩이 — 너무 고른 당김',
  x:`팀원 하나가 줄을 타고 구덩이 아래로 내려갔다. 아래가 안 보인다.<br><br>
    한 번 당기면 괜찮다. 두 번은 더 내려 달라. 세 번은 올려 달라. 정해 두었다.<br>
    줄이 당겨진다. 한 번. 쉬고. 한 번. 쉬고. 한 번. 괜찮다는 신호가 계속 온다. 같은 간격으로. 시계처럼.<br><br>
    사람 손은 시계처럼 당기지 못한다. 겁먹은 사람은 더더욱.`,
  o:[
    { l:'① 줄로 질문 신호를 보내 대답을 기다린다.', k:'bond', dc:23, wake:1,
      ok:`줄을 다섯 번 짧게 당겼다. 정한 적 없는 신호다. 내려간 팀원만 알아들을 수 있게, 그 사람 이름 글자 수로.<br><br>당김이 멈춘다. 오래. 그리고 아주 약하게, 두 번. 엉망인 간격으로. 손이 떨리는 당김이다. 진짜다.<br>세 번을 보내지 않고 그냥 끌어올렸다. 팀원이 올라왔다. 줄 중간을 다른 무엇이 쥐고 한 번씩 당기고 있었다고 했다. 위로 괜찮다고 알려 주라고.<br><br>정한 신호를 쓰지 않고 그 사람만 아는 걸로 묻는 법. 신호가 약속이 아니라 질문이 될 수 있다는 걸 알았다. 그 뒤로 이쪽 신호에는 늘 물음이 하나 섞인다.`,
      ng:`다섯 번 당겼는데 대답이 바로 온다. 다섯 번. 같은 간격으로.<br><br>똑같이 따라 했다. 팀원은 대답할 수 없는 상태다. 줄을 다 같이 당겼다. 끝에 팀원이 매달려 올라왔다. 정신이 없다. 발목에 손자국 둘. 다섯이 아니라 둘.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-22, spirit:-26 } },
    { l:'② 줄을 잡고 이쪽이 직접 내려간다.', k:'steady', dc:23,
      doom:{ title:'고른 당김', what:'줄에 매달린 채 구덩이 아래로 끌려 내려갑니다', dc:18, sec:50,
        text:`줄을 잡고 내려갔다. 팀원들이 위에서 붙든다.<br><br>중간쯤에서 손이 줄 위의 다른 손에 닿았다. 줄을 쥔 손. 차다. 그 손이 한 번 당긴다. 위로 괜찮다고.<br>그리고 이쪽 손목을 쥔다. 아래에서 팀원 목소리가 들린다. 괜찮다고. 같은 간격으로.<br><br>줄이 아래로 미끄러진다. 위의 팀원들이 당긴다. 아래가 세다.`,
        dieText:`위에서 줄을 감아올렸다. 끝이 비었다.<br><br>그런데 줄이 당겨진다. 한 번. 쉬고. 한 번. 괜찮다는 신호다. 시계처럼.<br>위의 팀원들은 다음 층으로 갔다. 줄은 놔두고 갔다. 줄이 계속 괜찮다고 한다. 둘 몫으로.` },
      ok:`줄을 잡고 내려갔다. 중간에서 다른 손이 줄을 쥐고 있었다. 그 손등을 칼끝으로 그었다. 손이 줄을 놓았다.<br><br>아래로 계속 갔다. 팀원이 매달려 있었다. 손목을 쥐고 세 번 당겼다. 위에서 둘을 같이 끌어올렸다.<br>올라와서 줄을 봤다. 중간쯤에 손자국이 하얗게 얼어 있었다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A', t:'갈림길 — 둘로 갈린 팀',
  x:`바닥이 꺼지며 팀이 갈렸다. 셋은 왼쪽 통로. 둘은 오른쪽.<br><br>
    두 통로는 벽 하나를 사이에 두고 나란히 간다. 벽 위로 녹슨 배관이 지나간다. 두 통로를 다 지난다.<br>
    소리를 지르면 무엇이 듣는다. 아까 꺼진 바닥 아래에서 무엇이 아직 움직인다.<br><br>
    배관은 두드리면 울린다. 양쪽으로 똑같이.`,
  o:[
    { l:'① 배관을 두드려 두 쪽 걸음을 맞춘다.', k:'bond', dc:23, wake:1,
      ok:`배관을 손톱으로 두드렸다. 작게. 한 번에 한 걸음.<br><br>건너편 배관에서 대답이 온다. 같은 박자로. 두 통로가 한 박자로 걷는다. 이쪽이 멈추면 저쪽도 멈춘다. 갈림길이 다시 만나는 데까지.<br>만났다. 다섯이 다 있다. 저쪽 둘 중 하나가 이쪽 손을 잡고 한참 놓지 않았다.<br><br>한쪽에서 보낸 신호를 다른 쪽이 받는 게 아니라 양쪽이 같이 박자를 지키는 법. 신호가 말이 아니라 걸음이 됐다. 손톱 끝이 그 박자를 외웠다.`,
      ng:`두드리는데 배관이 너무 울린다. 소리가 아래로도 간다.<br><br>꺼진 바닥 아래에서 무엇이 배관 박자를 따라 올라온다. 두 통로가 만나는 데서 기다렸다. 다섯이 다 만났을 때 그것도 거기 있었다. 다 같이 뛰었다. 하나가 발목을 할퀴였다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, spirit:-24 } },
    { l:'② 오른쪽 둘에게 한 사람이 뛰어가 다시 모은다.', k:'evade', dc:23,
      ok:`꺼진 바닥 가장자리를 따라 뛰었다. 금 간 데를 밟지 않고.<br><br>오른쪽 통로 입구에 닿았다. 둘이 웅크리고 있다. 손짓으로 따라오라고 했다. 셋이 다시 가장자리를 건넜다. 발밑에서 무엇이 한 번 손을 뻗었다. 모두 피했다.`,
      ng:`뛰는데 금이 발밑에서 벌어졌다. 한쪽 다리가 빠졌다.<br><br>무엇이 그 다리를 쥐었다. 걷어차고 기어 나왔다. 정강이에 긁힌 자국 셋. 둘을 데려오긴 했다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-30, mind:-14 } }
  ] },

{ at:'A', t:'복도 — 한 박자 늦은 대답',
  x:`복도 모퉁이마다 머릿수를 센다. 소리 없이. 손가락을 하나씩 튕긴다. 맨 앞이 하나, 그다음이 둘.<br><br>
    다섯까지 튕긴다. 그런데 다섯째 튕김이 한 박자 늦다. 매번.<br>
    다섯째 팀원은 원래 빠르다. 성미가 급한 사람이다. 지금은 늦다. 손가락 소리도 조금 젖었다.<br><br>
    늦는 이유는 둘이다. 다쳤거나, 따라 하느라 늦거나.`,
  o:[
    { l:'① 세는 순서를 바꿔 다섯째를 맨 처음에 둔다.', k:'bond', dc:23, wake:1,
      ok:`손짓으로 순서를 바꿨다. 이번엔 맨 뒤부터. 다섯째가 하나.<br><br>다섯째가 먼저 튕겨야 한다. 따라 할 앞소리가 없다. 기다렸다. 아무 소리가 안 난다. 맨 뒤 어둠 속에서 아무것도.<br>등불을 비췄다. 다섯째 자리에 아무도 없다. 진짜 다섯째는 셋째 뒤에 바짝 붙어 있었다. 언제부터 그랬는지 모른다고. 다섯째 자리가 차가워서 앞으로 왔다고.<br><br>세는 순서를 뒤집으면 흉내 내는 것이 설 데가 없어진다. 셈을 세는 법이 아니라 셈의 차례를 다루는 법. 손가락이 새 차례를 외웠다.`,
      ng:`순서를 바꾸는 손짓을 셋째가 못 봤다. 셋째가 하나를 튕겼다. 다섯째도 하나를 튕겼다.<br><br>둘이 겹쳤다. 그리고 하나가 더. 맨 뒤 어둠 속에서. 하나가 셋이다. 다들 뛰었다. 모퉁이 둘을 지나 다시 셌다. 다섯. 박자는 맞았다. 그래도 아무도 다섯째 뒤에 서려 하지 않았다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-22, spirit:-26 } },
    { l:'② 늦은 쪽에 등불을 비춰 얼굴을 확인한다.', k:'gaze', dc:22,
      ok:`등불 덮개를 반만 열어 다섯째 쪽에 댔다.<br><br>다섯째 얼굴이다. 땀투성이다. 발목을 접질렸다고. 아까부터 참았다고. 늦은 건 아파서였다.<br>안도했다. 다섯째 등 뒤도 비췄다. 거기 무엇이 웅크렸다가 빛을 받자 천장으로 올라갔다. 둘 다였다.`,
      ng:`비추는데 다섯째가 손으로 빛을 가린다. 눈이 부시다고.<br><br>손가락 사이로 얼굴이 언뜻 보였다. 다섯째인데 웃고 있다. 덮개를 닫았다. 다시 열 용기가 안 났다. 다음 모퉁이에서 다섯째는 다시 빨라져 있었다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'A', t:'빈 방 — 손짓을 따라 하는 그림자',
  x:`벽에 등불이 그림자를 던진다. 다섯 그림자. 이쪽이 손짓을 하자 이쪽 그림자도 한다.<br><br>
    멈춰. 그림자도 멈춰. 가. 그림자도 가.<br>
    그런데 그림자가 손짓 하나를 더 한다. 이쪽은 안 한 것. 손바닥을 펴서 아래로 끄는 손짓. 이리 와.<br><br>
    팀원들이 이쪽 손이 아니라 벽을 보고 있다. 그림자가 더 크고 더 잘 보인다.`,
  o:[
    { l:'① 그림자가 생기지 않는 신호로 바꾼다.', k:'bond', dc:23, wake:1,
      ok:`손을 내렸다. 팀원들 어깨를 하나씩 짚었다. 짚는 횟수로 말했다. 한 번은 멈춰, 두 번은 가.<br><br>그림자가 따라 할 손짓이 없다. 벽 위에서 손을 들었다 내렸다 한다. 혼자서. 이리 와, 이리 와.<br>팀원들이 이쪽 손끝만 따라 방을 지났다. 아무도 벽을 보지 않았다.<br><br>신호를 눈에서 몸으로 옮겼다. 보이는 신호는 훔칠 수 있다. 닿는 신호는 그 손이 닿아야 한다. 어깨 짚는 박자가 그 뒤로 이쪽 팀의 말이 됐다.`,
      ng:`어깨를 짚는데 한 팀원이 그림자를 보고 있다. 짚는 걸 못 느꼈다.<br><br>그 팀원이 벽 쪽으로 걷는다. 그림자 손이 이리 와. 뛰어가 허리를 붙들었다. 벽 바로 앞에서. 벽에 팀원 손바닥이 닿았다. 손바닥 모양 그을음이 남았다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-22, spirit:-28 } },
    { l:'② 등불을 꺼서 그림자를 없앤다.', k:'hide', dc:22,
      ok:`덮개를 닫았다. 방이 깜깜해졌다. 그림자도 없다.<br><br>손을 잡고 벽을 더듬어 걸었다. 어둠 속에서 손바닥을 끄는 소리가 났다. 이리 와. 벽 위에서. 보이지 않는 손짓은 소리로만 남는다.<br>문을 찾아 나갔다. 다섯 다.`,
      ng:`껐는데 그림자가 남았다. 불 없이. 벽에 붙은 채로.<br><br>손짓이 계속된다. 이리 와. 이번엔 어둠이 그림자보다 밝지 않아서 그림자밖에 안 보인다. 다시 불을 켜자 다섯째가 벽에 기대 서 있었다. 그림자와 손바닥을 맞댄 채로.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-22, spirit:-22 } }
  ] },

{ at:'A', t:'긴 계단 — 위에서 오는 호루라기',
  x:`계단을 내려가는데 위에서 호루라기가 운다. 짧게 셋. 이쪽 팀 신호다. 모여라.<br><br>
    호루라기는 이쪽 목에 걸려 있다. 하나뿐이다.<br>
    위에서 또 운다. 짧게 셋. 길게 하나. 길게 하나는 급하다는 뜻이다. 그것도 이쪽이 정했다.<br><br>
    팀원 둘이 계단을 거꾸로 오르려 한다. 신호를 따르는 게 몸에 배었다. 이쪽이 그렇게 가르쳤다.`,
  o:[
    { l:'① 이쪽 호루라기로 되받아 진짜 신호를 가린다.', k:'gaze', dc:23,
      ok:`호루라기를 입에 물었다. 길게 둘. 그리고 짧게 하나. 정한 적 없는 신호다. 대신 팀원들이 아는 소리로. 이쪽 호루라기 소리는 이쪽 팀원이 안다. 쉰 소리가 나는 걸.<br><br>위에서 오는 호루라기는 맑다. 너무 맑다. 팀원들이 두 소리를 비교한다. 쉰 쪽으로 돌아섰다.<br>계단을 내려갔다. 위의 맑은 호루라기가 오래 울었다. 점점 쉰 소리를 흉내 내며.`,
      ng:`되받았는데 위에서 똑같이 되받는다. 쉰 소리까지.<br><br>팀원 둘이 어느 쪽인지 모르겠다는 얼굴로 굳었다. 그 사이 하나가 위로 세 계단을 올랐다. 뛰어가 끌어내렸다. 무릎이 계단 모서리에 찍혔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-18 } },
    { l:'② 팀원들을 붙들고 이쪽이 먼저 소리를 따라 올라가 본다.', k:'bond', dc:24,
      doom:{ title:'맑은 호루라기', what:'호루라기 소리에 위층 어둠으로 끌려 올라갑니다', dc:18, sec:50,
        text:`팀원들에게 기다리라고 손짓하고 혼자 올라갔다.<br><br>계단참에 아무도 없다. 호루라기 소리는 그 위에서 난다. 더 올라갔다. 소리는 늘 한 층 위에 있다.<br>다섯째 층계참에서 소리가 멎었다. 이쪽 목에 걸린 호루라기가 저절로 운다. 짧게 셋. 이쪽 숨으로. 이쪽 입에 물리지도 않았는데.<br><br>목걸이 끈이 위로 당겨진다. 목이 들린다.`,
        dieText:`아래 계단의 팀원들은 기다렸다. 호루라기가 울었다. 짧게 셋. 쉰 소리. 이쪽 호루라기 소리다.<br><br>팀원들은 따르지 않았다. 이쪽이 그렇게 가르쳤으니까. 확인 신호가 없는 신호는 따르지 말라고.<br>호루라기는 그 뒤로도 위에서 운다. 확인 신호를 붙여서. 새끼손가락을 거는 박자까지 흉내 내며.` },
      ok:`팀원들에게 기다리라고 손짓하고 혼자 올라갔다. 호루라기를 손에 꽉 쥐었다. 소리가 안 나게.<br><br>계단참 셋을 올랐다. 소리가 늘 한 층 위에 있다. 거기서 멈췄다. 쫓아갈수록 멀어지는 소리는 이쪽을 부르는 게 아니라 끌고 가는 것이다.<br>내려왔다. 팀원들이 그대로 있었다. 위에서 호루라기가 울다 멎었다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A', t:'쉬는 자리 — 잠든 손등의 두드림',
  x:`밤. 다섯이 잔다. 이쪽은 불침번이다.<br><br>
    어둠 속에서 소리가 난다. 톡, 톡톡. 셋째 팀원 손등을 누가 두드린다. 손등 두드림은 이쪽 팀 신호다. 나를 봐.<br>
    셋째가 잠결에 눈꺼풀을 떤다. 깨면 본다. 두드리는 쪽을.<br><br>
    두드리는 손은 안 보인다. 셋째 손등만 조금씩 눌린다.`,
  o:[
    { l:'① 셋째 다른 손등에 이쪽이 멈춰 신호를 덧두드린다.', k:'bond', dc:23, wake:1,
      ok:`셋째 반대쪽 손등을 한 번 꾹 눌렀다. 멈춰. 눈 뜨지 마.<br><br>셋째 눈꺼풀이 멈춘다. 두 신호가 양손에 온다. 나를 봐, 멈춰. 셋째 몸이 어느 쪽을 따를지 망설인다. 이쪽이 한 번 더 눌렀다. 오래.<br>잠든 사람은 더 오래 닿은 쪽을 따른다. 셋째가 깊이 잠들었다. 반대쪽 두드림이 지쳐서 멎었다.<br><br>잠든 사람에게도 신호가 닿는다. 깨어 있는 사람보다 더 정직하게. 손끝으로 남의 잠을 지키는 법을 알았다. 그 뒤로 불침번 때 손이 먼저 움직인다.`,
      ng:`누르는데 셋째가 깜짝 놀라 깼다. 눈을 떴다.<br><br>두드리던 쪽을 봤다. 비명을 질렀다. 그 소리에 다 깼다. 셋째는 무엇을 봤는지 말하지 않는다. 손등에 손가락 자국 셋. 아침까지 그 손을 품에 넣고 떨었다.`,
      win:{ exp:24, dream:3, mind:6 }, lose:{ mind:-22, spirit:-28 } },
    { l:'② 셋째를 흔들어 깨우고 눈을 가린다.', k:'steady', dc:22,
      ok:`셋째 어깨를 흔들며 손바닥으로 눈을 덮었다. 깨되 보지 말라고 귓속말했다.<br><br>셋째가 깼다. 눈은 덮인 채로. 두드림이 멎었다. 깨어 있는 사람은 신호를 골라 받는다.<br>날이 밝을 때까지 셋째 눈을 덮고 있었다. 손바닥이 땀에 젖었다.`,
      ng:`흔드는데 손바닥이 미끄러졌다. 셋째 눈이 열렸다. 한쪽만.<br><br>그 한쪽 눈이 이쪽 어깨 너머를 본다. 그리고 감기지 않는다. 다음 날 내내 셋째는 한쪽 눈을 뜬 채로 잤다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-20, spirit:-24 } },
    { l:'③ 두드리는 손을 어둠 속에서 붙잡는다.', k:'break', dc:24,
      doom:{ title:'손등의 두드림', what:'붙잡은 손에 도리어 잡혀 어둠 속으로 끌려갑니다', dc:18, sec:50,
        text:`셋째 손등 위 허공을 움켜쥐었다. 손이 잡혔다. 작고 차고 마른 손.<br><br>그 손이 이쪽 손등을 두드린다. 톡, 톡톡. 나를 봐.<br>보지 않으려 했다. 고개가 돌아간다. 이쪽 손이 신호를 따르게 가르쳐 놨다. 몸이 먼저 신호를 따른다.<br><br>봤다. 그리고 그 손이 이쪽 손을 쥐고 당긴다. 어둠 쪽으로. 이쪽 몸이 그 신호도 따른다. 가.`,
        dieText:`아침에 팀원들이 깼다. 불침번이 없다.<br><br>쉬는 자리 가장자리 바닥에 손톱으로 쓴 신호가 있다. 손바닥 신호다. 멈춰, 멈춰, 멈춰. 어둠 쪽으로 갈수록 희미해진다.<br>그날부터 팀원들 손등을 밤마다 누가 두드린다. 쉰 박자로.` },
      ok:`셋째 손등 위 허공을 움켜쥐었다. 손이 잡혔다. 작고 차다. 그 손이 이쪽 손등을 두드리려 한다.<br><br>먼저 두드렸다. 이쪽이 그 손등을. 한 번 꾹. 멈춰.<br>손이 굳었다. 신호를 보내기만 하던 것이 신호를 받는 건 처음인 듯. 손을 놓았다. 손이 어둠 속으로 사라졌다. 다시 오지 않았다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A', t:'출구 앞 — 다 왔다는 신호',
  x:`아래층 문 앞이다. 한 사람씩 문을 지난다. 지난 사람은 문 너머에서 벽을 한 번 두드린다. 건넜다는 신호.<br><br>
    넷이 건넜다. 두드림 넷. 이쪽이 마지막이다.<br>
    이쪽이 건너기 전에 문 너머에서 두드림이 하나 더 났다. 다섯째.<br><br>
    문 너머엔 이미 다섯이 있다는 뜻이다. 이쪽 말고.`,
  o:[
    { l:'① 문을 넘기 전에 넷을 손으로 하나씩 짚어 센다.', k:'bond', dc:23,
      ok:`문틈으로 손을 넣었다. 짚었다. 하나, 둘, 셋, 넷. 어깨들. 이쪽 팀 어깨다. 다 안다.<br><br>다섯째 어깨를 찾았다. 손끝이 허공을 지난다. 아무것도 없다. 그런데 두드림은 다섯이었다.<br>건너가서 문을 등으로 막았다. 다섯째 두드림을 낸 것은 이쪽이 건너온 쪽 어딘가에 있다. 문을 닫았다. 다섯이 다시 다섯이 됐다.`,
      ng:`짚는데 넷째 어깨가 너무 차다. 손이 멈췄다.<br><br>넷째 어깨인지 다섯째인지 모른다. 그 사이 문이 닫히려 한다. 억지로 넘었다. 문틀에 어깨가 찍혔다. 그날 밤 팀원 하나가 이쪽 손이 차다고 했다. 어깨를 짚은 손이.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, spirit:-24 } },
    { l:'② 문 너머로 오지 마 신호를 보내고 다른 길로 돈다.', k:'steady', dc:24, wake:1,
      ok:`벽을 세 번 길게 두드렸다. 정한 신호다. 거기 있어. 오지 마. 그리고 문을 넘지 않았다.<br><br>문 너머에서 넷이 대답한다. 각자 한 번씩. 그리고 다섯째도 한 번. 이쪽은 넘지 않았다. 대신 옆 환기구를 기어 내려갔다. 넷 뒤로 내려섰다.<br>넷이 돌아봤다. 문 쪽 벽에 무엇이 서 있었다. 넷 사이에 섰던 자리다. 이쪽이 문을 넘었으면 그 자리가 이쪽 자리였다.<br><br>신호 하나로 사람을 세워 두고 다른 길로 도는 법. 신호가 문을 대신해 줄 수 있다는 걸 알았다. 신호로 길을 막고 몸으로 길을 낸다.`,
      ng:`두드렸는데 문 너머 넷이 따르지 않는다. 다섯째 두드림이 먼저 대답했다. 이쪽 박자로. 이리 와.<br><br>넷 중 하나가 문을 다시 열고 이쪽을 끌어당겼다. 걱정돼서. 넘어가 보니 다섯째는 안 보인다. 넷 중 셋이 등이 차다고 한다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-22, spirit:-26 } }
  ] },

{ at:'A1', t:'부조정실 — 인터컴의 큐',
  x:`부조정실 책상에 인터컴이 놓였다. 빨간 단추. 스피커에서 목소리가 난다. 아무도 단추를 안 눌렀는데.<br><br>
    <span style="color:#8fb3bf;">"카메라 투, 스탠바이. 방청객 위치로. 오늘의 친구 무대 옆 대기."</span><br>
    목소리는 이쪽 팀을 본다. 모니터마다 이쪽 팀이 비친다. 목소리가 말할 때마다 모니터 속 팀원이 한 명씩 고개를 든다.<br><br>
    큐를 주는 쪽과 받는 쪽이 있다. 큐는 한쪽으로만 흐른다. 단추를 누르면 이쪽도 말할 수 있다.`,
  o:[
    { l:'① 단추를 눌러 큐를 되묻는다.', k:'bond', dc:23, wake:1,
      ok:`단추를 눌렀다. 말했다. 오늘의 친구, 확인 바랍니다. 이름 다시.<br><br>스피커가 멈춘다. 큐를 받는 쪽은 되묻지 않는다. 되묻는 건 큐를 주는 쪽이 하는 일이다. 목소리가 헷갈린다. 지직거린다.<br><span style="color:#8fb3bf;">"……확인 중. 대기."</span> 그리고 조용하다. 모니터 속 팀원들이 고개를 숙였다. 대기 상태.<br><br>남의 말길에 이쪽 말을 끼워 넣는 법. 받기만 하던 신호에 되묻는 신호를 걸면 길의 방향이 바뀐다. 단추를 누른 엄지가 그 무게를 기억했다.`,
      ng:`눌렀는데 단추가 안 올라온다. 이쪽 숨소리가 스피커로 나간다. 건물 전체로.<br><br>모니터마다 화면이 이쪽 얼굴로 바뀐다. 목소리가 반가워한다. <span style="color:#8fb3bf;">"오늘의 친구, 마이크 테스트 감사합니다."</span> 단추를 칼로 쑤셔 빼냈다. 손가락이 전기에 데었다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-22, spirit:-26 } },
    { l:'② 인터컴 선을 뽑는다.', k:'break', dc:22,
      ok:`책상 밑으로 손을 넣어 선을 찾았다. 뽑았다.<br><br>스피커가 끊겼다. 모니터 속 팀원들이 멈춘다. 고개를 반쯤 든 채로.<br>대기도 아니고 진행도 아니다. 큐가 끊긴 무대는 다음 지시를 기다린다. 오래 기다릴 것이다. 그 사이 계단으로 갔다.`,
      ng:`선을 뽑자 스피커 대신 벽 전체가 말한다. 천장, 바닥에서. 같은 목소리.<br><br>선은 하나가 아니었다. 벽 속에 선이 많다. 귀를 막고 방을 뛰쳐나왔다. 이명이 한참 갔다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-20, spirit:-22 } }
  ] },

{ at:'A1', t:'무대 옆 — 손가락 다섯 개',
  x:`무대 옆에 무대 감독이 섰다. 헤드셋. 얼굴은 없다. 한 손을 높이 들었다.<br><br>
    손가락 다섯. 넷. 셋. 방송 들어가기 전 손신호다. 둘에서 소리가 끊기고, 하나에서 손가락이 무대를 가리킨다. 가리키는 데로 나가야 한다.<br>
    손가락이 셋에서 멈췄다. 이쪽 팀 쪽으로 손을 돌린다. 이쪽 팀이 다음 순서다.<br><br>
    신호수는 이 손신호를 안다. 남이 쓰는 신호도 신호다.`,
  o:[
    { l:'① 손가락 셈의 쉬는 박자를 읽어 그 틈에 팀을 뺀다.', k:'gaze', dc:23, wake:1,
      ok:`감독 손을 봤다. 손가락이 접히는 사이가 일정하지 않다. 넷에서 셋은 빠르고 셋에서 둘은 길다. 둘 직전에 헤드셋에서 무엇을 듣는다.<br><br>그 듣는 박자가 틈이다. 감독이 귀를 기울이는 그 순간, 손가락이 아무 데도 가리키지 않는다. 팀원들 어깨를 짚었다. 그 박자에 맞춰 한 걸음씩 무대 옆을 빠져나왔다.<br>하나가 접혔을 때 손가락은 빈 통로를 가리켰다. 박수가 났다. 빈 무대에.<br><br>신호를 주는 쪽도 신호를 받는다. 그 받는 틈이 제일 무르다. 남의 손신호에서 숨 쉬는 자리를 찾는 눈이 생겼다.`,
      ng:`읽는데 감독 손가락이 둘로 접혔다. 소리가 끊겼다. 이쪽 귀에서.<br><br>아무것도 안 들린다. 팀원들 입이 움직이는데 소리가 없다. 손가락이 하나. 무대를 가리킨다. 팀원 하나가 걸어 나간다. 소리 없이 부르며 붙잡았다. 소리는 다음 층에서야 돌아왔다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-22, spirit:-26 } },
    { l:'② 감독 손신호를 이쪽이 흉내 내 큐를 바꾼다.', k:'bond', dc:24,
      doom:{ title:'바뀐 큐', what:'큐를 받은 쪽이 되어 무대로 끌려 나갑니다', dc:19, sec:45,
        text:`감독 옆에 서서 손을 들었다. 다섯, 넷, 셋. 그리고 손바닥을 펴서 옆으로 그었다. 컷.<br><br>감독이 이쪽을 돌아본다. 헤드셋이 이쪽을 향한다. 오래. 그리고 감독이 손가락 하나로 이쪽을 가리켰다.<br>큐를 주는 사람이 둘일 수는 없다. 이쪽이 큐를 줬으니 이쪽이 큐를 받을 차례다. 다리가 무대 쪽으로 걷는다. 조명이 이쪽을 따라온다.<br><br>팀원들이 이쪽 팔을 붙든다. 무대 위에서 박수가 시작된다.`,
        dieText:`무대 위에서 손을 높이 든 사람이 하나 있었다. 손가락 다섯. 넷. 셋.<br><br>방청석을 향해 큐를 준다. 둘. 하나. 손가락이 방청석 한 줄을 가리킨다. 거기 앉은 사람들이 일어선다.<br>그 손신호는 정확했다. 박자 하나 틀리지 않았다. 신호를 가르치던 손이었다.` },
      ok:`감독 옆에 서서 손을 들었다. 다섯, 넷, 셋. 그리고 손바닥을 펴서 옆으로 그었다. 컷. 그대로 손을 감독 손 위에 겹쳤다.<br><br>두 손이 한 신호를 낸다. 감독 손가락이 셋에서 더 접히지 못한다. 헤드셋에서 지직거리는 소리.<br>무대 조명이 꺼졌다. 박수가 반쯤 나오다 멎었다. 그 틈에 팀원들이 빠져나갔다. 감독 손에서 이쪽 손을 떼었다. 손바닥이 얼어 있었다.`,
      win:{ exp:24, dream:3 } }
  ] },

{ at:'A1', t:'스튜디오 — 빨간 불 세 개',
  x:`스튜디오에 카메라 세 대. 카메라 위에 작은 빨간 불이 있다. 켜진 카메라가 지금 방송에 나가는 카메라다.<br><br>
    불이 옮겨 다닌다. 하나에서 둘로, 둘에서 셋으로. 켜진 카메라가 비추는 데에 서 있는 사람이 화면에 나간다.<br>
    화면에 나간 사람은 다음 순서가 된다. 벽 모니터에 그렇게 적혀 있다. 화면에 나온 친구는 무대로!<br><br>
    신호수에게 저 빨간 불은 신호등이다.`,
  o:[
    { l:'① 빨간 불을 읽으며 손짓으로 팀을 사각지대로 옮긴다.', k:'bond', dc:23, wake:1,
      ok:`빨간 불이 하나에 켜졌다. 둘과 셋 사이로 팀원들을 손짓했다. 불이 둘로 옮긴다. 셋 뒤로. 셋으로 옮긴다. 하나 앞으로.<br><br>불이 옮겨 가는 데는 반 박자가 걸린다. 그 반 박자 동안 렌즈가 돌아간다. 돌아가는 렌즈는 아무것도 못 잡는다.<br>스튜디오를 가로질렀다. 다섯이 한 번도 화면에 안 나갔다. 벽 모니터에는 빈 스튜디오만 비쳤다.<br><br>남이 쓰는 불빛을 이쪽 길잡이로 읽는 법. 신호는 이쪽을 위해 만들어진 것이 아니어도 이쪽이 읽으면 이쪽 신호가 된다. 손짓이 불빛 박자를 따라가는 게 몸에 붙었다.`,
      ng:`손짓하는데 불이 둘을 건너뛰고 셋으로 갔다. 박자를 바꿨다. 이쪽을 읽었다.<br><br>셋 렌즈에 팀원 하나가 잡혔다. 모니터에 크게. 박수. 그 팀원 발이 무대 쪽으로 향한다. 둘이 붙들고 렌즈 밖으로 끌어냈다. 그 팀원 얼굴에 빨간 불빛이 한참 남았다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-22, spirit:-26 } },
    { l:'② 카메라 렌즈를 차례로 가린다.', k:'hide', dc:22,
      ok:`카메라 뒤로 돌아가 렌즈에 손바닥을 댔다. 불이 다른 데로 옮겨 간다. 다른 팀원이 거기를 가렸다.<br><br>세 대를 다 가렸다. 빨간 불이 셋 다 켜진 채 깜빡인다. 볼 데가 없다.<br>손을 하나씩 떼며 뒷걸음질 쳤다. 마지막 렌즈를 떼자 불이 셋 다 꺼졌다.`,
      ng:`가리는데 렌즈 안쪽에서 손바닥을 마주 댄다. 차갑다. 유리 너머로.<br><br>손을 뗐다. 손바닥 모양 김이 렌즈에 남았다. 그 김 너머로 화면에 이쪽 손바닥이 크게 비친다. 손바닥이 출연했다. 그 손이 며칠째 저리다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, spirit:-24 } },
    { l:'③ 불이 옮겨 가는 순서를 센다.', k:'sense', dc:23,
      ok:`셌다. 하나, 둘, 셋, 둘, 하나, 셋. 그리고 다시 하나, 둘, 셋, 둘, 하나, 셋.<br><br>여섯 박자로 돈다. 방송 순서표대로다. 다음 불이 어디 켜질지 안다. 거기 아무도 안 서게 했다.<br>스튜디오를 건넜다. 마지막에 셋 앞을 지날 때 불이 일곱째 박자로 하나 더 켜졌다. 숨을 참고 지났다.`,
      ng:`세는데 박자가 안 맞는다. 일곱, 여덟. 불이 늘어난다. 카메라가 넷이 됐다.<br><br>넷째 카메라는 어디 있는지 안 보인다. 불만 있다. 이쪽 바로 뒤에서 켜졌다. 뛰었다. 뒤통수가 뜨거웠다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-20, spirit:-22 } }
  ] },

{ at:'A1', t:'방청석 — 박수 표지판',
  x:`방청석 위에 표지판이 걸렸다. 박수. 불이 들어오면 다들 손뼉을 친다. 빈 의자들까지.<br><br>
    표지판이 켜질 때마다 방청석이 한 줄씩 무대 쪽으로 당겨진다. 의자째. 바닥 레일 위로.<br>
    이쪽 팀이 앉은 줄은 뒤에서 셋째다. 앞의 두 줄이 비었다. 무대 앞까지 당겨져 갔다.<br><br>
    켜지는 박자가 있다. 박자가 있으면 쉬는 자리도 있다.`,
  o:[
    { l:'① 표지판이 꺼진 사이마다 팀을 한 줄씩 뒤로 옮긴다.', k:'fix', dc:23,
      ok:`표지판이 꺼졌다. 손짓했다. 다섯이 한 줄 뒤로 기어 넘었다. 켜졌다. 엎드려 박수 소리가 지나가게 했다. 앉은 줄이 앞으로 당겨졌다. 그 줄엔 이제 아무도 없다.<br><br>세 번을 그렇게 했다. 맨 뒷줄 뒤 벽에 닿았다. 더는 당겨질 줄이 없다.<br>표지판이 계속 켜졌다 꺼졌다. 빈 의자들만 무대로 갔다.`,
      ng:`꺼진 사이에 넘는데 꺼진 시간이 짧아졌다. 넘던 팀원이 의자 사이에 걸렸다.<br><br>표지판이 켜졌다. 그 팀원이 걸린 의자째 앞으로 당겨진다. 셋이 다리를 붙들고 버텼다. 의자가 부서졌다. 팀원 정강이가 레일에 긁혔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-16 } },
    { l:'② 의자를 밟고 올라가 표지판 전구를 깬다.', k:'break', dc:23,
      ok:`의자 등받이를 밟고 섰다. 칼자루로 표지판을 쳤다. 전구가 터진다. 박수 글씨가 꺼졌다.<br><br>방청석이 조용해졌다. 손뼉 칠 신호가 없다. 의자들이 레일 위에서 멈췄다.<br>무대 쪽 스피커에서 박수가 녹음된 소리로 나온다. 하지만 녹음은 아무도 안 당긴다.`,
      ng:`치는 순간 표지판이 켜졌다. 바로 눈앞에서. 하얗다.<br><br>손이 저절로 박수를 쳤다. 칼을 놓쳤다. 이쪽이 선 의자가 앞으로 당겨진다. 뛰어내렸다. 발목을 접질렸다. 칼은 무대 앞까지 굴러갔다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, spirit:-20 } }
  ] },

{ at:'A1', t:'7층 — 1분 전 손짓',
  x:`7층 복도. 스튜디오 문 위에 불. 1분 전. 숫자가 줄어든다.<br><br>
    복도에 스태프 다섯이 서 있다. 인형 같은 것들. 헤드셋을 꼈다. 다들 손을 든다. 손신호를 준비한다. 시작 신호가 나오면 이쪽 팀을 문 안으로 손짓할 것이다.<br>
    방송의 손신호는 정해져 있다. 시작, 대기, 줄여, 늘려, 끝.<br><br>
    끝 신호는 손바닥을 목 앞에서 옆으로 긋는 것이다. 아무도 아직 그 손짓을 안 했다.`,
  o:[
    { l:'① 다섯 스태프 앞에서 크게 끝 신호를 그어 보인다.', k:'bond', dc:24, wake:1,
      ok:`복도 한가운데 섰다. 손바닥을 목 앞에 대고 옆으로 그었다. 천천히, 크게. 스태프 다섯이 다 보게.<br><br>스태프들이 멈칫한다. 끝 신호를 받으면 그쪽도 끝 신호를 되돌려야 한다. 신호는 받았다는 신호로 끝난다. 다섯이 하나씩 손바닥을 목 앞에서 긋는다.<br>스튜디오 문 위 숫자가 멈췄다. 39초. 복도 불이 한 칸씩 꺼진다. 그 사이 송출 부스 쪽 문이 열렸다.<br><br>남의 신호 체계 안에서 그 체계가 거절 못 하는 신호를 고르는 법. 신호를 아는 건 신호를 쓸 줄 아는 것과 다르다. 손이 그 차이를 처음 넘었다.`,
      ng:`그었는데 스태프 다섯이 서로 본다. 그리고 다섯이 동시에 늘려 신호를 한다. 양손을 벌려 길게.<br><br>숫자가 늘어난다. 1분이 2분이 됐다. 복도가 길어진다. 스튜디오 문이 멀어진다. 한참 뛰어서야 송출 부스 쪽 문에 닿았다. 다리가 풀렸다.`,
      win:{ exp:25, dream:4 }, lose:{ hp:-24, spirit:-28 } },
    { l:'② 시작 신호가 나오기 전에 송출 부스로 뛴다.', k:'evade', dc:23,
      ok:`숫자가 40초일 때 뛰었다. 스태프 사이로. 손이 뻗어 온다. 몸을 비틀어 빠졌다.<br><br>송출 부스 문이 잠겼다. 손잡이를 흔드는 사이 숫자가 줄어든다. 팀원이 경첩을 칼로 뜯었다. 문이 열렸다.<br>등 뒤에서 스태프들이 일제히 손을 들었다. 시작 신호. 아무도 그쪽을 안 봤다.`,
      ng:`뛰는데 스태프 손 하나가 팀원 옷깃을 잡았다.<br><br>떼어 내느라 늦었다. 숫자가 10초. 다들 귀를 막고 부스 문을 들이받았다. 문이 열렸다. 어깨가 빠졌다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-30, mind:-14 } }
  ] },

{ at:'A2', t:'종탑 — 물 밑에서 치는 종',
  x:`종탑에 종이 매달렸다. 종줄이 바닥 구멍으로 내려가 물에 잠겼다.<br><br>
    종이 운다. 아무도 줄을 안 당겼다. 물 밑에서 당긴다. 땡. 쉬고. 땡, 땡.<br>
    학교 종은 신호다. 기상, 수업, 점호. 다 박자가 다르다. 벽에 박자표가 붙어 있다. 반쯤 지워졌다.<br><br>
    신호수는 종소리를 듣고 무엇을 부르는지 알 수 있다. 그리고 무엇이 오는지도.`,
  o:[
    { l:'① 종소리 박자를 지워진 박자표와 맞춰 읽는다.', k:'sense', dc:23, wake:1,
      ok:`들었다. 땡. 쉬고. 땡, 땡. 박자표에서 지워지지 않은 줄을 찾았다. 수업 시작. 셋째 줄.<br><br>수업 시작이면 복도의 것들이 교실로 들어간다. 복도가 빈다. 팀원들을 손짓해 종탑 계단을 내려갔다. 복도엔 아무도 없었다. 교실마다 물속에서 책상 끄는 소리가 났다.<br>다음 종은 쉬는 시간이다. 그 전에 다음 층에 닿았다.<br><br>남이 정한 신호를 이쪽 시계로 쓰는 법. 종이 울릴 때마다 무엇이 어디로 움직이는지 안다. 귀가 이 학교의 시간표를 외워 가기 시작했다.`,
      ng:`읽는데 박자가 박자표 어느 줄과도 안 맞는다. 땡, 땡, 땡, 땡. 끝없이.<br><br>지워진 줄이다. 박자표 맨 밑에 있었을 줄. 무엇인지 모른다. 그 소리가 날 때 계단 밑 물이 끓듯 일어났다. 다 같이 종탑 위로 뛰어올랐다. 물이 계단 반까지 차올랐다가 빠졌다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-22, spirit:-26 } },
    { l:'② 종줄을 붙들어 종을 멈춘다.', k:'steady', dc:23,
      doom:{ title:'젖은 종줄', what:'종줄에 감겨 물 밑으로 끌려갑니다', dc:18, sec:50,
        text:`종줄을 두 손으로 쥐었다. 종이 멈췄다.<br><br>물 밑에서 당기는 쪽이 멈칫한다. 그리고 다시 당긴다. 이번엔 종이 아니라 줄 끝의 이쪽을.<br>줄이 손목을 감는다. 젖은 밧줄이 뱀처럼. 바닥 구멍 쪽으로 끌린다. 무릎이 구멍 가장자리에 걸렸다.<br><br>물 밑에서 종소리가 난다. 이쪽 몸으로 치는 종소리.`,
        dieText:`종이 다시 울렸다. 땡. 쉬고. 땡, 땡.<br><br>박자가 조금 달라졌다. 쉬는 자리에 짧은 박이 하나 더 들어간다. 새끼손가락 거는 박자.<br>팀원들은 그 박자를 안다. 확인 신호다. 이쪽이 보낸 진짜 신호라는 표시. 그 종소리를 따라가지 않으려고 귀를 막고 내려갔다.` },
      ok:`종줄을 두 손으로 쥐었다. 종이 멈췄다. 줄이 당겨지자마자 손을 놓았다. 줄이 구멍으로 빨려 내려갔다.<br><br>종이 한참 흔들리다 멎었다. 물 밑에서 당길 줄이 없다. 끝이 다 내려갔다.<br>종탑이 조용해졌다. 이 층에서는 다음 종이 울리지 않는다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A2', t:'물속 복도 — 아래에서 대답하는 불빛',
  x:`물에 잠긴 복도를 헤엄쳐 건넌다. 앞이 안 보인다. 방수 등불로 신호를 정했다. 한 번 깜빡이면 따라와. 두 번은 위로.<br><br>
    이쪽이 한 번 깜빡였다. 뒤에서 팀원들 불빛이 한 번씩 대답한다. 넷.<br>
    그리고 아래에서 하나 더. 복도 바닥보다 깊은 데서. 한 번.<br><br>
    따라오겠다는 대답이다. 아니면 따라오라는 신호다. 같은 신호다.`,
  o:[
    { l:'① 위로 신호를 길게 보내 팀을 수면으로 올린다.', k:'bond', dc:23, wake:1,
      ok:`등불을 두 번 깜빡이고 길게 켜 두었다. 위로, 지금, 계속.<br><br>뒤의 불빛 넷이 위로 오른다. 아래 불빛도 따라 오른다. 천천히. 수면 직전에서 아래 불빛이 멈췄다. 물 밖으로는 못 온다.<br>천장 아래 숨 고일 데에 다섯 머리가 떠올랐다. 아래 불빛이 두 번 깜빡였다. 위로. 이쪽 신호를 이쪽에게 돌려준다. 내려오라는 뜻으로.<br><br>같은 신호도 오래 켜 두면 다른 뜻이 된다. 신호에 길이를 실어 따르는 쪽을 고른다. 이쪽 팀만 아는 길이가 생겼다.`,
      ng:`길게 켜는데 등불이 물에 들어가 깜빡거린다. 고장이다. 짧게, 짧게.<br><br>팀원들이 따라와 신호로 읽었다. 한 팀원이 아래로 내려간다. 아래 불빛 쪽으로. 뒤쫓아 내려가 발목을 잡아 올렸다. 둘 다 물을 먹었다. 숨 고일 데까지 겨우 왔다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, spirit:-24 } },
    { l:'② 등불을 품에 가리고 어둠 속에서 벽을 더듬어 간다.', k:'hide', dc:23,
      ok:`등불을 품에 넣었다. 다른 팀원들에게도 등을 쳐서 알렸다. 불을 끄라고.<br><br>깜깜한 물속. 벽을 더듬어 헤엄쳤다. 아래 불빛만 남았다. 혼자 깜빡인다. 대답할 불빛이 없다.<br>복도 끝 계단에 닿아 머리를 내밀었다. 숨을 몰아쉬며 돌아보니 물 밑 불빛이 한 자리에서 오래 깜빡이고 있었다.`,
      ng:`품에 넣었는데 불빛이 옷 틈으로 샜다. 한 줄기.<br><br>아래 불빛이 그 한 줄기를 향해 올라온다. 빨리. 벽을 차고 계단으로 뛰었다. 발뒤꿈치를 무엇이 스쳤다. 차갑고 미끄러웠다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-28, mind:-16 } },
    { l:'③ 아래 불빛이 진짜 사람인지 그쪽으로 내려가 본다.', k:'sense', dc:24,
      doom:{ title:'아래의 불빛', what:'불빛을 따라 물 밑 깊이 끌려 내려갑니다', dc:18, sec:45,
        text:`아래로 내려갔다. 불빛이 가깝다. 등불이다. 이 학교 비상 등불.<br><br>쥔 손이 보인다. 하얗다. 교복 소매. 등불이 한 번 깜빡인다. 따라와.<br>그 손이 이쪽 손목을 잡는다. 등불째 아래로. 숨이 다 됐다. 위를 보니 팀원들 불빛 넷이 아주 멀다. 두 번 깜빡인다. 위로. 다급하게.<br><br>몸이 아래로 내려간다. 이쪽 등불이 손에서 미끄러진다.`,
        dieText:`팀원들이 수면에서 기다렸다. 아래 불빛이 둘이 됐다.<br><br>둘이 나란히 깜빡인다. 한 번. 따라와. 한 불빛은 박자가 정확하다. 신호를 가르치던 박자다.<br>팀원들은 따라가지 않았다. 다음 층으로 갈 때 물 밑에서 불빛 둘이 한참 따라왔다.` },
      ok:`아래로 조금만 내려갔다. 불빛이 보일 만큼만. 비상 등불이다. 쥔 손이 교복 소매다.<br><br>사람이 아니다. 거기서 멈추고 바로 올라왔다. 위로 두 번 깜빡였다. 팀원들이 따랐다.<br>아래 불빛은 따라오지 않았다. 한 번만 더 깜빡였다. 다음에.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A2', t:'기숙사 복도 — 안에서 두드리는 사물함',
  x:`복도 양쪽에 사물함이 줄지어 있다. 반쯤 물에 잠겼다.<br><br>
    한 사물함이 안에서 두드려진다. 셋, 하나, 셋. 이쪽 팀 박자다.<br>
    팀원은 다섯 다 여기 있다. 그런데 셋째 팀원이 아까 이 사물함 앞에서 한참 서 있었다. 혼자. 다시 왔을 때 셋째 손이 젖어 있었다.<br><br>
    사물함 번호는 213이다.`,
  o:[
    { l:'① 이쪽 팀원만 아는 물음 박자로 사물함에 묻는다.', k:'bond', dc:23, wake:1,
      ok:`사물함 문에 손가락을 댔다. 셋째 이름 글자 수로 두드렸다. 그리고 쉬고 물음 박자.<br><br>안에서 대답이 없다. 셋, 하나, 셋만 반복한다. 모르는 물음에는 아는 박자로만 답한다.<br>셋째를 돌아봤다. 셋째가 물음 박자에 손가락을 움직여 대답한다. 이쪽 손등에. 정확하게. 진짜 셋째다. 그럼 사물함 안은 셋째가 아니다.<br><br>셋째가 아까 저 앞에서 박자를 가르쳐 줬다. 몰래. 불쌍해서. 안에서 누가 울어서. 신호는 가르치는 순간 남의 것이 된다. 그래서 신호 안에 그 사람만 아는 걸 넣어야 한다. 그 원칙이 이제 이쪽 신호의 첫 줄이다.`,
      ng:`물었는데 안에서 대답이 온다. 정확하게. 셋째 이름 글자 수로.<br><br>셋째가 가르쳐 준 게 하나가 아니었다. 이름도 줬다. 사물함 문이 조금 열린다. 안에서 젖은 손이 나와 셋째 소매를 잡는다. 셋이 붙어 떼어 냈다. 문을 발로 차서 닫았다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-22, spirit:-28 } },
    { l:'② 사물함 문을 칼로 비틀어 연다.', k:'break', dc:23,
      ok:`칼날을 문틈에 넣어 비틀었다. 자물쇠가 튕겨 나갔다.<br><br>안에 물이 가득하다. 그 속에 명찰 하나. 213. 이름이 지워졌다. 두드리던 것은 없다.<br>명찰을 꺼내 물 위에 띄웠다. 사물함이 조용해졌다. 셋째가 그 명찰을 오래 봤다.`,
      ng:`비트는데 문이 안쪽에서 버틴다. 안에서 문고리를 쥐었다.<br><br>칼이 부러졌다. 부러진 날 끝이 이쪽 손등을 그었다. 사물함은 계속 두드린다. 셋, 하나, 셋. 조금 화가 난 박자로.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, spirit:-20 } }
  ] },

{ at:'A2', t:'방송실 — 켜진 마이크',
  x:`방송실 마이크가 켜져 있다. 빨간 불. 학교 전체 스피커로 이어진 마이크다.<br><br>
    여기서 말하면 모든 교실, 모든 복도, 모든 물속에 들린다.<br>
    팀원 하나가 이 층 어딘가에 갇혔다. 아까 갈라졌다. 찾을 길이 없다. 소리를 내면 찾을 수 있다. 소리를 내면 다른 것들도 찾아온다.<br><br>
    신호수는 말이 아니어도 되는 신호를 생각한다.`,
  o:[
    { l:'① 마이크에 손가락 두드림만 보낸다.', k:'bond', dc:23, wake:1,
      ok:`마이크에 입을 대지 않았다. 손가락으로 마이크 머리를 두드렸다. 셋, 하나, 셋. 그리고 이쪽 팀만 아는 끝 박자.<br><br>학교 전체 스피커가 두드림을 낸다. 퉁, 퉁. 말이 아니다. 물속 것들은 말에 몰린다. 두드림에는 몰리지 않는다. 사람 목소리가 아니니까.<br>한참 뒤 어딘가 복도 끝 스피커 밑에서 두드림이 대답했다. 끝 박자까지. 그쪽으로 갔다. 팀원이 청소함에 갇혀 있었다.<br><br>모든 귀에 닿는 길로 한 사람에게만 말하는 법. 듣는 귀는 많아도 알아듣는 귀는 하나다. 그 신호를 짓는 손이 생겼다.`,
      ng:`두드리는데 마이크가 두드림을 목소리로 바꾼다. 이쪽 목소리로. 셋, 하나, 셋 박자로 이쪽 이름을 부른다.<br><br>학교 전체가 이쪽 이름을 부른다. 물속 것들이 일제히 방송실 쪽으로. 마이크를 끄고 뛰었다. 팀원은 다음 층에서야 찾았다. 반쯤 얼어 있었다.`,
      win:{ exp:25, dream:4 }, lose:{ hp:-24, spirit:-30 } },
    { l:'② 마이크를 끄고 불빛 신호로만 찾는다.', k:'fix', dc:22,
      ok:`마이크를 껐다. 등불을 들고 복도마다 비추며 깜빡였다. 한 번. 따라와.<br><br>세 번째 복도에서 청소함 문틈으로 빛이 깜빡였다. 성냥불. 한 번.<br>문을 열었다. 팀원이 성냥을 쥐고 있었다. 마지막 개비였다.`,
      ng:`끄려는데 스위치가 안 내려간다. 빨간 불이 그대로다.<br><br>이쪽 숨소리가 학교 전체에 퍼진다. 숨을 참았다. 오래. 마이크 선을 이로 끊었다. 입술이 찢어졌다. 그 사이 물속에서 무엇이 방송실 문을 두드렸다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, mind:-20 } }
  ] },

{ at:'A2', t:'강당 — 마지막 점호 박자',
  x:`강당에 점호가 울린다. 마지막 점호다. 사감 목소리가 물을 타고 온다. 이름이 하나씩.<br><br>
    대답하면 안 된다. 대답하면 남는다. 그런데 대답 안 하면 이름이 또 불린다. 더 크게. 세 번 불리면 사감이 찾으러 온다.<br>
    종줄은 무대 끝이다. 거기까지 가려면 점호 줄 사이를 지나야 한다.<br><br>
    이름 하나가 불리는 데 숨 두 번. 그 박자를 센다.`,
  o:[
    { l:'① 점호 박자에 맞춰 무음 손짓으로 다섯을 한 칸씩 옮긴다.', k:'bond', dc:24, wake:1,
      ok:`이름이 불릴 때 사감 고개가 그쪽으로 간다. 그 박자에 손을 내렸다. 한 칸. 다음 이름. 한 칸.<br><br>다섯이 이쪽 손끝만 보고 움직였다. 숨 두 번에 한 걸음. 사감 고개가 돌아올 때는 멈춰. 손바닥 하나로.<br>스무 이름이 지나갔다. 다섯이 종줄 앞에 섰다. 이쪽 팀 이름은 아직 안 불렸다. 그 전에 종줄을 당겼다.<br><br>남의 박자에 이쪽 걸음을 얹는 법. 점호는 이쪽을 부르는 신호였는데 이쪽을 옮기는 신호가 됐다. 손 하나로 다섯을 남의 박자 사이로 걷게 했다.`,
      ng:`손을 내렸는데 사감이 이름을 건너뛰었다. 박자가 바뀌었다.<br><br>고개가 이쪽 팀 쪽으로 돌아온다. 다섯이 움직이던 중이다. 사감이 본다. 출석부에 무엇을 적는다. 다섯 칸. 다들 엎드려 기었다. 종줄에 닿을 때까지 무릎이 다 까졌다.`,
      win:{ exp:25, dream:4 }, lose:{ hp:-24, spirit:-30 } },
    { l:'② 점호 사이를 뛰어 곧장 종을 친다.', k:'break', dc:23,
      ok:`이름이 길게 불리는 틈에 뛰었다. 물을 헤치고 무대로.<br><br>종줄을 쥐고 당겼다. 종이 울린다. 점호가 끊겼다. 사감 목소리가 멈춘다.<br>뒤돌아보니 팀원 넷이 아직 점호 줄 사이에 있다. 종소리 속에서 아이들이 고개를 든다. 넷이 그 사이로 뛰어왔다. 아무도 안 잡혔다. 아슬아슬했다.`,
      ng:`뛰는데 이쪽 이름이 불렸다. 한 번. 다리가 멈췄다. 대답할 뻔했다.<br><br>입을 손으로 막고 다시 뛰었다. 두 번째로 불렸다. 무대 계단에서 미끄러졌다. 세 번째가 불리기 직전에 종줄을 당겼다. 팔꿈치가 깨졌다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, mind:-16 } },
    { l:'③ 점호가 몇 번째 이름에서 쉬는지 듣는다.', k:'gaze', dc:23,
      ok:`들었다. 사감이 이름 열둘마다 쉰다. 출석부를 넘긴다. 젖은 종이가 붙어서 넘기는 데 숨 다섯 번.<br><br>그 다섯 숨이 길이다. 열둘째 이름이 지나자 손짓했다. 다섯이 그 다섯 숨에 무대 끝까지 갔다. 종을 쳤다.<br>사감은 출석부를 넘기다 말고 고개를 들었다. 종이 다 울린 뒤였다.`,
      ng:`듣는데 이름 열둘째가 이쪽 팀원 이름이었다. 쉬는 대신 그 이름이 다시 불렸다.<br><br>팀원 입이 열린다. 손으로 막았다. 사감이 출석부를 넘기지 않는다. 그 이름 칸에서 손가락이 멈췄다. 한참 버텼다. 종은 결국 다른 팀원이 쳤다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-22, spirit:-22 } }
  ] },

]);

// ------------------------------------------
// 표사 · 내공
// ------------------------------------------
kJob('escort', 'A', [

{ at:'A', t:'첫 통로 — 되돌아오는 표호',
  x:`길에 들어서면 외친다. 지나간다고. 이 짐에는 지키는 사람이 있다고. 표사의 버릇이다.<br><br>
    외쳤다. 통로 끝까지 울린다. 그리고 통로 끝에서 같은 소리가 돌아온다.<br>
    메아리가 아니다. 목소리가 조금 다르다. 더 낮고 더 느리다. 그리고 한 마디가 더 붙어 있다. 짐 다섯.<br><br>
    이쪽은 짐 수를 외치지 않았다.`,
  o:[
    { l:'① 내공을 실어 다시 외치되 이번엔 짐 수를 먼저 박는다.', k:'bond', dc:23, cost:{ qi:28 }, wake:1,
      ok:`단전에서 끌어올렸다. 지나간다. 짐 다섯, 사람 하나. 다섯 다 지키는 짐이다.<br><br>소리가 통로 벽을 밀고 간다. 끝까지. 돌아오는 소리가 없다. 한참. 그러다 낮은 목소리가 다시 온다. 짐 다섯. 사람 하나. 이쪽 말을 그대로.<br>그리고 덧붙이지 않았다. 짐 수를 먼저 정한 쪽이 이겼다. 저쪽은 받아 적기만 했다.<br><br>외침은 겁주는 소리인 줄 알았다. 먼저 정하는 소리이기도 하다. 짐이 몇이고 누가 지키는지를 먼저 박아 두면 길 위의 셈은 이쪽 셈을 따른다. 목에서 단전까지 그 소리 길이 하나 더 트였다.`,
      ng:`끌어올리는데 목에서 갈라졌다. 짐 다섯까지만 나왔다.<br><br>사람 하나를 못 외쳤다. 돌아온 소리가 이번엔 분명하다. 짐 다섯. 지키는 사람 없음.<br>그 뒤로 통로를 다 지날 때까지 등 뒤에서 무엇이 따라왔다. 짐 실은 수레를 따르는 들개처럼.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-22, spirit:-26 } },
    { l:'② 더 외치지 않고 팀원들을 가운데 모아 둘러싸 간다.', k:'steady', dc:22,
      ok:`입을 다물었다. 팀원들을 가운데 몰았다. 이쪽이 앞에 섰다. 뒤는 제일 힘 좋은 팀원.<br><br>짐 다섯이 한 덩어리로 움직인다. 덩어리는 세기 어렵다.<br>통로 끝에서 낮은 목소리가 셌다. 하나, 둘. 셋에서 막혔다. 덩어리 속 사람을 못 가른다. 그 사이 지나갔다.`,
      ng:`모으는데 팀원 하나가 덩어리 밖으로 밀려났다.<br><br>낮은 목소리가 바로 센다. 하나. 그 팀원 어깨가 움찔한다. 누가 짚었다. 끌어들였다. 그 팀원은 그 뒤로 내내 어깨가 무겁다고 한다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, spirit:-24 } }
  ] },

{ at:'A', t:'좁은 길목 — 위가 트인 자리',
  x:`통로가 좁아지고 위가 트였다. 천장이 높다. 어둠이 고였다.<br><br>
    산길이었다면 매복 자리다. 표사 눈에는 다 보인다. 양쪽 벽이 높고 위가 트인 곳. 짐이 줄지어 지나야 하는 곳.<br>
    위에서 무엇이 내려다본다. 소리는 없다. 그래도 안다. 이런 데는 늘 무엇이 있다.<br><br>
    여기서 짐은 제일 지친 사람이다.`,
  o:[
    { l:'① 내공을 귀로 모아 위의 기척을 읽는다.', k:'sense', dc:23, cost:{ qi:26 },
      ok:`숨을 고르고 내공을 귀로 모았다. 위의 어둠이 들린다.<br><br>숨소리 셋. 아주 느리다. 왼쪽 벽 위에 둘, 오른쪽에 하나. 오른쪽 것이 크다. 왼쪽 둘이 몰고 오른쪽이 채는 식이다. 산적도 그렇게 한다.<br>오른쪽 벽에 바짝 붙어 걸었다. 오른쪽 것 바로 밑. 채려면 몸을 뒤집어야 한다. 아무도 안 채였다.`,
      ng:`모은 내공이 위에서 내려오는 바람에 흩어졌다. 귀가 먹먹하다.<br><br>아무것도 못 들었다. 지나가는데 위에서 무엇이 내려와 맨 뒷사람 머리칼을 한 움큼 쥐고 올라갔다. 머리칼만. 맨 뒷사람 두피에서 피가 났다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-18 } },
    { l:'② 제일 지친 팀원을 가운데 두고 넷이 둘러싸 간다.', k:'bond', dc:23, wake:1,
      ok:`제일 지친 팀원을 가운데 세웠다. 넷이 어깨를 붙여 둘러쌌다. 이쪽은 위를 본다. 칼을 위로.<br><br>위에서 무엇이 한 번 내려왔다. 둘러싼 어깨에 닿았다. 가운데까지 손이 안 닿는다. 다시 올라갔다.<br>길목을 다 지났다. 가운데 팀원이 처음으로 혼자 걸었다. 둘러싸인 동안 숨을 돌렸다고.<br><br>짐을 둘러싸는 법은 산에서 배웠다. 땅 밑에서는 위까지 둘러싸야 한다. 칼끝을 하늘로 세우고 걷는 걸음이 몸에 붙었다. 짐을 지키는 둘레가 한 칸 높아졌다.`,
      ng:`둘러싸는데 넷의 걸음이 엇갈렸다. 어깨 사이가 벌어졌다.<br><br>위에서 손이 그 틈으로 내려왔다. 가운데 팀원 목덜미를 쥐었다. 다 같이 칼을 휘둘렀다. 손이 놓았다. 목덜미에 손톱자국 넷.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, spirit:-22 } },
    { l:'③ 먼저 벽을 타고 올라가 위를 친다.', k:'evade', dc:24,
      doom:{ title:'매복 자리', what:'벽 위에서 채여 어둠 속으로 끌려 올라갑니다', dc:18, sec:50,
        text:`벽을 탔다. 손끝으로 틈을 짚으며. 위가 가깝다.<br><br>손을 뻗어 벽 끝을 쥐었다. 그 손을 위에서 무엇이 쥐었다. 반가운 듯이. 짐보다 지키는 사람을 먼저 채 간다. 그게 매복이다.<br>몸이 들린다. 발이 벽에서 떨어진다. 아래에서 팀원들이 이쪽 발목을 붙든다.<br><br>위의 어둠이 깊다. 끝이 안 보인다.`,
        dieText:`팀원들 손에 신발 한 짝이 남았다.<br><br>길목 위에서 소리가 났다. 외치는 소리. 지나간다. 짐 넷.<br>팀원들은 길목을 지났다. 위에서 아무것도 내려오지 않았다. 지키는 사람이 이미 위에 있었으니까.` },
      ok:`벽을 탔다. 끝에 닿기 전에 멈췄다. 칼을 위로 쑤셨다.<br><br>칼끝에 무엇이 걸렸다. 무르다. 위에서 비명. 무엇이 벽 위에서 떨어져 이쪽 옆을 스쳐 바닥으로 갔다. 바닥에서 버둥대다 어둠으로 기어갔다.<br>내려와서 팀원들을 지나게 했다. 칼날에 검은 것이 묻었다. 냄새가 고였다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A', t:'쉬는 자리 — 짐 하나가 늘었다',
  x:`쉬는 자리에서 짐을 센다. 표사는 쉴 때마다 센다. 산에서도 그랬다. 쉬는 동안 짐이 제일 많이 없어진다.<br><br>
    팀원 다섯. 깔개 다섯. 짐 다섯.<br>
    다시 셌다. 깔개가 여섯이다. 여섯째 깔개는 젖었다. 그 위에 아무도 없는데 움푹 눌렸다.<br><br>
    여섯째 짐이 쉬고 있다.`,
  o:[
    { l:'① 짐마다 이쪽 표기 끈을 하나씩 묶어 둔다.', k:'fix', dc:23, wake:1,
      ok:`허리띠에서 붉은 끈을 풀었다. 다섯 가닥으로 잘랐다. 팀원 손목에 하나씩 맸다. 이쪽이 지키는 짐이라는 표시.<br><br>여섯째 깔개엔 안 맸다. 밤새 깔개가 움직였다. 팀원들 쪽으로 조금씩. 붉은 끈 앞에서 멈췄다. 끈이 있는 짐 옆에는 못 눕는다.<br>아침에 여섯째 깔개는 쉬는 자리 밖에 있었다. 물기가 말라 있었다.<br><br>표기는 깃발만이 아니다. 짐 하나하나에 묶는 끈도 표기다. 이쪽 짐에 이쪽 표시를 하는 것. 그 습관이 손에 박혔다. 그 뒤로 쉴 때마다 끈부터 맨다.`,
      ng:`묶는데 끈이 여섯째 깔개 쪽으로 흘러내렸다. 그 위에 떨어졌다.<br><br>여섯째 깔개에 표기가 생겼다. 이쪽 짐이 됐다. 밤새 여섯째가 이쪽 등 뒤에 누워 있었다. 숨소리가 차갑다. 아침에 등이 젖어 있었다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-22, spirit:-28 } },
    { l:'② 여섯째 깔개를 걷어 치우고 다섯을 붙여 눕힌다.', k:'bond', dc:22,
      ok:`여섯째 깔개를 둘둘 말았다. 무겁다. 안에 무엇이 있는 것처럼. 어둠 쪽으로 던졌다.<br><br>다섯을 바짝 붙여 눕혔다. 빈틈이 없게. 이쪽은 그 둘레를 돌며 밤을 샜다.<br>새벽녘 어둠 쪽에서 깔개 펴는 소리가 났다. 거기서 혼자 쉬는 것이다.`,
      ng:`마는데 깔개가 이쪽 팔을 감았다. 젖은 천이 손목을 조인다.<br><br>떼어 내느라 소리가 났다. 다 깼다. 아무도 다시 못 잤다. 손목에 천 자국이 붉게 남았다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, mind:-20 } }
  ] },

{ at:'A', t:'긴 통로 — 업은 짐이 하는 말',
  x:`다친 팀원을 업었다. 짐 지는 건 몸에 익었다.<br><br>
    등 뒤에서 팀원이 속삭인다. 내려놔. 무거우면 내려놔도 돼. 여기 두고 가.<br>
    그 팀원 목소리가 아니다. 그 팀원은 이런 말을 할 사람이 아니다. 내려놓으라는 짐은 없다. 짐은 실어 달라고 할 뿐이다.<br><br>
    그런데 등에 업힌 무게는 그 팀원 무게다. 정확하게.`,
  o:[
    { l:'① 내공으로 허리를 받치고 대답 없이 계속 걷는다.', k:'steady', dc:23, cost:{ qi:30 }, wake:1,
      ok:`단전에서 내공을 허리로 내렸다. 짐을 고쳐 업었다. 대답하지 않았다.<br><br>속삭임이 계속된다. 내려놔. 두고 가. 걸음을 바꾸지 않았다. 짐이 무슨 말을 하든 짐을 지는 쪽은 걸음으로 대답한다.<br>통로 끝에서 업힌 팀원이 진짜 목소리로 말했다. 방금 꿈을 꿨다고. 누가 자기 입으로 이상한 말을 했다고.<br><br>짐의 말과 짐을 갈라 듣는 법. 등에 진 무게는 믿고 귀에 들리는 말은 안 믿는다. 허리가 그 둘을 나눠 받쳤다.`,
      ng:`내공을 내리는 사이 속삭임이 이름을 불렀다. 이쪽 이름. 어머니 목소리로.<br><br>걸음이 꼬였다. 무릎을 찧었다. 업힌 팀원이 굴러떨어졌다. 다친 다리를 또 다쳤다. 비명은 그 팀원 목소리였다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-28, spirit:-24 } },
    { l:'② 내려놓고 업혔던 사람 얼굴을 확인한다.', k:'gaze', dc:23,
      doom:{ title:'내려놓은 짐', what:'등에 붙은 것에게 목을 감겨 통로 끝으로 끌려갑니다', dc:18, sec:50,
        text:`팀원을 내려놓았다. 얼굴을 봤다. 그 팀원이다. 기절해 있다.<br><br>그럼 속삭인 건. 등이 아직 무겁다. 내려놓았는데.<br>목에 팔이 감긴다. 내려놔. 그래, 잘했어. 이제 이쪽을 업고 가자. 목소리가 가까워진다. 귀 바로 뒤.<br><br>발이 통로 끝 쪽으로 걷는다. 왔던 길로. 이쪽이 짐이 됐다.`,
        dieText:`팀원들이 기절한 팀원을 깨웠을 때 통로에 아무도 없었다.<br><br>통로 끝 어둠에서 소리가 났다. 외치는 소리. 지나간다. 짐 하나.<br>그 소리는 뒤로 갈수록 낮아졌다. 짐을 업은 사람이 무거운 걸음으로 멀어지는 것처럼.` },
      ok:`팀원을 벽에 기대 내려놓았다. 얼굴을 봤다. 그 팀원이다. 기절했다.<br><br>등이 가벼워졌는지 확인했다. 가볍다. 그럼 속삭인 건 업힌 사람 입을 빌린 것이다. 내려놓으라고 한 건 내려놓게 하려는 것.<br>팀원 입에 천을 물리고 다시 업었다. 속삭임은 다시 나오지 않았다. 천이 축축하게 젖었다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A', t:'갈림길 — 버려지는 사람',
  x:`다른 팀이 갈림길에서 한 사람을 두고 간다. 그 사람은 앉아서 귀를 막고 있다.<br><br>
    불렸다고 한다. 계속 불린다고. 데려가면 다 같이 불린다고 그쪽 반장이 말한다. 그래서 두고 간다고.<br>
    표사는 짐을 버리는 걸 못 본다. 짐은 누군가에게 가야 한다. 이 사람은 집에 가야 하는 짐이다.<br><br>
    그쪽 반장이 이쪽을 본다. 대신 질 거냐는 눈이다.`,
  o:[
    { l:'① 내공을 끌어올려 그 사람을 이쪽 등에 진다.', k:'bond', dc:23, cost:{ qi:28 }, wake:1,
      ok:`그 사람을 업었다. 내공을 허리에 둘렀다. 그 사람이 이쪽 목을 꽉 안는다.<br><br>걸을 때마다 그 사람 귀에 대고 말했다. 짐은 짐꾼 말만 들으면 된다고. 다른 소리는 짐꾼이 듣겠다고.<br>그 사람을 부르던 소리가 이쪽 귀로 옮겨 왔다. 이쪽 이름이 아니라 그 사람 이름으로. 이쪽은 그 이름에 대답할 일이 없다. 그 소리는 이쪽 귀에서 헛돌다 사라졌다.<br><br>남을 부르는 소리를 대신 받아 주는 법. 짐을 지는 건 무게만 지는 게 아니다. 짐에 붙은 것까지 진다. 등이 그 무게의 모양을 처음 알았다.`,
      ng:`업었는데 그 사람이 이쪽 귀를 막는다. 자기 귀 대신.<br><br>소리가 이쪽 귀로 쏟아진다. 그 사람 이름. 그리고 이쪽 이름. 둘이 번갈아. 걸음이 비틀린다. 결국 둘 다 갈림길에 주저앉았다. 그쪽 팀은 이미 멀리 갔다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-22, spirit:-28 } },
    { l:'② 그 사람 귀에 천을 틀어막고 일으켜 걷게 한다.', k:'heal', dc:22,
      ok:`천을 찢어 뭉쳤다. 그 사람 귀에 단단히 막았다. 귀를 덮고 머리를 감쌌다.<br><br>소리가 줄었다고 한다. 일어섰다. 스스로 걸었다. 이쪽 팀 맨 뒤에 섰다.<br>다음 층에서 그쪽 팀을 만났다. 반장이 그 사람을 보고 고개를 돌렸다. 그 사람이 반장에게 손을 흔들었다. 귀가 막혀 아무 말도 못 들었다.`,
      ng:`막는데 귀에서 물이 흘러나온다. 맑은 물. 그칠 줄 모른다.<br><br>천이 다 젖었다. 그 사람이 웃기 시작했다. 젖은 귀로 무엇을 듣는다. 일어서서 갈림길 다른 쪽으로 걸어간다. 붙잡았지만 팔 힘이 너무 세다. 놓쳤다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, spirit:-24 } }
  ] },

{ at:'A', t:'긴 계단 — 짐 끈이 당겨진다',
  x:`팀원들 허리를 끈 하나로 이었다. 짐을 묶듯이. 계단을 내려갈 때 하나가 미끄러져도 넷이 붙들게.<br><br>
    계단 중간쯤에서 끈이 당겨졌다. 맨 뒤에서. 위로.<br>
    맨 뒤 팀원이 끌려 올라간다. 끈이 팽팽해지며 그 앞사람도 한 계단 끌린다. 그 앞사람도.<br><br>
    묶은 끈은 같이 살게도 하고 같이 끌려가게도 한다. 짐을 묶는 사람은 언제 끈을 풀어야 하는지도 안다.`,
  o:[
    { l:'① 끈을 끊고 맨 뒤 팀원에게 뛰어올라 품에 안는다.', k:'bond', dc:23, wake:1,
      ok:`칼로 이쪽 앞 끈을 끊었다. 넷은 아래로 자유롭게. 이쪽은 위로 뛰었다. 계단 셋씩.<br><br>맨 뒤 팀원이 끈째 위로 끌려간다. 끈 끝이 어둠 속에 있다. 팀원 허리를 끌어안았다. 그리고 그 허리끈을 끊었다. 끈만 어둠 속으로 휙 올라갔다.<br>안은 채로 계단에 주저앉았다. 위에서 끈을 감는 소리. 끝에 아무것도 없다는 걸 알고 멈췄다.<br><br>짐을 묶은 끈을 언제 끊는지. 끊고 나서 짐을 손으로 붙드는 법. 끈보다 팔이 짐을 오래 지킨다. 그 순서가 몸에 새겨졌다.`,
      ng:`끊는데 끈이 너무 팽팽해서 칼날이 미끄러졌다. 이쪽 손바닥을 베었다.<br><br>그 사이 맨 뒤 팀원이 계단참 하나를 넘어갔다. 피 흐르는 손으로 끈을 쥐고 당겼다. 다 같이 당겼다. 겨우 끌어내렸다. 팀원 허리에 끈 자국이 시퍼렇다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, spirit:-24 } },
    { l:'② 내공을 실어 끈을 거꾸로 당겨 버틴다.', k:'break', dc:24, cost:{ qi:30 },
      doom:{ title:'짐 끈', what:'묶은 끈째 계단 위 어둠으로 끌려 올라갑니다', dc:18, sec:50,
        text:`끈을 두 손으로 쥐었다. 내공을 팔로 끌어올렸다. 당겼다.<br><br>위의 힘이 멈칫한다. 그리고 웃는 것처럼 끈이 한 번 떨린다. 다시 당긴다. 이번엔 다섯 다를.<br>끈이 묶인 허리마다 같은 힘이 걸린다. 이쪽이 제일 아래다. 제일 많이 당겨진다. 발이 계단을 미끄러져 올라간다.<br><br>끈을 끊어야 한다. 손이 끈을 놓지 않는다. 짐을 묶은 끈이다.`,
        dieText:`맨 아래 팀원이 끈을 끊었다. 겨우.<br><br>넷은 계단에 쓰러졌다. 끈은 이쪽 허리에 묶인 채 위로 올라갔다. 위에서 외치는 소리가 났다. 지나간다. 짐 하나.<br>넷은 그 계단을 다시 오르지 않았다. 끈 끝을 아래에 묶어 두고 내려갔다. 혹시 짐이 돌아올지 몰라서.` },
      ok:`끈을 두 손으로 쥐었다. 내공을 팔과 다리로 나눴다. 당기지 않고 버텼다. 위가 당기는 만큼만.<br><br>위의 힘이 세지면 이쪽도 세졌다. 약해지면 약해졌다. 한참 그렇게 밀고 당겼다. 위가 먼저 지쳤다. 끈이 느슨해졌다.<br>그 틈에 맨 뒤 팀원 허리끈을 풀었다. 위에서 빈 끈이 감겨 올라갔다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A', t:'문 앞 — 통행세',
  x:`통로를 막은 문 앞에 목소리가 있다. 문 뒤에서 난다.<br><br>
    <span style="color:#8fb3bf;">"지나가려면 짐 하나."</span><br>
    산길의 통행세를 표사는 안다. 산적은 짐 하나를 받고 길을 연다. 대신 다음에 또 받는다. 한 번 내면 그 길은 그 산적의 길이 된다.<br><br>
    여기서 짐은 사람이다.`,
  o:[
    { l:'① 표호를 외치며 이 짐은 내줄 짐이 아니라고 못 박는다.', k:'bond', dc:23, wake:1,
      ok:`문 앞에 섰다. 외쳤다. 지나간다. 짐 다섯, 지키는 사람 하나. 이 짐에는 갈 곳이 있다. 세는 내지 않는다.<br><br>문 뒤가 조용해진다. 산적도 표호 앞에서 셈을 한다. 지키는 사람이 있는 짐을 빼앗으면 싸움이 된다. 싸움은 짐 하나보다 비싸다.<br>문이 열렸다. 저절로. 뒤에 아무도 없다. 지나가는데 문 뒤 어둠에서 낮게 말했다. 다음엔 둘.<br><br>세를 안 내는 법은 칼이 아니라 외침에 있다. 이 짐이 누구 것인지 먼저 말하면 길은 그 말을 듣는다. 표호가 겁주는 소리에서 길을 여는 소리가 됐다.`,
      ng:`외쳤는데 문 뒤에서 웃는다. 지키는 사람 하나. 그럼 그 하나를 내라.<br><br>문틈으로 손이 나와 이쪽 멱살을 잡았다. 팀원들이 떼어 냈다. 목에 손자국. 다른 길로 돌았다. 오래 걸렸다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-22, spirit:-28 } },
    { l:'② 사람 대신 내줄 짐을 골라 문 앞에 놓는다.', k:'luck', dc:22,
      ok:`배낭 하나를 문 앞에 놓았다. 짐 하나. 사람이라고 말한 적은 없다.<br><br>문 뒤에서 배낭을 끌어간다. 무게를 재는 소리. 오래. 그리고 문이 열렸다. 짐은 짐이다. 정확하게 말하지 않은 쪽이 손해다.<br>배낭 안에는 젖은 깔개와 빈 물통이 들어 있었다. 아깝지 않았다.`,
      ng:`놓았는데 문 뒤에서 배낭을 도로 밀어낸다. 이건 짐이 아니라고.<br><br>문이 꼼짝 않는다. 문 뒤에서 팀원 이름 하나를 부른다. 그 팀원 얼굴이 하얘졌다. 다 같이 다른 길로 뛰었다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-22, spirit:-20 } }
  ] },

{ at:'A', t:'어둠 속 — 대열 사이를 걷는 것',
  x:`대열을 짜서 걷는다. 앞에 이쪽, 가운데 셋, 뒤에 하나. 짐 지키는 대열이다.<br><br>
    걸음 소리가 여섯이다. 이쪽 발소리, 셋, 하나. 그리고 가운데 셋 사이에 하나 더. 맨발 소리.<br>
    대열 가운데에 무엇이 끼어 함께 걷는다. 짐인 척.<br><br>
    가운데 셋은 모른다. 서로 어깨를 붙이고 걷는다. 그중 하나의 어깨가 차다는 것도 모른다.`,
  o:[
    { l:'① 대열을 바꾸는 신호로 그것을 바깥으로 밀어낸다.', k:'fix', dc:23, wake:1,
      ok:`정한 신호를 외쳤다. 둘러싸기. 가운데 셋이 바깥으로 돈다. 등을 안으로, 얼굴을 밖으로.<br><br>대열이 뒤집혔다. 가운데가 비었다. 빈 가운데에 무엇이 혼자 남았다. 맨발 소리가 멈춘다. 숨을 데가 없다.<br>다섯이 그것을 둘러싼 꼴이 됐다. 그것이 낮게 울며 땅으로 꺼졌다. 다섯 다 등 뒤가 젖었다.<br><br>대열은 짐을 지키는 모양이자 짐 사이에 낀 것을 골라내는 모양이다. 대열을 뒤집는 신호 하나가 거름망이 된다. 걸음 대형을 바꾸는 법이 한 수 늘었다.`,
      ng:`외쳤는데 셋 중 둘만 돌았다. 하나가 그 자리에 서 있다. 차가운 어깨 옆에서.<br><br>그 하나가 대열에서 끌려 나간다. 어둠 쪽으로. 뛰어가 붙들었다. 팔 하나를 서로 당겼다. 이겼다. 팀원 팔에 맨손 자국이 하얗게 얼었다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-24, spirit:-26 } },
    { l:'② 내공을 귀로 모아 발소리 하나하나의 무게를 잰다.', k:'sense', dc:23, cost:{ qi:26 },
      ok:`내공을 귀로 모았다. 발소리가 갈린다. 무게가 다르다.<br><br>팀원 발소리는 지쳐서 뒤꿈치가 끌린다. 맨발 소리는 앞꿈치만 닿는다. 무게가 없다. 셋째와 넷째 사이다.<br>셋째 어깨를 짚어 한 걸음 앞으로 당겼다. 넷째는 뒤로. 사이가 벌어졌다. 맨발 소리가 끼어들 틈을 잃었다. 몇 걸음 더 따라오다 멈췄다.`,
      ng:`모은 내공 때문에 발소리가 너무 크다. 여섯이 다 같은 무게로 들린다.<br><br>못 가렸다. 귀가 울렸다. 걸음을 멈췄다. 다섯이 멈췄다. 맨발 소리가 한 걸음 더 갔다. 이쪽 바로 앞에서.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-22, spirit:-22 } }
  ] },

{ at:'A', t:'깊은 곳 — 짐을 놓으면 산다',
  x:`통로가 끝없이 길다. 팀원 둘이 지쳤다. 이쪽이 하나를 업었다. 하나는 어깨를 빌려 걷는다.<br><br>
    어둠 속에서 목소리가 말한다. 친절하다. 짐을 놓으면 너는 산다. 짐꾼은 짐이 없으면 빨리 간다.<br>
    맞는 말이다. 둘을 놓고 가면 셋은 빨리 간다.<br><br>
    산에서 그런 표사를 봤다. 짐을 놓고 혼자 내려온 사람. 그 사람은 다시는 짐을 못 졌다.`,
  o:[
    { l:'① 짐을 고쳐 매고 대답 대신 걸음을 낸다.', k:'steady', dc:23, wake:1,
      ok:`업은 팀원을 추슬러 고쳐 업었다. 어깨 빌린 팀원 팔을 더 깊이 걸었다. 걸었다.<br><br>목소리가 계속 말한다. 놓으면 산다. 대답하지 않았다. 걸음이 대답이다. 한 걸음, 또 한 걸음.<br>목소리가 지쳤다. 마지막으로 말했다. 바보. 그리고 조용해졌다. 통로 끝이 보였다.<br><br>짐을 놓으라는 말에는 걸음으로 대답한다. 그 걸음을 몇 번 하고 나니 짐이 덜 무겁다. 무게가 줄어든 게 아니라 등이 무게를 담는 모양이 바뀌었다.`,
      ng:`고쳐 업는데 어깨 빌린 팀원이 손을 뺐다. 짐이 되기 싫다고. 놓고 가라고.<br><br>그 팀원이 혼자 걷겠다며 앞서 걸었다. 비틀거린다. 쫓아가 다시 어깨를 걸었다. 셋이 같이 넘어졌다. 업힌 팀원 머리가 바닥에 부딪혔다.`,
      win:{ exp:24, dream:3, hp:6 }, lose:{ hp:-28, spirit:-24 } },
    { l:'② 짐을 내려놓는 척해 목소리를 속인다.', k:'hide', dc:24,
      doom:{ title:'내려놓은 척', what:'짐 대신 짐꾼이 어둠 속으로 끌려갑니다', dc:18, sec:50,
        text:`업은 팀원을 바닥에 내려놓았다. 놓는 척. 한 손은 그 팀원 허리띠를 쥔 채.<br><br>목소리가 반가워한다. 잘했어. 그리고 어둠 속에서 손이 나온다. 짐 쪽이 아니라 이쪽으로.<br>짐을 놓은 짐꾼은 짐이 아니다. 그냥 사람이다. 그냥 사람은 데려갈 수 있다. 손이 이쪽 발목을 쥔다.<br><br>쥐었던 허리띠가 손에서 빠진다. 몸이 어둠 쪽으로 끌린다.`,
        dieText:`팀원들이 통로 끝에 닿았을 때 넷이었다. 업혔던 팀원도 걸어서 왔다. 이쪽이 내려놓은 그 자리에서 일어나서.<br><br>등 뒤 통로에서 외치는 소리가 났다. 지나간다. 짐 없음.<br>그 소리가 아주 오래 통로를 오갔다. 짐을 찾는 짐꾼처럼.` },
      ok:`업은 팀원을 내려놓았다. 놓는 척. 허리띠를 쥔 채.<br><br>어둠 속에서 손이 나왔다. 이쪽 발목을 노린다. 그 순간 다시 업었다. 짐을 진 짐꾼이 됐다. 손이 멈춘다. 짐 진 사람은 못 데려간다.<br>손이 한참 이쪽 발목 앞에서 허공을 쥐었다 폈다 한다. 짐을 고쳐 업고 지나갔다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A', t:'쉬는 자리 — 저절로 기우는 표기',
  x:`쉬는 자리에 표기를 꽂았다. 막대에 붉은 천. 팀 이름 첫 글자를 숯으로 썼다. 짐이 모일 자리라는 표시.<br><br>
    바람이 없다. 그런데 표기가 기운다. 한쪽으로. 쉬는 자리 바깥 어둠 쪽으로.<br>
    표기는 짐이 가야 할 쪽을 가리킨다. 이쪽이 그렇게 정했다. 팀원들이 표기를 보고 일어선다.<br><br>
    그쪽 어둠에서 물 떨어지는 소리가 난다. 아주 일정하게.`,
  o:[
    { l:'① 표기가 기우는 반대쪽 길을 살핀다.', k:'gaze', dc:23,
      ok:`기우는 쪽 말고 반대쪽을 봤다. 천이 등지고 있는 쪽.<br><br>벽에 금이 있다. 바람이 아주 조금 새어 나온다. 진짜 바람은 이쪽에서 분다. 표기는 바람을 거슬러 기울고 있다. 무엇이 당기는 것이다.<br>반대쪽 금을 넓혀 지나갔다. 아래층으로 이어졌다. 표기는 두고 왔다. 표기가 가리키는 쪽에 무엇이 오래 기다릴 것이다.`,
      ng:`반대쪽을 보는데 아무것도 없다. 벽뿐이다.<br><br>그 사이 팀원 둘이 표기 쪽으로 걸어갔다. 이쪽이 정한 대로. 뒤쫓아 갔다. 어둠 가장자리에서 둘을 붙잡았다. 발밑이 물이다. 발목까지 차가운 물에 잠겼다. 그 물이 당긴다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-24, mind:-20 } },
    { l:'② 표기를 뽑아 짐 한가운데 다시 꽂고 그 아래 모은다.', k:'bond', dc:23, wake:1,
      ok:`표기를 뽑았다. 팀원들 한가운데 꽂았다. 천이 다시 기운다. 이번엔 사람 쪽으로 기울 데가 없다. 사방이 짐이다.<br><br>천이 한 번 펄럭이고 곧게 섰다. 둘러앉은 다섯 어깨가 표기를 받친다.<br>표기는 길을 가리키는 게 아니라 짐이 모이는 자리여야 한다. 이쪽이 처음 꽂을 때 잘못 정했다. 다시 정했다.<br><br>깃발을 사람들 바깥이 아니라 한가운데 꽂는 법. 깃발이 가리키는 데로 짐을 보내지 않고 깃발 아래로 짐을 모은다. 표기 다루는 손이 한 겹 깊어졌다.`,
      ng:`뽑는데 막대가 안 빠진다. 땅속에서 무엇이 쥐고 있다.<br><br>힘을 주다 막대가 부러졌다. 천이 바닥에 떨어져 어둠 쪽으로 미끄러져 간다. 혼자서. 잡으러 가지 않았다. 표기 없이 밤을 샜다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-22, spirit:-26 } },
    { l:'③ 물 떨어지는 소리 쪽을 내공으로 듣는다.', k:'sense', dc:22, cost:{ qi:25 },
      ok:`내공을 귀로 모았다. 물소리가 가까워진다. 물이 아니다. 떨어지는 것은 물방울인데 떨어지는 데가 바닥이 아니다. 무엇의 손바닥이다.<br><br>손바닥에 물을 받으며 기다리는 것이 있다. 손바닥이 차면 마시러 오는 것이다. 마시러 올 때 쉬는 자리를 지난다.<br>그 전에 자리를 옮겼다. 물소리가 그친 것은 한참 뒤였다.`,
      ng:`듣는데 물소리가 귀 안으로 들어온다. 이쪽 귀에서 물이 떨어진다.<br><br>고개를 털었다. 물이 안 나온다. 소리만 난다. 그 소리가 밤새 이쪽 머릿속에서 떨어졌다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-20, spirit:-24 } }
  ] },

{ at:'A1', t:'입장문 — 어린이 줄과 보호자 줄',
  x:`방청객 입장문 앞에 줄이 둘이다. 바닥에 테이프로 그었다. 왼쪽 어린이. 오른쪽 보호자.<br><br>
    어린이 줄 끝에 문이 있다. 활짝 열렸다. 안에서 박수가 새어 나온다.<br>
    보호자 줄 끝에는 의자가 놓였다. 대기석. 문이 없다. 보호자는 밖에서 기다리는 줄이다.<br><br>
    하얀 장갑이 테이프 옆에 서서 팀원들 등을 왼쪽으로 민다. 키가 작은 순서대로.`,
  o:[
    { l:'① 짐을 갈라 세우지 않고 다섯을 다 보호자 줄로 끌고 간다.', k:'bond', dc:23, wake:1,
      ok:`장갑이 미는 팀원 손목을 잡아 오른쪽으로 당겼다. 다섯을 다 보호자 줄에 세웠다. 이쪽이 맨 앞에.<br><br>장갑이 이쪽 앞을 막는다. 손가락으로 왼쪽을 가리킨다. 이쪽이 장갑 손가락을 쥐고 다섯을 가리켰다. 이 짐은 이쪽이 데리고 온 짐이다. 짐은 짐꾼과 같은 줄에 선다.<br>장갑이 오래 망설인다. 그리고 다섯 다 대기석으로 손짓했다. 대기석 뒤에 직원 통로가 있었다. 그리로 빠졌다.<br><br>짐을 분류하는 손 앞에서 짐을 한 묶음으로 우기는 법. 갈라 세우면 하나씩 빼앗긴다. 묶어 두면 통째로 지킨다. 그 고집이 기술이 됐다.`,
      ng:`당기는데 장갑이 더 세다. 팀원 하나가 왼쪽 테이프를 넘었다.<br><br>박수가 커진다. 그 팀원 몸이 입장문 쪽으로 기운다. 셋이 달려들어 허리를 붙들었다. 테이프 안쪽으로 끌어냈다. 그 팀원 발이 테이프 너머에 있던 동안 신발이 젖었다. 박수에 젖은 것처럼.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-22, spirit:-28 } },
    { l:'② 줄을 서지 않고 테이프 밖 벽을 따라 돌아간다.', k:'hide', dc:22,
      ok:`줄 밖으로 빠졌다. 벽에 붙어 돌았다. 장갑이 줄만 본다. 줄 밖 사람은 셀 수 없다.<br><br>입장문 옆을 지날 때 박수가 이쪽 귀에 바싹 붙었다. 돌아보지 않았다.<br>계단에 닿았다. 테이프 위에 발자국이 다섯 남아 있었다. 이쪽 팀 신발 크기로. 아무도 안 밟았는데.`,
      ng:`돌아가는데 막내가 테이프를 밟았다. 왼쪽 선을.<br><br>장갑이 바로 막내 등을 민다. 막내가 입장문 쪽으로 미끄러진다. 붙잡아 끌어당겼다. 막내 등에 하얀 장갑 자국이 남았다. 지워지지 않는다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, spirit:-24 } }
  ] },

{ at:'A1', t:'의상실 — 옷걸이 레일',
  x:`의상실 천장에 레일이 지나간다. 옷걸이가 줄줄이 매달려 레일을 따라 움직인다. 아주 천천히.<br><br>
    팀원 하나의 겉옷 깃이 옷걸이에 걸렸다. 발끝이 바닥에서 뜬다. 레일을 따라 실려 간다.<br>
    레일 끝은 벽 구멍이다. 그 구멍으로 옷걸이들이 들어간다. 그리고 다른 옷을 걸고 나온다. 인형탈 옷.<br><br>
    실려 가는 짐을 표사는 그냥 보지 않는다.`,
  o:[
    { l:'① 내공을 실어 레일을 두 손으로 붙잡아 멈춘다.', k:'steady', dc:24, cost:{ qi:30 },
      doom:{ title:'옷걸이 레일', what:'옷걸이에 걸려 레일 끝 구멍으로 실려 갑니다', dc:19, sec:45,
        text:`뛰어올라 레일을 두 손으로 쥐었다. 내공을 팔에 모았다. 레일이 멈칫한다.<br><br>그런데 레일이 멈추지 않는다. 옷걸이들이 이쪽 쪽으로 몰려온다. 줄줄이. 맨 앞 옷걸이가 이쪽 겉옷 깃을 건다.<br>이쪽도 걸렸다. 손을 놓으면 떨어지지 않는다. 깃에 걸려 매달린다. 레일이 다시 움직인다. 팀원과 이쪽이 나란히 실려 간다. 벽 구멍이 가깝다.<br><br>밑에서 팀원들이 다리를 붙든다.`,
        dieText:`벽 구멍에서 옷걸이 둘이 나왔다. 인형탈 옷 두 벌을 걸고.<br><br>한 벌은 갈색 털이다. 한 벌은 처음 보는 탈이다. 등에 붉은 천 조각이 꿰매져 있다. 숯으로 쓴 글자 하나. 팀 이름 첫 글자.<br>레일 끝 옷걸이에 걸린 그 탈은 가끔 손을 들어 외치는 모양을 한다. 소리는 안 난다.` },
      ok:`뛰어올라 레일을 쥐었다. 내공을 팔에 모아 레일을 비틀었다. 레일 이음새가 벌어졌다.<br><br>옷걸이들이 이음새에서 멈춘다. 넘어가지 못한다. 팀원 옷걸이도 멈췄다. 팀원을 내려 깃을 찢어 빼냈다.<br>레일 끝 구멍에서 무엇이 기다리다 소리를 냈다. 실망한 숨소리. 이음새 앞에서 옷걸이들이 밀려 덜컹거렸다.`,
      win:{ exp:24, dream:3 } },
    { l:'② 레일 끝 구멍 앞에 먼저 가서 막는다.', k:'fix', dc:23,
      ok:`레일을 따라 앞질러 뛰었다. 벽 구멍 앞에 의상 상자를 쌓아 올렸다. 구멍이 막혔다.<br><br>옷걸이들이 상자에 걸려 멈춘다. 팀원 옷걸이도 상자 앞에서 섰다. 내렸다.<br>상자 너머 구멍 안쪽에서 무엇이 상자를 민다. 상자 위에 팀원 셋이 올라앉아 버텼다. 그 사이 의상실을 빠져나왔다.`,
      ng:`쌓는데 상자가 모자라다. 구멍이 반만 막혔다.<br><br>팀원 옷걸이가 반쯤 남은 틈으로 들어간다. 다리가 먼저. 뛰어가 팀원 허리를 안았다. 겉옷이 찢어지며 팀원이 빠져나왔다. 겉옷만 구멍으로 들어갔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-18 } }
  ] },

{ at:'A1', t:'방청석 — 손에서 손으로',
  x:`방청석에서 팀원 하나가 들렸다. 빈 의자들에서 하얀 장갑들이 올라와 팀원을 받쳐 든다.<br><br>
    손에서 손으로 넘긴다. 무대 쪽으로. 팀원은 누운 채 실려 간다. 버둥거릴수록 손이 늘어난다.<br>
    실려 가는 짐을 쫓는 건 표사가 늘 하는 일이다. 다만 산적은 짐을 이렇게 다정하게 들지 않는다.<br><br>
    무대까지 의자 열두 줄.`,
  o:[
    { l:'① 의자 등받이를 밟고 뛰어 짐을 앞질러 막는다.', k:'evade', dc:23,
      ok:`의자 등받이를 밟고 뛰었다. 한 줄, 두 줄. 손들 위를 넘어 앞질렀다.<br><br>무대 바로 앞 줄에서 돌아섰다. 넘어오는 팀원을 이쪽이 받았다. 손들이 이쪽 팔에 팀원을 건넨다. 이쪽도 손이니까.<br>받은 채로 방청석 통로로 뛰어내렸다. 손들이 허공을 더듬다 하나씩 의자로 가라앉았다.`,
      ng:`등받이 하나가 접혔다. 발이 빠졌다. 의자 사이에 끼었다.<br><br>팀원이 머리 위로 지나간다. 손 하나가 이쪽 머리를 쓰다듬고 지나간다. 다리를 빼는 데 한참. 팀원은 무대 턱 앞에서 다른 팀원들이 겨우 끌어내렸다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, spirit:-20 } },
    { l:'② 내공을 실어 표호를 외쳐 손들을 멈춘다.', k:'bond', dc:23, cost:{ qi:28 }, wake:1,
      ok:`단전에서 끌어올려 외쳤다. 지나간다. 이 짐에는 주인이 있다. 손대지 마라.<br><br>방청석이 얼어붙었다. 손들이 팀원을 든 채 멈춘다. 이 방청석에서 큰 소리는 박수뿐이었다. 박수 아닌 큰 소리는 처음이다.<br>손들이 팀원을 천천히 내려놓았다. 의자 위에. 그리고 의자 밑으로 사라졌다. 팀원이 떨며 일어났다.<br><br>남의 판에서 남의 박자 대신 이쪽 외침을 박아 넣는 법. 표호가 길 위만이 아니라 방 안에서도 통한다. 소리가 닿는 데까지가 이쪽 길이다. 외침의 길이가 늘었다.`,
      ng:`외쳤는데 방청석이 박수로 받는다. 크게. 이쪽 외침이 무대 소리로 들렸다.<br><br>손들이 더 빨라진다. 팀원이 무대 턱까지 갔다. 다 같이 뛰어가 다리를 잡아당겼다. 무대 위로 손 하나만 올라갔다. 팀원 신발 한 짝이 무대 위에 남았다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-22, spirit:-28 } },
    { l:'③ 손들 사이로 줄을 던져 팀원 허리에 건다.', k:'fix', dc:23,
      ok:`허리 줄을 풀어 고리를 지었다. 던졌다. 팀원 허리에 걸렸다.<br><br>당겼다. 손들이 넘기는 방향과 반대로. 팀원이 손에서 손으로 넘어가다 줄에 걸려 멈춘다. 손들이 더 당길수록 줄이 조인다.<br>손들이 놓았다. 팀원이 의자 사이로 떨어졌다. 줄을 감아 끌어왔다.`,
      ng:`던졌는데 줄이 손 하나에 걸렸다. 그 손이 줄을 쥔다.<br><br>손이 이쪽을 끌어당긴다. 방청석 위로. 줄을 놓았다. 줄이 손에서 손으로 넘어간다. 팀원은 결국 셋이 무대 앞에서 붙잡아 끌어내렸다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-26, mind:-18 } }
  ] },

{ at:'A1', t:'소품 냉장고 — 촬영용 음식',
  x:`소품실 구석에 냉장고가 있다. 문틈으로 차가운 빛이 샌다. 전기가 끊긴 건물인데.<br><br>
    안에 접시가 줄지어 있다. 요리 코너 소품. 플라스틱 음식이 반, 진짜가 반. 진짜 쪽은 시들지도 썩지도 않았다.<br>
    팀은 먹을 게 떨어졌다. 짐을 지키는 사람은 짐이 먹을 것도 챙긴다.<br><br>
    냉장고 맨 아래 칸이 비었다. 사람 하나 웅크려 들어갈 만하다. 서리에 손자국이 있다.`,
  o:[
    { l:'① 내공으로 냄새를 갈라 진짜 먹을 것만 고른다.', k:'sense', dc:23, cost:{ qi:25 },
      ok:`숨을 고르고 내공을 코로 모았다. 냉장고 안 냄새가 갈린다. 플라스틱 냄새. 서리 냄새. 그리고 흙냄새.<br><br>흙냄새 나는 접시를 꺼냈다. 산나물 무침이다. 촬영 전에 진짜로 무쳐 둔 것. 소금기가 아직 있다.<br>문을 닫는데 맨 아래 칸에서 손이 서리를 긁는 소리가 났다. 다시 열지 않았다.`,
      ng:`모은 내공이 찬 공기에 얼어붙었다. 코가 마비됐다.<br><br>손으로 더듬어 고르다 맨 아래 칸에 손이 들어갔다. 서리 속에서 무엇이 손가락을 쥐었다. 뺐다. 손가락 셋이 동상이다.`,
      win:{ exp:18, dream:2, item:'산나물' }, lose:{ hp:-24, spirit:-20 } },
    { l:'② 먹을 것을 포기하고 냉장고 문을 닫아 기댄다.', k:'steady', dc:22,
      ok:`문을 닫았다. 등을 기대 막았다. 팀원들에게 마른 것을 나눴다. 반씩.<br><br>등 뒤에서 냉장고 문이 몇 번 밀렸다. 안에서. 기댄 채로 버텼다.<br>배는 덜 찼다. 대신 맨 아래 칸에 아무도 안 들어갔다.`,
      ng:`닫는데 문이 안 닫힌다. 맨 아래 칸에서 손이 문을 받치고 있다.<br><br>밀었다. 손가락이 문틈에 끼었다. 그 손가락이 이쪽 신발 끝을 쥐었다. 신발을 벗어 버리고 물러났다. 냉장고 문이 천천히 닫혔다. 신발을 안에 들인 채.`,
      win:{ exp:15, dream:2 }, lose:{ hp:-22, mind:-20 } }
  ] },

{ at:'A1', t:'무대 옆 통로 — 줄 선 인형탈들',
  x:`무대 옆 통로에 인형탈들이 줄을 섰다. 입장 순서를 기다린다. 열 남짓.<br><br>
    그 줄 옆을 지나야 송출 부스 계단이다. 통로가 좁다. 탈들 어깨를 스치며 지나야 한다.<br>
    탈들은 지나가는 사람을 하나씩 본다. 그리고 손을 내민다. 같이 서자는 손. 줄이 하나씩 길어지는 걸로 안다.<br><br>
    줄을 지날 때는 대열을 짠다. 짐을 지키는 사람이 늘 하는 일이다.`,
  o:[
    { l:'① 짐을 벽 쪽에, 이쪽을 탈 쪽에 세우는 대열로 지난다.', k:'bond', dc:23, wake:1,
      ok:`팀원 넷을 벽에 붙였다. 한 줄로. 이쪽은 넷과 탈들 사이에 섰다. 옆걸음으로 같이 갔다.<br><br>탈들이 손을 내민다. 이쪽 어깨에 닿는다. 넷에게는 안 닿는다. 이쪽이 벽이다. 손 열이 이쪽 어깨와 팔을 쓸고 지나간다.<br>통로 끝에서 대열을 풀었다. 이쪽 어깨에 하얀 털이 잔뜩 붙었다. 털어 내도 다시 붙는다.<br><br>짐과 위험 사이에 이쪽 몸을 한 줄로 세우는 대열. 산에서 쓰던 대열을 통로 너비에 맞게 줄였다. 몸이 어디에 서야 하는지 통로를 보자마자 안다.`,
      ng:`세우는데 통로가 생각보다 좁다. 이쪽 어깨가 탈 하나 손에 걸렸다.<br><br>그 탈이 이쪽 팔을 끼고 줄에 세우려 한다. 팔을 비틀어 뺐다. 그 사이 대열이 흐트러져 팀원 하나가 탈들 쪽으로 밀렸다. 붙잡았다. 둘이 같이 벽에 부딪혔다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-24, spirit:-26 } },
    { l:'② 탈들 앞에서 낮게 표호를 내고 기다린다.', k:'steady', dc:23,
      ok:`낮게 외쳤다. 지나간다. 짐 다섯. 줄에 설 짐은 없다.<br><br>탈들이 일제히 이쪽을 돌아본다. 그리고 손을 거둔다. 줄은 입장 순서다. 순서에 없는 짐은 안 받는다.<br>지나갔다. 맨 끝 탈만 손을 늦게 거뒀다. 그 손이 막내 머리를 한 번 쓰다듬었다.`,
      ng:`외쳤는데 탈들이 그걸 입장 신호로 들었다. 줄이 앞으로 한 칸 움직인다.<br><br>맨 뒤 탈이 이쪽 팀 막내 손을 잡고 같이 움직인다. 떼어 냈다. 막내 손에 탈 장갑 하나가 벗겨져 남았다. 장갑 안이 따뜻했다.`,
      win:{ exp:16, dream:2 }, lose:{ mind:-22, spirit:-22 } }
  ] },

{ at:'A2', t:'물 위 — 배에 실은 짐',
  x:`나무배에 다섯이 탔다. 노는 하나. 종탑까지 물이 평평하다. 안개가 수면에 얹혔다.<br><br>
    배가 기운다. 한쪽으로. 아무도 움직이지 않았다. 뱃전 밖에서 무엇이 손을 걸었다.<br>
    배 가장자리에 앉은 팀원 둘 쪽이다. 가장자리 짐이 제일 먼저 떨어진다. 수레에서도 배에서도.<br><br>
    배는 짐을 나르는 수레다. 수레에는 싣는 법이 있다.`,
  o:[
    { l:'① 짐을 배 한가운데로 모아 앉히고 이쪽이 뱃전에 앉는다.', k:'bond', dc:23, wake:1,
      ok:`가장자리 둘을 가운데로 당겼다. 다섯을 배 한가운데 몰아 앉혔다. 이쪽이 기운 뱃전에 앉았다. 노를 쥐고.<br><br>뱃전의 손이 이쪽 옷자락을 더듬는다. 짐이 아니라 짐꾼이 앉은 걸 안다. 짐꾼은 짐보다 무겁다. 손이 한참 버티다 놓았다. 배가 바로 섰다.<br>종탑에 닿을 때까지 이쪽 옷자락이 젖어 있었다. 뱃전 쪽만.<br><br>싣는 법을 물 위로 옮겼다. 무게를 가운데, 지키는 사람을 가장자리. 수레든 배든 같다. 짐을 앉히는 손이 어디서든 같은 모양을 짓는다.`,
      ng:`모으는데 배가 더 기운다. 무게가 한쪽으로 몰렸다.<br><br>뱃전으로 물이 넘어 들어온다. 손이 넘어 들어온 물을 타고 배 안으로 들어왔다. 팀원 발목을 쥐었다. 노로 내리쳤다. 손이 물러났다. 노가 갈라졌다.`,
      win:{ exp:24, dream:3 }, lose:{ hp:-26, spirit:-24 } },
    { l:'② 내공을 실어 노를 저어 종탑에 빨리 닿는다.', k:'steady', dc:23, cost:{ qi:28 },
      ok:`내공을 팔로 내렸다. 노를 깊이 넣어 저었다. 배가 미끄러진다.<br><br>뱃전의 손이 따라온다. 그러다 떨어진다. 빠른 배는 붙잡기 어렵다. 종탑 창에 뱃머리가 닿았다.<br>팔이 후들거린다. 내공이 바닥이다. 그래도 다섯이 창을 넘었다.`,
      ng:`젓는데 노가 물속에서 무엇에 걸렸다. 무엇이 노를 쥐었다.<br><br>당겨도 안 빠진다. 노를 놓을 수는 없다. 배가 빙빙 돈다. 팀원들이 손으로 물을 저어 겨우 종탑에 붙었다. 노는 물 밑으로 갔다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-28, mind:-16 } }
  ] },

{ at:'A2', t:'기숙사 — 침대를 세는 밤',
  x:`기숙사 빈 호실에서 밤을 난다. 침대가 열둘. 다섯이 하나씩 눕는다. 이쪽은 문 앞.<br><br>
    밤 아홉 시가 지나고 복도에서 발소리가 난다. 사감이 아니다. 더 작다. 호실마다 들어가 침대를 센다. 소리 내어.<br>
    하나, 둘. 빈 침대는 건너뛴다. 사람 누운 침대만 센다.<br><br>
    센 침대에는 다음 날 아침 명찰이 놓인다고 벽에 적혀 있다.`,
  o:[
    { l:'① 다섯 침대에 표기 천을 덮어 짐 표시를 한다.', k:'fix', dc:23, wake:1,
      ok:`붉은 천을 다섯 조각으로 찢었다. 팀원들 이불 위에 하나씩 덮었다. 숯으로 쓴 글자 하나. 팀 이름 첫 글자. 이 짐은 임자가 있다는 표시.<br><br>발소리가 호실에 들어온다. 침대 사이를 걷는다. 붉은 천 앞에서 멈춘다. 오래. 그리고 건너뛴다. 임자 있는 짐은 세지 않는다. 남의 짐을 세는 건 도둑질이니까.<br>아침에 명찰은 없었다. 붉은 천 위에 작은 젖은 손자국만 하나씩.<br><br>표기가 길 위의 깃발만이 아니라 잠든 짐 위의 덮개가 될 수 있다. 이쪽 표시를 짐에 덮는 법이 한 가지 더 늘었다. 천 다섯 조각이 이쪽 깃발이 됐다.`,
      ng:`덮는데 천이 모자란다. 네 조각.<br><br>다섯째 침대가 맨 이불이다. 발소리가 그 침대 앞에서 멈췄다. 하나. 그 팀원이 잠결에 대답했다. 응. 아침에 그 침대 머리맡에 명찰이 놓여 있었다. 그 팀원 이름이 수놓여 있다.`,
      win:{ exp:24, dream:3 }, lose:{ mind:-22, spirit:-28 } },
    { l:'② 문 앞에 앉아 밤새 발소리를 들이지 않는다.', k:'steady', dc:23,
      ok:`문 앞에 등을 대고 앉았다. 발소리가 문 앞에 왔다. 문고리가 돌아간다. 등으로 막았다.<br><br>문틈으로 작은 목소리가 셌다. 하나. 이쪽을. 문 밖에서 보이는 건 이쪽뿐이다. 이쪽은 짐꾼이다. 침대가 아니다.<br>발소리가 다음 호실로 갔다. 아침까지 등이 문에 붙어 있었다.`,
      ng:`앉았는데 졸았다. 깼을 때 문이 조금 열려 있다.<br><br>안에서 세는 소리. 셋, 넷. 뛰어 들어가 불을 켰다. 아무도 없다. 침대 넷 머리맡에 젖은 자국. 넷째와 다섯째 사이에서 세는 소리가 멈췄다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-22, mind:-20 } }
  ] },

{ at:'A2', t:'식당 — 앉혀지는 짐',
  x:`식당 식탁에 식판이 차려졌다. 물에 반쯤 잠겼다. 자리마다 이름표.<br><br>
    팀원 하나가 식탁 사이를 지나다 멈췄다. 의자가 저절로 빠지며 그 팀원 무릎 뒤를 친다. 앉으라고.<br>
    팀원 무릎이 꺾인다. 앉으면 배식 줄 아이들이 그 자리에 식판을 놓는다. 다 먹을 때까지 못 일어난다고 벽에 적혀 있다.<br><br>
    다 먹은 아이는 아무도 없다.`,
  o:[
    { l:'① 내공을 실어 의자째 팀원을 끌어낸다.', k:'bond', dc:24, cost:{ qi:30 },
      doom:{ title:'배식 줄', what:'식탁 자리로 끌려가 앉혀집니다', dc:19, sec:45,
        text:`의자 등받이를 쥐었다. 내공을 팔에 모아 뒤로 당겼다. 팀원이 의자째 끌려 나온다.<br><br>그런데 식탁 옆 다른 의자가 빠진다. 이쪽 무릎 뒤를 친다. 무릎이 꺾였다. 내공을 팔에 다 썼다. 다리에 남은 게 없다.<br>앉았다. 식판이 놓였다. 젖은 숟가락이 손에 쥐어진다. 손이 저절로 숟가락을 든다.<br><br>팀원들이 이쪽 어깨를 잡아당긴다. 엉덩이가 의자에서 안 떨어진다.`,
        dieText:`팀원들이 식당을 나올 때 식탁 한 자리에 이쪽이 앉아 있었다.<br><br>숟가락을 들고 있다. 먹지는 않는다. 식판을 지키듯 두 팔로 감쌌다.<br>그 자리 이름표에 이쪽 이름이 적혔다. 그 옆자리에도 이름이 하나 더 적혀 있다. 아까 끌어낸 팀원 이름. 지워져 있다. 이쪽 손톱으로.` },
      ok:`의자 등받이를 쥐었다. 내공을 팔과 다리에 반씩 나눴다. 뒤로 당겼다. 팀원이 의자째 끌려 나온다.<br><br>옆 의자가 빠지며 이쪽 무릎 뒤를 친다. 다리에 남겨 둔 내공이 버텼다. 무릎이 안 꺾였다.<br>팀원을 의자에서 뜯어냈다. 식당을 나올 때 식탁의 빈 의자들이 일제히 뒤로 빠져 있었다. 기다리는 모양으로.`,
      win:{ exp:24, dream:3 } },
    { l:'② 이쪽 식량을 식판에 올려 그 자리를 대신 채운다.', k:'luck', dc:23,
      ok:`팀원이 앉기 전에 말린 고기를 꺼내 그 자리 식판에 올렸다. 다 먹은 식판처럼 깨끗이.<br><br>의자가 멈췄다. 빈 식판이 아니다. 먹을 게 놓였으니 먹을 사람이 왔던 자리다. 의자가 스스로 식탁 밑으로 들어갔다.<br>팀원이 일어섰다. 식탁 밑 물속에서 무엇이 말린 고기를 집어 가는 소리가 났다. 처음 먹어 보는 맛인 듯 오래 씹었다.`,
      ng:`올렸는데 식판이 말린 고기를 거부했다. 물속으로 미끄러뜨렸다.<br><br>의자가 다시 친다. 팀원이 반쯤 앉았다. 다 같이 들어 올렸다. 팀원 엉덩이가 의자에서 떨어질 때 쩍 하는 소리가 났다. 바지가 찢어졌다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-24, spirit:-20 } },
    { l:'③ 팀원 앞을 막고 식탁 사이를 대열로 빠진다.', k:'steady', dc:23,
      ok:`팀원 앞에 섰다. 의자와 팀원 사이. 의자가 이쪽 무릎을 친다. 이쪽은 앉을 생각이 없다. 버텼다.<br><br>다섯이 한 줄로 식탁 사이를 빠졌다. 이쪽이 매번 의자 쪽에 섰다. 의자들이 차례로 이쪽 무릎을 친다. 열두 번.<br>식당을 나왔을 때 무릎이 다 멍투성이였다. 그래도 서 있었다.`,
      ng:`막는데 의자가 이쪽 무릎 뒤가 아니라 팀원 무릎 뒤로 돌아갔다. 이쪽을 비켜서.<br><br>팀원이 앉았다. 식판이 놓였다. 다 같이 들어 올리는데 팀원 손이 숟가락을 놓지 않는다. 숟가락째 끌고 나왔다. 그 숟가락은 아직 그 팀원 손에 있다.`,
      win:{ exp:16, dream:2 }, lose:{ hp:-28, mind:-16 } }
  ] },

{ at:'A2', t:'물 밑 계단 — 짐을 지고 잠수',
  x:`아래층으로 가는 계단이 물에 잠겼다. 다음 공기 고인 데까지 숨 한 번으로 가야 한다.<br><br>
    팀원 하나가 다쳤다. 숨이 짧다. 혼자서는 못 간다.<br>
    짐을 지고 물에 드는 일은 산에서는 없었다. 그래도 짐은 짐이다. 지고 간다.<br><br>
    계단 아래 물속이 어둡다. 손 같은 물풀이 계단 난간을 감고 흔들린다.`,
  o:[
    { l:'① 팀원을 등에 업고 숨을 나눠 주며 내려간다.', k:'bond', dc:24, wake:1,
      ok:`팀원을 등에 업고 허리를 묶었다. 크게 숨을 들이켜고 잠겼다. 계단을 짚으며 내려갔다.<br><br>중간쯤에서 팀원이 이쪽 어깨를 두드린다. 숨이 다 됐다. 돌아서 입을 맞대고 이쪽 숨을 반 나눠 줬다. 둘 다 반 숨이 됐다. 그 반 숨으로 계단을 마저 내려갔다.<br>난간의 물풀이 발목을 스친다. 걸음을 멈추지 않았다. 공기 고인 데에 둘이 같이 떠올랐다.<br><br>짐에게 이쪽 숨을 나눠 주는 일. 진 무게만이 아니라 숨까지 나눠 지는 법. 반 숨으로도 둘이 간다는 걸 폐가 기억했다.`,
      ng:`숨을 나눠 주려 돌아서는데 물풀이 이쪽 발목을 감았다. 손 모양으로.<br><br>숨이 다 빠졌다. 발목을 차서 풀었다. 둘이 물을 먹으며 떠올랐다. 공기 고인 데에서 한참 기침을 했다. 팀원은 기절해 있었다. 가슴을 눌렀다. 깨어났다.`,
      win:{ exp:25, dream:4 }, lose:{ hp:-32, spirit:-24 } },
    { l:'② 줄을 매고 이쪽이 먼저 내려가 줄을 당겨 끌어 준다.', k:'fix', dc:23,
      doom:{ title:'물 밑 계단', what:'줄을 잡은 채 계단 아래 물속으로 끌려 내려갑니다', dc:19, sec:45,
        text:`허리에 줄을 매고 먼저 잠겼다. 계단을 내려간다. 줄이 뒤로 풀린다.<br><br>중간쯤에서 줄이 무거워졌다. 앞에서. 물 밑 어둠에서 무엇이 줄을 쥐었다. 이쪽 허리에 묶인 줄을. 이쪽 앞쪽 끝을.<br>줄은 하나인데 끝이 셋이 됐다. 이쪽 허리, 위의 팀원, 아래의 무엇. 아래가 당긴다. 이쪽이 가운데서 끌린다.<br><br>숨이 반 남았다. 줄을 끊으면 위의 팀원과도 끊긴다.`,
        dieText:`위의 팀원들이 줄을 당겼다. 줄이 한참 버티다 확 가벼워졌다.<br><br>끌어올린 줄 끝은 매듭째였다. 풀린 자국이 없다. 허리가 매듭에서 빠져나간 것이다.<br>그 계단은 그 뒤로 가끔 물 위로 거품이 올라온다. 일정하게. 짐을 진 사람이 숨을 고르는 박자로.` },
      ok:`허리에 줄을 매고 먼저 잠겼다. 계단을 내려가 공기 고인 데에 닿았다. 줄을 세 번 당겼다.<br><br>위에서 다친 팀원이 줄을 잡고 잠긴다. 당겼다. 끌어당겼다. 물풀이 줄을 감으려 한다. 줄이 빨라서 못 감는다.<br>팀원이 떠올랐다. 숨을 몰아쉰다. 줄 중간에 물풀 한 줌이 얽혀 따라 올라왔다. 손가락 모양이었다.`,
      win:{ exp:22, dream:3 } }
  ] },

{ at:'A2', t:'강당 — 짐을 넘겨받겠다는 사감',
  x:`강당 무대 앞에 사감이 섰다. 출석부를 펼쳤다. 이쪽 팀 이름 다섯이 적혀 있다.<br><br>
    사감이 손을 내민다. 인계받겠다고. 학생은 학교가 맡는다고. 보호자는 이제 가도 된다고. 고생했다고.<br>
    부드러운 목소리다. 짐을 넘기는 자리 같다. 짐꾼은 짐을 넘기는 자리에서 늘 마음이 놓인다.<br><br>
    그런데 짐은 받을 사람에게만 넘긴다. 받을 사람이 누구인지는 짐꾼이 정하지 않는다. 짐이 정한다.`,
  o:[
    { l:'① 인계를 거절하고 짐에게 갈 곳을 직접 묻는다.', k:'bond', dc:24, wake:1,
      ok:`사감 손을 잡지 않았다. 팀원들을 돌아봤다. 하나씩 물었다. 어디로 가느냐고.<br><br>다섯이 다 대답했다. 집. 사감이 내민 손이 허공에 멈춘다. 받을 곳이 정해진 짐은 중간에서 받을 수 없다.<br>사감 출석부의 다섯 이름이 한 줄씩 지워진다. 물에 녹듯이. 그 사이 팀원 하나가 종줄을 당겼다. 종이 울렸다.<br><br>짐을 넘기는 자리에서 짐에게 직접 묻는 법. 짐꾼은 받는 쪽 손이 아니라 짐의 목적지를 믿는다. 그 물음 하나로 남의 출석부에서 이름 다섯을 빼냈다.`,
      ng:`물었는데 팀원 하나가 대답을 못 한다. 머뭇거린다. 집이 어디였는지 잠깐 잊었다.<br><br>사감 손이 그 팀원 어깨에 얹힌다. 인계 완료. 다 같이 달려들어 떼어 냈다. 그 팀원 어깨가 하얗게 얼었다. 종을 칠 때까지 그 팀원은 집 주소를 중얼거렸다.`,
      win:{ exp:25, dream:4 }, lose:{ mind:-22, spirit:-30 } },
    { l:'② 사감 앞을 지나 곧장 종줄을 당긴다.', k:'break', dc:23,
      ok:`대답 대신 뛰었다. 사감 옆을 스쳐 무대로. 종줄을 쥐고 당겼다.<br><br>종이 운다. 사감 손이 허공에서 멈췄다. 하교 종이 울리면 인계는 끝난다. 학생은 집에 간다.<br>사감이 출석부를 덮었다. 고개를 숙였다. 인사하는 것처럼. 그리고 물속으로 가라앉았다.`,
      ng:`뛰는데 사감 손이 이쪽 소매를 잡았다. 보호자는 무대에 오르면 안 된다고.<br><br>소매를 찢고 무대에 올랐다. 손목에 찬 손자국이 남았다. 종줄을 당길 때 그 손목이 떨렸다. 종소리가 반 박자 늦었다.`,
      win:{ exp:18, dream:2 }, lose:{ hp:-30, spirit:-20 } },
    { l:'③ 인수증을 달라고 하고 사감 글씨를 본다.', k:'gaze', dc:23,
      ok:`인계하려면 인수증이 있어야 한다고 했다. 받은 사람 이름과 날짜.<br><br>사감이 출석부 한 장을 찢어 적는다. 받은 사람 칸에 사감 이름. 날짜 칸에 잠기던 날.<br>그 날짜면 이미 지난 일이다. 지난 날짜로는 오늘 짐을 못 받는다. 인수증을 돌려줬다. 사감이 그 종이를 오래 봤다. 그리고 비켜섰다.`,
      ng:`글씨를 보는데 사감이 받은 사람 칸에 이쪽 이름을 쓴다. 보호자 인수.<br><br>이쪽이 짐이 됐다. 다리가 무겁다. 팀원들이 이쪽 팔을 끌고 종줄까지 갔다. 이쪽 몸이 사감 쪽으로 계속 기울었다.`,
      win:{ exp:18, dream:2 }, lose:{ mind:-22, spirit:-24 } }
  ] },

]);
